GimCorpus.put(365,0,[[1,1,"כל הפסולים לעבודה וכו' עד הזבח כשר. משנה וגמרא בפרק כל הפסולין (זבחים דף ל״א ל״ב:):",1,0],[1,2,"ומ\"ש וכן פר כהן גדול של יום הכפורים וכו' אף פרה אדומה ששחטה זר כשירה. בפרק טרף בקלפי (יומא דף מ\"ב) אתמר שחיטת פרה (אדומה) ופרו וכו' חד אמר פרה פסולה ופרו כשירה וחד אמר פרו פסולה ופרה כשירה ובתר הכי (דף מ\"ג:) אמרינן תני תנא קמיה דר\"י כל השחיטות כשירות בזר חוץ משל פרה א\"ל ר\"י פוק תני לברא לא מצינו שחיטה בזר פסולה ור\"י ל\"מ לתנא דלא ציית אלא אפי' לרביה לא ציית דאמר ר\"י משום ר\"ש בן יהוצדק שחיטת פרה בזר פסולה ואני אומר כשירה לא מצינו שחיטה שפסולה בזר. ופסק רבינו כר\"י משום דלגבי פרו הלכה כרב באיסורי ועוד דה\"ל רב ור\"י תרי לגבי שמואל ולגבי פרה ה\"ל שמואל ור\"י תרי לגבי רב ואע\"ג דר\"ש בן יהוצדק רביה פסל בפרה כיון דראה ר\"י דבריו ודחאן נקטינן כוותיה:",1,0],[1,3,"השוחט את הקדשים ולא נתכוין לשחיטה וכו'. בס\"פ ב\"ש (זבחים דף מ\"ז) ובפ\"ק דחולין (דף י\"ג) בעיא דאיפשיטא:",1,0],[1,4,"ולא ישחוט ב' ראשים כאחד בקדשים וכו'. ברפ\"ב דחולין (דף כ\"ט) תני רב יוסף תזבח שלא יהו שנים שוחטין זבח אחד תזבחוהו שלא יהא אחד שוחט ב' זבחים ואמרינן בתר הכי אמר רבב\"ח אר\"י זו דברי ר\"א בר\"ש [סתימתאה] אבל חכ\"א שנים שוחטין זבח אחד וסתם מתני' שם (דף ל':) השוחט שני ראשים כאחד שחיטתו כשירה ואוקמוה בקדשים ומש\"ה דיעבד אין לכתחלה לא:",1,0],[1,5,"ומ\"ש אבל שנים שוחטים בהמה אחת וכו'. משנה שם ומשמע דבקדשים מיירי דומיא דרישא:",1,0],[1,6,"הקטן אינו שוחט קדשים אע\"פ שהגדול עומד וכו'. הכי משמע בהדיא בפ\"ק דחולין (י\"ב:).",1,0],[1,6,"ומ\"ש אפי' היתה מחשבתו ניכרת מתוך מעשיו אינה מחשבה להקל אלא להחמיר כיצד היתה עולה עומדת בדרום וכו'. שם (דף י\"ג) בעיא דאיפשיטא מחשבתו ניכרת מתוך מעשיו מדאורייתא אין לו מדרבנן יש לו. ופירש\"י מדרבנן יש לו ולחומרא במעלה פירותיו לגג מפני הכנימה והיפך בהם ה\"ז בכי יותן מדאוריי' אין לו וגבי היה עולה בדרום ומשכה לצפון ושחטה לא סמכינן עלה.",2,0],[1,6,"ומ\"ש אלא להחמיר. כגון ששחט ע\"מ לזרוק דמו אחר שתשקע החמה הויא מחשבתו מחשבה והזבח פגול:",3,0],[1,7,"קדשי קדשים שנשחטו בדרום או שנתקבל דמן בדרום פסולים. נלמד ממה שיבא בסמוך:",1,0],[1,8,"היה עומד בדרום והושיט ידו לצפון ושחט שחיטתו כשירה. ברייתא בפרק ב' דזבחים (דף כ\"ו):",1,0],[1,9,"ומ\"ש היה עומד בדרום והושיט ידו וקיבל הדם בצפון קבלתו פסולה. שם. ופירש\"י שחיטתו כשירה לקמן ילפינן לה אותו בצפון ואין השוחט בצפון אבל המקבל בצפון:",1,0],[1,10,"ומ\"ש הכניס ראשו ורובו בצפון הרי הוא כעומד בצפון. ג\"ז שם:",1,0],[1,11,"שחטה בצפון ופרכסה כו'. שם פרכסה ויצתה לדרום וחזרה כשירה ופירש\"י (משום) דאין פיסול יוצא אלא מתוך המחיצות והאי וחזרה לאו דוקא. ורבינו מפרש דהאי וחזרה איצטריך לאשמועינן שאם אחר שחזרה קיבל דמה בצפון כשירה ואם קיבל דמה עד שלא חזרה פשיטא דפסולה.",1,0],[1,11,"ומ״ש אפי' הוציאה לדרום כשירה. בר״פ דם חטאת (זבחים דף צ״ב:):",2,0],[1,12,"וכן קדשים קלים שהיו בפנים כו' הכניס ידו וקיבל קבלתו פסולה וכו'. שם (דף כ\"ז) בברייתא ופירש\"י הכניס ראשו ורובו כאילו לא נכנס כדילפינן לקמן בשמעתין בבואם אל אהל מועד עד שיבא כולו וגבי עזרה דכתיב לעמוד לפני ה' בעיא כולו דכיון דגלי בחדא גלי בכולהו והכי אמרינן בשמעתין.",1,0],[1,12,"ומ\"ש אפי' היה העובד כולו בפנים וציצתו בחוץ עבודתו פסולה וכו'. שם בעיא דאיפשיטא ופירש\"י ציצתו ציצת ראשו דהיינו שערו:",2,0],[1,13,"פרכסה הבהמה ויצאה לחוץ וכו'. זה מבואר בטעמו.",1,0],[1,13,"ומ\"ש כמו שיתבאר. הוא בס\"פ זה ושם מבואר שאין הזריקה מועלת ליוצא אלא לשרפו אבל לא לאכלו ומשמע דהוא הדין הכא:",2,0],[1,14,"היתה הבהמה כולה בפנים וכו'. שם בעא מיניה אבוה דשמואל משמואל היא בפנים ורגלה בחוץ מהו א\"ל כתיב והביאום לה' עד שתהא כולה בפנים:",1,0],[1,15,"ומ\"ש שחטה והיא כולה בפנים ואח\"כ הוציאה רגלה לחוץ וכו'. ג\"ז שם (דף כ\"ח:) א\"ר אמי א\"ר אלעזר היא בפנים ורגליה בחוץ חתך ואח\"כ שחט כשירה שחט ואחר כך חתך פסולה חתך ואח\"כ שחט כשירה בעל מום קא מקריב אלא אימא קיבל ואח\"כ חתך פסולה חתך ואח\"כ קיבל כשירה והא א\"ר זירא הצורם אוזן בבכור ואח\"כ קיבל דמו פסול וכו' א\"ר חסדא אמר אבימי חותך באבר עד שמגיע לעצם. קיבל ואח\"כ חתך פסולה שמעת מיניה דם המובלע באיברים דם הוא דילמא משום שמנונית ש\"מ בשר קדשים קלים שיצא לפני זריקה פסול דילמא בקדשי קדשים. ופירש\"י חותך באבר עד שהוא מגיע לעצם דלאו מום הוא והדם מעוכב ע\"י חתיכה מלעלות וליכנס לפנים. ש\"מ דם המובלע באיברים דם ובשר נמי לא הוי דאלת\"ה אהיכא חייל פיסול יוצא אמיא בעלמא. דילמא משום שמנונית דחזיא לאכילה וחשיבא לאיפסולי ביוצא וכו' ומובלע בדם הרגל ונפקא דרך בית השחיטה ופסלה ליה לדם שבמזרק:",1,0],[1,15,"כתב הראב״ד שחטה והיא כולה וכו' עד מפני שמנונית וכו'. א״א לא ידעתי זה מהו שהיוצא בקדשי קדשים וכו' עד לבעלים לכפרה קאמר וכן עיקר. דבריו מבוררים שהוא משיג על רבינו שנראה מדבריו שהוא מכשיר בחותך הבשר עד שהוא מגיע לעצם ואח״כ מקבל הדם דהא לענין טומאה איבעיא לן בפ' כיצד צולין (פסחים דף פ״ה) אי גזרו רבנן טומאה ביוצא או לא ולא איפשיטא ונקטינן לחומרא דגזרו טומאה ביוצא ואע״ג דמידי דרבנן הוא משום חומרא דקדשים נקטינן ביה לחומרא ומאחר דיוצא טמא אף מה שבפנים טמא דהא רבינא דבתרא הוא סבר בפ' בהמה המקשה דחיבורי אוכלים כמאן דמפרתי דמו ונגעי בהדדי וא״כ טימא היוצא למה שבפנים ופסול ושמעתא בפ' שני דזבחים (דף כ״ה כ״ו) דמכשר דלא כרבינא ולא הו״ל לרבינו לפסוק כוותיה אלא כרבינא דבתרא הוא ומשום דקשה לומר דשמעתא דזבחים ליפלוג ארבינא הדר ואמר דאפשר דאף שמעתא דזבחים סברה כרבינא דנפסל הבשר לאכילה ולא אתיא אלא לאכשורי זיבחא לבעלים לכפרה אבל הבשר אה״נ דאסור וה״ל לרבינו לפרושי. וליישב דעת רבינו י״ל דאי נימא דשמעתא דזבחים פליגא ארבינא למינקט כסתם גמרא עדיף מלמינקט כרבינא ואפי' למ״ש דהך שמעתא לאו לאכשורי בישרא לאכילה קאמר וכו' אין השגה על רבינו שהרי דרכו להעתיק לשון הגמרא כמות שהיא. ועי״ל דסבר רבינו דבעיא דפ' כיצד צולין דלא איפשיטא נקטינן לקולא כיון דבדרבנן היא והשתא שמעתא דזבחים לא פליגא ארבינא ולאכשורי בישרא לאכילה אתא:",2,0],[1,15,"כתב עוד ואח\"כ חתך פסול וכו' א\"א אפילו אחר זריקה וכו'. כלומר משיג על מ\"ש רבינו שבשר קדשים קלים שיצא קודם זריקה כשר דמאי איריא קודם זריקה אפילו אחר זריקה נמי ואפשר לומר דמאי יצא דקאמר רבינו יצא חוץ לחומת ירושלים. ועי\"ל דאפי' את\"ל דביוצא חוץ לעזרה מיירי ה\"ק אע\"ג דדם האיברים לאו דם הוא לענין שנאמר שאם הזה ממנו כשר מ\"מ כיון דאית ביה שמנונית לא חשבינן ליה כמיא בעלמא למימר דלא ליחול עליה פיסול יוצא כלומר שע\"י השמנונית חשיב דם לחול עליו פיסול יוצא:",3,0],[1,16,"תלה הבהמה ושחטה באויר העזרה פסולה וכו'. שם:",1,0],[1,17,"ומ\"ש היתה הבהמה בארץ ונתלה וכו'. (זבחים כ\"ו) נתלה ושחט מהו א\"ל פסולה א\"ל אישתבשת שחיטה על ירך ולא שוחט על ירך נתלה וקיבל מהו א\"ל כשירה א\"ל אישתבשת אין דרך שירות בכך תלה וקיבל מהו א\"ל פסולה א\"ל אישתבשת שחיטה על ירך ולא קבלה על ירך אמר אביי בקדשי קדשים כולם פסולים בר מנתלה ושחט בקדשים קלים כולם כשירים בר מנתלה וקיבל אמר רבא מ\"ש תלה וקיבל בקדשים קלים דכשרה דאויר פנים כפנים דמי בקדשי קדשים נמי אויר צפון כצפון דמי אלא אמר רבא בין בקדשי קדשים בין בקדשים קלים כשירים בר מתלה ושחט בקדשי קדשים נתלה וקיבל בין בקדשי קדשים בין בקדשים קלים. ופירש\"י בר מתלה ושחט בקדשי קדשים דבעינן על ירך אבל בקדשים קלים דלא כתיב על ירך כשירה. תלה וקיבל כשר בכולן דדרך שירות בכך ואויר צפון כצפון דמי ובקבלה לא כתיב על ירך. ונתלה וקיבל בקדשים קלים נמי פסול דקבלה שירות היא ואין דרך שירות בכך אבל נתלה ושחט כשרה דשחיטה לאו שירות הוא ועל ירך נמי לאו בשוחט כתיב אלא בבהמה עכ\"ל. ומזה יתבאר לך שיש טעות סופר בדברי רבינו וכן צריך להגיה, היתה הבהמה בארץ ונתלה ושחט והוא תלוי באויר כשירה תלה את הבהמה ושחטה באויר העזרה בקדשי קדשים פסול בקדשים קלים כשר:",1,0],[1,18,"שחט מיעוט סימנים בחוץ וגמרן בפנים. בפרק ב' דחולין (דף כ\"ט:) אמר ר\"ל וכו' אינה לשחיטה אלא בסוף ורבי יוחנן אמר ישנה לשחיטה מתחלה ועד סוף ואסיקנא לא נחלקו אלא כגון ששחט מיעוט סימנים בחוץ וגמרן בפנים למ\"ד ישנה לשחיטה מתחלה ועד סוף מיחייב למאן דאמר אינה אלא לבסוף לא מיחייב וידוע דהלכה כרבי יוחנן.",1,0],[1,18,"ומה שכתב או ששחטן בדרום וגמרן בצפון פסולים. נלמד ממה שנתבאר בסמוך:",2,0],[1,19,"נתלה וקיבל הדם וכו' היה עומד בעזרה ותלה המזרק בידו וקיבל הדם באויר וכו'. נתבאר בסמוך:",1,0],[1,21,"נתן מזרק לתוך מזרק וקיבל כשר. בפ' הוציאו לו (יומא דף נ״ח) בעא מיניה רמי בר חמא מרב חסדא הניח מזרק בתוך מזרק וקיבל בו את הדם מהו מין במינו חוצץ או אינו חוצץ ובעא למיפשטה ודחי ליה ואעפ״כ כיון דאשכחן לרבא דאמר בפרק לולב הגזול (סוכה דף ל״א) דמין במינו אינו חוצץ פסק רבינו כן. ועוד דאמרינן בפ' הוציאו לו איכא דאמרי הכי בעא מיניה דרך שירות בכך או אין דרך שירות בכך ת״ש דתנא דבי ר' ישמעאל ואת כלי השרת אשר ישרתו בם בקדש שני כלים ושירות אחת:",1,0],[1,21,"הניח סיב בתוך המזרק וקיבל וכו'. שם בעיא ובעא למיפשטה ודחי לה ובתר הכי אמרינן איכא דאמרי הכי פשט ליה בדם כשר בקומץ פסול ופסק כלישנא בתרא:",2,0],[1,22,"קבלת הדם והולכתו למזבח וזריקתו וכו' אינה כשירה אלא בכהן הכשר לעבודה. בספ\"ק דזבחים (דף י\"ג וי\"ד).",1,0],[1,22,"ומ\"ש וכן הולכת איברים לכבש. בפ\"ג דזבחים (דף ל\"ה).",2,0],[1,22,"ומ\"ש כמו שביארנו בקמיצת המנחה. פי\"ג ממעשה הקרבנות. ובמליקת העוף בפ\"ו מהלכות הנזכרות:",3,0],[1,23,"והולכה שלא ברגל אינה הולכה וכו'. מימרא דר\"י בספ\"ק דזבחים (דף י\"ד וט\"ו):",1,0],[1,25,"קיבל בימינו ונתן לשמאלו וכו' עד ואספו ונתנו לכלי השרת נפסל הזבח. משנה רפ\"ב (דף ט\"ו:) ורפ\"ג דזבחים (דף ל\"ב):",1,0],[1,26,"נשפך מקצת הדם מצואר בהמה על הארץ וכו'. בפ\"ב דזבחים (דף כ\"ה) אהא דתנן נשפך על הרצפה ואספו פסול ת\"ר ולקח הכהן המשיח מדם הפר מדם הנפש ולא מדם העור ולא מדם התמצית, ומשמע לרבינו דכל שאינו מדם העור ולא מדם התמצית אף על פי שנשפך מקצתו בארץ כשר ואף על גב דאמרינן התם השוחט צריך שיקבל את כל דמו של פר יש לומר דהיינו לכתחלה דוקא אי נמי ההיא בשלא נשפך דם מצואר לארץ אבל אם נשפך מקצת דם מצואר לארץ הדם הנשאר היינו כל הפר והיינו דתנן נשפך על הרצפה ואספו פסול הא אם לא אספו לא נפסל הזבח דמקבל דם הנשאר בצואר כשר:",1,0],[1,27,"כל הזבחים שקיבל דמן אחד מהפסולים לעבודה נפסל הזבח. משנה ריש פרק ב' דזבחים (דף ט\"ו:).",1,0],[1,27,"ומה שכתב או שהוליך את הדם למזבח או שזרקו למזבח כהלכתו נפסל הזבח. בסוף פרק קמא דזבחים (דף י\"ד) תניא זר אונן שכור בעל מום בקבלה בהולכה בזריקה פסל וכן יושב וכן שמאל.",2,0],[1,27,"ומה שכתב רבינו כהלכתו נראה דה\"ק אפילו אם זרקו כהלכתו נפסל הזבח, ויותר נראה לומר דדוקא זרקו כהלכתו פסל אבל זרקו שלא כהלכתו לא פסל דלא חשיבא זריקה:",3,0],[1,27,"קיבל הכשר ונתן לפסול וכו' עד שהרי אי אפשר לתקן דבר זה. בסוף פירקא קמא דזבחים אמר עולא אמר רבי יוחנן הולכה שלא ברגל לא שמה הולכה אפשר לתקונה או לא אפשר לתקונה וכו' אתמר אמר עולא אמר ר' יוחנן הולכה שלא ברגל פסולה אלמא לא אפשר לתקונה ובתר הכי אמרינן הוליכו זר והחזירו כהן וחזר והוליכו פליגי בה בני רבי חייא ורבי ינאי ח\"א כשר וח\"א פסול מר סבר אפשר לתקונה ומ\"ס לא אפשר לתקונה הוליכו כהן והחזירו וחזר והוליכו זר א\"ר שימי בר אשי לדברי המכשיר פסול לדברי הפוסל מכשיר רבא אמר אף לדברי הפוסל פסול מ\"ט דהא צריך לאמטוייה. ופסק כמ\"ד לא אפשר לתקונה משום דרבי יוחנן קאי כוותיה ופסק נמי כרבא:",4,0],[1,28,"קיבל הפסול וכו'. משנה ברפ\"ג דזבחים (דף ל\"ב).",1,0],[1,28,"ומ\"ש שאין הפסולים לעבודה עושים הדם הנשאר שירים חוץ מן הטמא וכו'. בפ\"ק דמעילה (דף ה'):",2,0],[1,28,"כתב הראב\"ד עושה שירים כיצד וכו' א\"א סבור אני שטעה בזה וכו'. ואני אומר שגם רבינו סובר כן וכשכתב כאן כיצד קיבל הטמא קיבל וזרק קאמר וסמך על מ\"ש בפ\"ג מה' מעילה קיבלו הפסולים את הדם וזרקוהו וחזרו הכשרים לעבודה וקיבלו שאר דם הנפש וזרקוהו אין מועלין בבשרן שאין הפסולים עושים שאר דם הנפש שירים חוץ מן הטמא כיצד קיבל הטמא וזרק אע\"פ שחזר הכשר וקיבל שאר דם הנפש וזרקו הרי אלו לא היתה להם שעת היתר וכו':",3,0],[1,29,"בהמה שחסר מאיבריה כל שהוא וכו'. מימרא דרבי זירא בפרק שני דזבחים (דף כ״ו) ובפרק על אלו מומין (בכורות דף ל״ט):",1,0],[1,30,"ומ\"ש אבל אם חסרה אחר קבלה קודם זריקה אפי' אבד הבשר קודם זריקת הדם או נשרף אם נשתייר כזית מן הבשר או כזית מן האימורים זורק את הדם ואם לאו אינו זורק. גם זה שם.",1,0],[1,30,"ומ\"ש ובעולה אפי' כחצי זית מן הבשר וחצי זית מן האימורים וכו'. בהקומץ רבה (דף כ\"ו) ובתוספתא דזבחים פ\"ד והטעם פשוט משום דכולה להקטרה:",2,0],[1,31,"ומ\"ש נשאר פחות מכזית וכו' ואם זרק לא הורצה. הכי משמע שם:",1,0],[1,31,"נפסל הבשר קודם זריקה כו'. בפרק כיצד צולין (פסחים דף ע״ט):",2,0],[1,32,"בשר קדשים קלים וכו'. בזבחים פרק כל התדיר (זבחים דף צ') פלוגתא דרבי יוחנן ור״ל ופסק כר' יוחנן וכן היא ג״כ פלוגתא דר' אליעזר ור״ע ופסק כר״ע.",1,0],[1,32,"ומ\"ש והזריקה מועלת ליוצא לשרפו אבל לא לאכלו. בספ\"ק דמעילה (דף ז':) כי אמר ר' עקיבא זריקה מועלת ליוצא לשריפה אבל לאכילה הוא דלא מרצה. ופירש\"י דלהכי מהניא ליה זריקה שאינו נשרף לאלתר כפסולים אלא עד שתעובר צורתו:",2,0],[1,32,"כתב הראב\"ד א\"א לא ידעתי מהו זה וכו'. כלומר דהשתא מהדר רבינו למ\"ש לעיל או שיצא חוץ לעזרה לא יזרוק הדם ואם זרק הורצה וקאמר דלא הורצה אלא להעלותו על גבי המזבח אבל לא לאכלו וה\"ה לבשר קדשים קלים שיצא חוץ לחומת ירושלים שאם זרק הדם הורצה לשרפו אבל לא לאכלו, וכתב שדבריו מבולבלים שהכניס דין בשר קדשים קלים שיצא חוץ לעזרה בין הדבקים וכך ה\"ל לכתוב ואם זרק הורצה וה\"ה לבשר קדשים קלים שיצא חוץ לחומת ירושלים ואח\"כ ה\"ל לכתוב דין בשר קדשי קדשים שיצא חוץ לחומת העזרה. ואני אומר שטעמו של רבינו שבתחלה כתב דין בשר קדשי קדשים שיצא חוץ לעזרה (ואח\"כ כתב דין בשר קדשים קלים שיצא חוץ לעזרה) ואח\"כ כתב דין בשר שיצא חוץ למחיצתו קודם זריקה דהיינו בשר קדשי קדשים חוץ לעזרה ובשר קדשים קלים חוץ לחומת ירושלים שהזריקה מועלת בהם לשורפו אבל לא לאכלו:",3,0],[1,33,"וכן אימורי קדשים קלים כו'. בפרק כל התדיר (זבחים דף צ') מייתי הא דתנן בפרק קמא דמעילה אימורי קדשים קלים שיצאו לפני זריקת דמים ר״א אומר אין מועלין בהם ואין חייבין עליהם משום פגול נותר וטמא ר״ע אומר מועלין בהם וחייבים עליהם משום פגול נותר וטמא ואסיק רב פפא בדהדר עיילינהו כולי עלמא לא פליגי והכא בדאיתנהו אבראי פליגי. ואע״ג דלכאורה משמע דרב פפא בדרך דחייה אמרה מכל מקום מדאקשינן והא רב פפא הוא דאמר בדאיתנהו אבראי כולי עלמא לא פליגי וכו' ושני ה״מ גבי שתי הלחם וכו' משמע דבקושטא דמילתא אמרה:",1,0],[1,33,"וכתב הראב\"ד ואם החזירן מקטירין אותם א\"א [זה] אינו מחוור עכ\"ל. טעמו דס\"ל דאע\"ג דמועלים בהם וחייבין עליהם משום פגול וכו' כיון שיצאו לחוץ נפסלו מלהקטירן. ורבינו סובר שמאחר שמועלין בהם וחייבין עליהם משום פגול וכו' לא נפסל הזבח:",2,0],[1,34,"כל הזבחים של יחיד וכו'. בפרק כיצד צולין (פסחים דף ע״ז) אהא דתנן חמשה דברים באים בטומאה ואינם נאכלים בטומאה העומר ושתי הלחם וכו' אמרינן נימא מתני' דלא כר' יהושע דתניא (ועשית עולותיך הבשר והדם) רבי יהושע אומר אם אין דם אין בשר אם אין בשר אין דם. ופירש״י אם אין בשר ראוי כגון שנטמא או שאבד אין הדם נזרק וכיון דאמר רבי יהושע בעינן תרתי וציץ אאכילות לא מרצה היכי אתי בטומאה ואסיקנא (דף ע״ח) מתניתין כר״י ול״ק כאן ביחיד כאן בצבור. ופירש״י ביחיד לכתחלה פסולה ואם זרק הורצה ומתני' בצבור באין לכתחלה דטומאת צבור דחויה היא.",1,0],[1,34,"ומה שכתב וכן אימורים או איברי עולה שנטמאו והקטירן הציץ מרצה כמו שביארנו. בפרק רביעי מהלכות ביאת המקדש:",2,0],[1,34,"ומה שכתב וכל קרבנות הצבור שנטמא הבשר והחלב כולו הרי זה זורק את הדם. נתבאר בסמוך דטומאה דחויה היא בצבור:",3,0],[1,35,"דם קדשים שיצא חוץ לעזרה וכו'. בס\"פ התערובות (דף פ\"ב) תנן גבי דמים פסולים שאין הציץ מרצה על היוצא:",1,0],[1,36,"וכל דם הקדשים אינו מקבל טומאה כלל וכו'. בסוף פרק ב״ש (זבחים דף מ״ו:).",1,0],[1,36,"ומ״ש על הארץ תשפכנו כמים וכו'. בסוף פירקא קמא דפסחים (דף ט״ז:) מנין לדם קדשים שאינו מכשיר שנאמר על הארץ תשפכנו כמים וכו' ומתיב התם מדתניא דם שנטמא וזרקו במזיד לא הורצה ומשני התם מדרבנן. וק״ל מדתנן בפרק כיצד צולין (פסחים דף פ':) הנזיר ועושה פסח הציץ מרצה על טומאת הדם ומשמע דמדאורייתא טמא הדם מדקתני הציץ מרצה וצ״ע:",2,0],[1,37,"ודם ששקעה עליו חמה וכו'. מימרא בס״פ איזהו מקומן (זבחים דף נ״ו):",1,0],[2,1,"כל הדמים הניתנים על מזבח החיצון וכו'. ברפ\"ד דזבחים (דף ל\"ו:) וכב\"ה:",1,0],[2,2,"ומ\"ש וכל הניתנים בזריקה שנתנם בשפיכה יצא וכו'. שם ת\"ר מנין לניתנים על מזבח החיצון שנתנן במתנה אחת שכיפר ת\"ל ודם זבחיך ישפך. ופירש\"י ישפך שפיכה אחת משמע דלא כתיב סביב. והאי להכי הוא דאתא האי מבעי ליה לכדתניא וכו' מנין לניתנין בזריקה שנתנן בשפיכה יצא ת\"ל ודם זבחיך ישפך סבר לה כר\"ע דאמר לא זריקה בכלל שפיכה ולא שפיכה בכלל זריקה. ופירש\"י מנין לניתנין בזריקה כל הדמים שכתוב בהם זריקה וכו' וכל זריקה מרחוק משמע שזורק מן הכלי למזבח למרחוק שפיכה עומד אצל היסוד ושופך. ודם זבחיך ישפך כל זבחים במשמע. ובתר הכי אמרינן (דף ל\"ז:) וכל הנך תנאי דמפקי להאי ודם זבחיך ישפך לדרשא אחרינא האי כל הניתנים על מזבח החיצון שנתן מתנה אחת כיפר מנא להו סברי כב\"ה דאמרי אף חטאת שנתנה מתנה אחת כיפר וילפינן כולהו מחטאת. ויש לתמוה על רבינו דמייתי לה מודם זבחיך ישפך דכיון דפסק כב\"ה דאמרי אף חטאת שנתנה מתנה אחת כיפר מחטאת ילפינן לה ולא מודם זבחיך ותו כיון דאמרינן דמאן דיליף שאם נתנן מתנה אחת כיפר מודם זבחיך ישפך סבר לה כר\"ע דאמר דניתנין בזריקה שנתנן בשפיכה לא יצא היאך רבינו מזכי שטרא לבי תרי. מיהו בהא איכא למימר דאע\"ג דמאן דיליף וכו' סבר לה כר\"ע אפשר דר\"ע לא סבר לה כוותיה אבל אכתי קשה דכיון דההיא דמנין לניתנין בזריקה שנתנן בשפיכה יצא אתיא דלא כר\"ע לא ה\"ל להביאה. והר\"י קורקוס ז\"ל כתב שפסק כאותה ברייתא ואם נתן בשפיכה יצא משום דמשמע דהלכתא היא דבפסחים (דף פ\"ט.) פריך מינה ומסיק דאמרינן בדיעבד אבל לכתחלה לא עכ\"ל. ולענין קושיא קמייתא איכא למימר שדרך רבינו לסמוך הדבר לפסוק שנראה לו שהוא פשוט ללמוד ממנו הדין יותר מהפסוק שמביא ממנו הגמרא ודרך הגמרא לעשות כן בכמה מקומות:",1,0],[2,3,"כל הדמים הניתנים על מזבח הפנימי וכו'. שם במשנה:",1,0],[2,4,"חטאת שנתן ממנה מתנה אחת ומתו הבעלים וכו' עד חייב משום מעלה בחוץ. מימרא דרבי יוחנן שם (דף ל\"ח:) ופירש רש\"י אינם באות בלילה ואף על פי שאינן מעכבות ולאו זריקה גמורה היא מיהו דם נפסל בשקיעת החמה ואין מעלין לגבי מזבח לכתחלה באות לאחר מיתה אם נתן מתנה ראשונה ומתו בעליה כבר כיפר בראשונה ואין שם חטאת גמורה על הדם עוד ליפסל משום חטאת שמתו בעליה וכו' הזורק אותה בחוץ חייב שהרי ראויות לפנים בתורת זריקה גמורה:",1,0],[2,7,"היה מזה ונקטעה ידו של מזה וכו'. בסוף פ\"ק דזבחים (דף ט\"ו:) בעיא דאיפשיטא:",1,0],[2,8,"שינה מתן קרבנות בחטאת וכו':",1,0],[2,9,"נתן הדם מן הקרן ולפנים וכו':",1,0],[2,10,"דם שמצותו ליתן אותו למעלה וכו' עד הרי בשר הזבח פסול. משנה בפרק שני דזבחים (דף כ\"ו).",1,0],[2,10,"ומ\"ש ואע\"פ כן נתכפרו הבעלים בו. מימרא דשמואל שם ואף על גב דר\"י פליג עליה הא אסיקנא בקשיא ואמוראי טובא התם ס\"ל כשמואל מדשקלי וטרו אליביה.",2,0],[2,10,"ומה שכתב במה דברים אמורים כשהיה זה הזורק כשר לעבודה וכו' עד ויזרוק הדם במקומו. ג\"ז שם:",3,0],[2,11,"דמי קדשים שנתערבו וכו' עד יתן הכל מתן ד'. משנה בפ' התערובות (דף פ').",1,0],[2,11,"ומה שכתב בין דם בדם בין כוסות בכוסות הכי משמע התם בגמרא.",2,0],[2,11,"ומ\"ש נתערבו הניתנין מתנה אחת בניתנין מתן שתים שהן כארבע וכו' נלמד ממה ששנו שם במשנה ופלוגתא דר\"א ורבי יהושע ופסק כרבי יהושע:",3,0],[2,11,"נתערבו הניתנים למעלה בניתנין למטה ישפך הכל לאמה. שם במשנה פלוגתא דר\"א ורבנן ופסק כרבנן.",4,0],[2,11,"ומ\"ש אפי' נתערבו שירי החטאת עם דם העולה וכו'. שם פלוגתא דאמוראי ופסק כרבי יהודה:",5,0],[2,12,"ומ\"ש ואם לא שאל אלא נתן מן התערובת למעלה ולמטה ה\"ז כשר. שם במשנה.",1,0],[2,12,"ומ\"ש נתן למעלה ושאל יתן למטה ואלו ואלו עלו לו. ברייתא שם:",2,0],[2,13,"נתערבו הניתנין בפנים בניתנין בחוץ וכו' בד\"א בשאר דמים הניתנין בחוץ חוץ מן החטאת וכו' עד פסולה. שם במשנה (דף פ\"א:) ופסק כחכמים דפליגי אר\"ע ואר\"א.",1,0],[2,13,"ומ\"ש שדם חטאת שנכנס להיכל אפי' חטאת יחיד הנאכלת אסור וכו'. שם (דף פ\"ב) בברייתא דברי ר\"י הגלילי. ומדברי רבינו נראה שהוא גורס אין לי אלא חטאת צבור של יחיד מנין ת\"ל כל.",2,0],[2,13,"ומ\"ש והוא שיבא דרך שער ההיכל וכו'. ג\"ז שם בסוף הפרק:",3,0],[2,14,"פר העלם ושעיר ע\"ז וכו' וכן פר ושעיר של יוה\"כ וכו' עד נפסל. שם (דף פ\"ב ע\"ב) בעי רבא פר העלם דבר של צבור ושעיר ע\"ז שהכניס דמן לפנים מהו מי אמרי' אל הקדש פנימה [כל היכא דקרינן אל הקדש] קרינן ליה פנימה כל היכא דלא קרינן אל הקדש לא קרינן פנימה או דילמא שלא מקומן הוא ואת\"ל שלא מקומן הוא פר ושעיר של יוה\"כ שהזה מדמן על הבדים והוציא להיכל והכניסן מהו מי אמרינן מקומן הוא או דילמא הואיל ונפק נפק ואת\"ל הואיל ונפק נפק הזה דמן על הפרוכת והוציאן למזבח והכניסן [מהו] הכא ודאי חד מקום הוא או יציאה קרינן ביה תיקו. ופירש\"י פר העלם דבר שמצות כפרתו בהיכל והכניסו לפני לפנים מהו מי אמרי' כל היכא דקרינן ביה פיסול דאל הקדש כגון בחטאות החיצונות קרינן ביה פיסול דפנימה וכו' דהא כי הדדי כתיבי או דילמא שלא במקומו הוא והויא הכנסה ומיפסיל. והוציאן להיכל להזות על הפרוכת כמשפטן. מקומן הוא שהרי הוזקקו לשם תחלתן. או דילמא כיון דנפק בעשיית כל מצותו נפיק ליה לגמרי וה\"ל שלא מקומו. והוציאו למזבח להזות ז' (הזאות) על טהרו. ומתן ד' על קרנותיו כדכתיב ויצא אל המזבח אשר לפני ה' וכפר עליו ותנן זה מזבח הזהב בפרק הוציאו לו ואמרי' התם דלהכי כתיב ויצא עד דנפיק מכוליה מזבח שלא יעמוד בין המזבח ולפרוכת בשעת מתנות המזבח אלא בין המזבח לפתח לצד המזבח הכא חד מקום הוא שאין הפסק מזבח בינתים ולא הויא הכנסה שלא במקומה או דילמא רחמנא שוייה שני מקומות דכתיב ביה יציאה עכ\"ל. וכדרך פירש\"י הוא פירוש הראב\"ד שכתב וז\"ל א\"א אני איני סובר כפירושו כו'. ורבינו דחה פירוש זה משום דלישנא דהואיל ונפק נפק משמע דמטעם שיצא חוץ למקומו הוא דפסלינן ליה ולא משום הכנסה. ולענין תרי בעיי קמאי כיון דאיפשיטו באת\"ל פסק כן רבינו והשלישית שעלתה בתיקו פסקה לחומרא. והר\"י קורקוס ז\"ל כתב שיש לתמוה על רבינו שהיה לו לכתוב בבבא השלישית לא יעשה מספק ואם עשה הורצה ואפשר דלא שייך בזה הורצה כיון דספק יוצא הוא ואין הציץ מרצה על היוצא מ\"מ ה\"ל לכתוב ספק כמו בסמוך כי לשון שכיון שיצא הדם חוץ למקומו נפסל משמע דמן הודאי קאמר. ואפשר דסבר רבינו דרבא הוא דאסקה בתיקו ומיהו גמרא משמע התם דלא מספקא ליה וכ\"נ שם בברייתא דר\"י הגלילי גם בפרק טבול יום נראה כן גבי חטאת אהרן שמא בחוץ היתה בקדש היתה וקדש היינו היכל משמע שכל שיצאה מן ההיכל נפסלה עכ\"ל:",1,0],[2,15,"חטאת שקיבל דמה בב' כוסות וכו'. משנה שם (דף פ\"ב).",1,0],[2,15,"ומ\"ש נכנס אחד מהם להיכל וכו' אף החיצון פסול. שם במשנה מחלוקת ופסק כחכמים.",2,0],[2,15,"ומ\"ש והזה ממנו. שם במשנה הנזכרת נכנס לכפר אע\"פ שלא כיפר פסל דברי ר\"א ר\"ש אומר עד שיכפר ופסק כר\"ש משום דר' יהודה סבר כוותיה כמו שיתבאר בסמוך:",3,0],[2,16,"ומ\"ש דם חטאת שהכניסו לכפר בו בפנים ולא כיפר אלא הוציאו וכו' אם הכניסו בשוגג ה\"ז כשר וכו'. שם במשנה ר' יהודה אומר אם הכניס שוגג כשר ומשמע לרבינו דר\"י אר\"ש קאי וה\"ק הא דמכשיר ר\"ש כשלא כיפר היינו דוקא כשנכנס שוגג אבל אם הכניסו במזיד אע\"פ שלא כיפר פסול. אבל קשה דהתם בגמרא (דף פ\"ג) אמרינן אר' יהודה דאמר אם הכניס שוגג כשר הא מזיד פסול בשכיפר או בשלא כיפר ופירש\"י בשכיפר וכר\"ש ס\"ל או אפי' בשלא כיפר וכר\"א אמר ר' ירמיה ממשמע שנאמר ואת פר החטאת וכו' ורבי יהודה לכפר לא משמע ליה מ\"ט לאו משום דמיבעיא ליה לג\"ש. ופירש\"י מ\"ט לאו משום דמפיק להאי לכפר לג\"ש דר\"ש ללמד על דמים החיצונים שנכנס דמם לפנים שאין פסול אא\"כ כיפר כר\"ש ועוד דבס\"פ כל הפסולין אמרינן (דף ל\"ו) והתנן א\"ר יהודה הכניס בשוגג כשר הא במזיד פסול וקי\"ל בשכיפר הרי בהדיא דמפרש גמרא דר' יהודה לא פסל במזיד אא\"כ כיפר. וא\"כ היאך פסק רבינו שבמזיד אע\"פ שלא כיפר פסל. וכתב הר\"י קורקוס ז\"ל שטעם רבינו משום דמסיק שם בפ' כל הפסולים על תרי תנאי ואליבא דרבי יהודה פי' דתנא דההיא ברייתא דמוכח מינה לר' יהודה דדוקא בכיפר פליג אההיא מתני' וגם מתני' דפרק התערובות מצינן לפרושה כההיא דכל הפסולים ובדלא כיפר מיירי, ומעתה הדין עם רבינו שלא לסמוך על אותו פשיטות ולהניח משנה דכל הפסולים אלא דחינן ברייתא מקמי מתניתין ומפרשים בלא כיפר עכ\"ל, ודבריו אלו צל\"ע:",1,0],[2,17,"הכניס החטאת עצמה וכו'. בפ' דם חטאת (זבחים דף צ״ב) ובפ' דם חטאת נתבאר שאפי' הכניסה קודם שקיבל דמה וכשהוציאה קיבל דמה כשירה ולכך כתב רבינו הכניס החטאת עצמה ולא כתב הכניס בשר כלשון הגמ' כך כתב הר״י קורקוס ז״ל:",1,0],[2,18,"חטאת העוף שפרכסה ונכנסה להיכל כשירה. שם (דף צ\"ב:):",1,0],[2,19,"הכניס דם חטאת העוף וכו'. גם זה שם בעי ר' אבין חטאת העוף שהכניס דמה בצוארה בפנים מהו צוארה ככלי שרת דמי ומיפסיל או דילמא כצואר בהמה מדמה אמר רחמנא ולא בשרה. ופירש\"י שהכניס דמה בצוארה בפנים בין מליקה להזיה מהו שתפסל משום וכל חטאת אשר יובא. ככלי שרת דמי שהרי לא הוזקקה בקבלת כלי וזהו כליה ומיפסיל בהכנסת הדם שהכניסה בכלי להיכל או דילמא וכו' ובהמה שהכניסה לפנים משנשחטה הוציאה וקיבל דמה לא מיפסלה דמדמה אמר רחמנא ולא שהכניסו עם בשרה עכ\"ל ולא איפשיטא:",1,0],[2,20,"ומ\"ש נשפך דם חטאת העוף ואספו וכו'. שם בעי רבי אבין נשפך על הרצפה ואספו מהו אצרוכי הוא דלא אצרכיה רחמנא כלי שרת והילכך אוספו וכשר או דילמא מיפסל פסל ביה רחמנא כלי שרת והילכך אוספו ופסול. ופירש\"י נשפך על הרצפה מצואר העוף. אצרוכי הוא דלא אצרכיה רחמנא כלי שרת וצואר דידיה הוא במקום כלי שרת והלכך לאוספו כשר ולהזותו למזבח דה\"ל כנשפך מן הכלי על הרצפה ואספו דכשר. א\"ד מיפסל פסל ביה רחמנא כלי שרת דדוקא שייר ולא כתב ביה קבלה משום דבעי להזותו מן העוף עצמו למזבח וכ\"ש ברצפה פוסלתו עכ\"ל ולא איפשיטא.",1,0],[2,20,"ומ\"ש לפיכך תשרף וכו'. קאי גם להכניס דם חטאת העוף להיכל בצוארה ופשוט הוא:",2,0],[2,21,"חטאת שקיבל דמה בארבעה כוסות וכו' עד נשפכים לאמה. בפרק שלישי דזבחים (דף ל״ד ע״ב) ופרק הוציאו לו (יומא דף נ״ז:) ברייתא ואע״ג דפליג ר' אלעזר בר' שמעון פסק כתנא קמא:",1,0],[2,22,"דם שנפל לתוך המים וכו'. בפרק התערובות (דף ע\"ז:) שנינו דם שנתערב במים אם יש בו מראה דם כשר ובגמרא אמר רבי חייא בר אבא א\"ר יוחנן לא שנו אלא שנפלו מים לתוך דם אבל נפל דם לתוך מים ראשון ראשון בטל.",1,0],[2,22,"ומ\"ש או לתוך דמי חולין וכן מ\"ש נפל לתוכו יין או דם חולין וכו'. שם במשנה נתערב ביין וכו' בדם בהמה או בדם החיה רואים אותו כאילו הוא מים:",2,0],[2,23,"דם הקדשים שנתערב בדם פסולי המזבח וכו'. משנה שם (דף ע\"ט:) דם תמימים בדם בעלי מומין ישפך לאמה כוס בכוסות ר\"א אומר אם קרב כוס אחד יקרבו כל הכוסות וחכ\"א אפי' קרבו כלם חוץ מאחד מהם ישפך לאמה.",1,0],[2,23,"ומ\"ש וכל הזבחים פסולים. פשוט הוא מאחר שלא נזרק הדם לא הותרו ואע\"פ שאין בדם הפסול שיעור לבטל הכשר ישפך לאמה דגזרינן דילמא אתי לאכשורי כשיש בדם הפסול או התמצית לבטל הכשר והא דלא גזרינן בנתערב בדם חולין משום דדם חולין לא שכיח בעזרה:",2,0],[2,23,"נתערב בדם התמצית וכו'. משנה שם (דף ע\"ח):",3,0],[2,25,"האימורים ואיברי העולות וכו' עד או בידו פסולים. בתוספתא דזבחים ספ״ק ואיתא בגמרא פרק הקומץ רבה (מנחות דף כ״ו):",1,0],[2,26,"איברים שסידרן וכן קומץ שסידרו וכו' עד סוף הפרק. בפ' הקומץ בעיי דסלקו בתיקו ואע\"פ שאמרו שם דאליבא דמ\"ד על ממש לא תיבעי כבר נתבאר בפרק שרבינו פוסק כמ\"ד על היינו בסמוך:",1,0],[3,1,"קדשי קדשים ששחטן בראש המזבח וכו'. משנה בר״פ קדשי קדשים (זבחים דף נ״ח) פלוגתא דתנאי ופסק כר' יוסי דנימוקו עמו ופריך בגמרא השתא כולו לעולה כשר כולו לשלמים מיבעיא ומשני סד״א עולה היא דדחיק ליה מקום אבל שלמים דלא דחיק ליה מקום אימא לא קמ״ל:",1,0],[3,2,"עולה ששחטה בראש המזבח או ששחטה למטה וכו'. משנה בפ' המזבח מקדש (זבחים דף פ״ד) עולה שעלתה חיה לראש המזבח תרד שחטה בראש המזבח יפשיט וינתח במקומה.",1,0],[3,2,"ומ\"ש ומוריד את הקרבים ומדיחן. הכי אמרי' שם בברייתא ואע\"ג דהתם מיירי בנפסלה ילפינן מינה לכשירה במכל שכן.",2,0],[3,2,"ומה שכתב ומוריד העור ונותנו לכהנים. פשוט הוא.",3,0],[3,2,"ומ\"ש דה\"ה לשחטה למטה והעלה לראש המזבח. הכי משמע מדתנן בראש הפרק הנזכר (דף פ\"ג) כל הראוי לאשים אם עלה לא ירד ועוד דמשמע דאתיא בכ\"ש משחטה בראש המזבח:",4,0],[3,3,"ומ\"ש וכן זבחים שחוטים שעלו לגבי מזבח וכו' שכל הראוי לאשים אם עלה לראש המזבח לא ירד וכן מ\"ש מה עולה שהיא ראויה לאשים וכו'. משנה הזכרתיה בסמוך לר' יהושע ואע\"ג דפליג עליה ר\"ג לא פסק רבינו כמותו משום דר\"ע ור\"י הגלילי ור\"ש פליגי עליה.",1,0],[3,3,"ומ\"ש שנאמר כל הנוגע במזבח יקדש. שם במשנה ובגמרא:",2,0],[3,4,"עולה שהעלה חיה לראש המזבח תרד וכו'. משנה כתבתיה בסמוך:",1,0],[3,5,"ומ\"ש וכן קומץ המנחה שלא נתקדש בכלי שרת. בר\"פ המזבח מקדש שם.",1,0],[3,5,"ומ\"ש וכל איסורי המזבח שעלו ירדו וכו' וכן בהמת הקדשים שנשחטה בלילה וכו'. שם במשנה (דף פ\"ד) אלו אם עלו לא ירדו הלן והיוצא והטמא ושנשחט חוץ לזמנו וחוץ למקומו ושקבלו פסולים וזרקו את דמו ר' יהודה אומר ושנשחטה בלילה ושנשפך דמה ושיצא דמה חוץ לקלעים אם עלתה תרד רבי שמעון אומר לא תרד שהיה פיסולו בקדש שרבי שמעון אומר כל שפיסולו בקדש הקדש מקבלו לא היה פיסולו בקדש אין הקדש מקבלו ואלו לא היה פיסולן בקדש הרובע והנרבע והמוקצה והנעבד והאתנן והמחיר והכלאים והטרפה והיוצא דופן ובעלי מומין ובגמרא תניא ר' יהודה אומר זאת והיא העולה מיעוטים פרט לנשחטה בלילה ושנשפך דמה ושיצא דמה חוץ לקלעים שאם עלתה תרד ר\"ש אומר עולה אין לי אלא עולה כשירה מנין לרבות שנשחטה בלילה וכו' והניתנין למטה שנתנן למעלה ולמעלה שנתנן למטה והניתנין בחוץ שנתנן בפנים בפנים שנתנן בחוץ וכו' ת\"ל תורת העולה ריבה וכו' ור' יהודה מייתי לה מהכא מפני מה אמרו לן בדם כשר שהרי לן כשר באימורין לן באימורין כשר שהרי לן כשר בבשר יוצא שהיוצא כשר בבמה טמא הואיל והותר לעבודת צבור חוץ לזמנו הואיל ומרצה לפיגולו חוץ למקומו הואיל ואיתקש לחוץ לזמנו שקבלו פסולים וזרקו את דמו בהני פסולים דחזו לעבודת צבור וכי דנים דבר שלא בהכשרו מדבר שבהכשרו תנא אזאת תורת העולה ריבה סמיך ליה. ופירש\"י לן בדם כשר שאם עלה לא ירד. שהרי לן כשר באימורים שאם עלו לא ירדו. שהרי לן כשר בבשר כגון בשר שלמים הנאכלים לשני ימים. יוצא וכו' וביוצא דאימורי עולה ואימורי קדשים אבל יוצא דדם פסל ר' יהודה ולכך כתב רבינו זבח שיצא ופירש\"י חוץ לזמנו דאשכחן ליה ריצוי אפילו בפנים שמרצה לפיגולו ליענש כרת. דחזו לעבודת צבור כגון טמא. דבר שלא בהכשרו כגון לן באימורים. מדבר שבהכשרו לן בבשר ויוצא דמקדש מיוצא דבמה שאין שם מחיצה עכ\"ל. ופסק רבינו כר' יהודה:",2,0],[3,7,"ומ\"ש או קדשי קדשים שנשחטו בדרום או שנתקבל דמן בדרום אע\"פ שכל אלו פסולים אם עלו [לראש המזבח] לא ירדו. יש לתמוה דבריש מעילה (דף ב') גבי קדשי קדשים ששחטן בדרום וקיבל דמן בצפון בצפון וקיבל דמן בדרום איבעיא להו עלו מהו שירדו רבה אמר אם עלו ירדו רב יוסף אמר אם עלו לא ירדו אליבא דר' יהודה לא תיבעי לך דכ\"ע לא פליגי שאם עלו ירדו כי פליגי אליבא דר\"ש ואע\"ג דאיתותב רבא דאמר אם עלו ירדו היינו משום דאמר הכי לר\"ש אבל לר' יהודה לכ\"ע ירדו. ורבינו שפסק בסמוך כר' יהודה ה\"ל לפסוק כאן שאם עלו ירדו ושמא נוסחא אחרת היתה לרבינו בזה. והר\"י קורקוס ז\"ל נדחק מאד ליישב זה ולא כתבתיו שלא להאריך:",1,0],[3,8,"וכשם שאם עלו לא ירדו כו'. משנה בפ' המזבח מקדש (זבחים דף פ״ד):",1,0],[3,9,"ומ״ש ואם משלה בהם האור אע״פ שירדו יעלו שניה וכו'. מימרא דעולא שם (דף פ״ה:) ובפרק בית שמאי (זבחים דף מ״ג):",1,0],[3,10,"קומץ שנתפגל כו'. גם זה בפרק ב״ש (זבחים דף מ״ג):",1,0],[3,11,"איברים וחלבים וקמצים שלנו בראשו של מזבח וכו'. בפ' המזבח מקדש (זבחים דף פ״ז) אתמר איברים שלנו בעזרה מקטיר והולך כל הלילה לנו בראשו של מזבח מקטיר והולך לעולם ירדו רבה אמר יעלו רבא אמר לא יעלו ופסק כרבא דבתרא הוא:",1,0],[3,12,"ומ\"ש ואויר מזבח כמזבח. שם בעא ר\"ל מר\"י ואסיקנא דבעומד האדם בראש המזבח ואוחז האבר בידו פשיטא דאויר מזבח כמזבח דמי כי מיבעיא ליה [דעומד בקרקע העזרה] ונקיט ליה בקניא כנגד המזבח מאי תיקו. ויש לתמוה על רבינו שסתם דבריו ולא חילק והר\"י קורקוס ז\"ל דחק עצמו להוכיח שנפשטה הבעיא ממקומות אחרים ולי אין צורך לכך אלא מאחר דלא איפשיטא בעיא מספיקא לא תרד:",1,0],[3,12,"אימורי קדשים קלים וכו'. כלומר אע״פ שהעלום בפסלות כיון שנזרק הדם אח״כ לא ירדו. בר״פ המזבח מקדש ובספ״ק דמעילה מימרא דעולא ובפ' המזבח מקדש (זבחים דף פ״ג:) בעיא דאיפשיטא ועיין במ״ש רבינו רפ״ב מהל' מעילה. וכתבו התוס' דאימורי קדשים קלים דנקט לרבותא וכ״ש קדשי קדשים:",2,0],[3,13,"הפריש שני אשמות לאחריות ושחט את שניהם וכו' הרי אלו ירדו. בסוף פרק קמא דמעילה (דף ז') אילו הפריש שתי אשמות לאחריות ושחט את שניהם וקדם והעלה אמורים של אחד מהם קודם זריקה אי אתה מודה שאם עלו ירדו. ופירש\"י לאחריות שאם יאבד אחד מהם שיתכפר באחר והאי דנקט שני אשמות וכ\"ש שתי חטאות דחטאת חמירא קדושתה מאשם. ושחט את שניהם וקדם והעלה אימורים של אחד מהם קודם זריקה ואח\"כ זרק הדם ואשם שלא קרבו אמורים אי אתה מודה שאם עלו באותן אימורים שירדו דזריקת דם דאידך לא מהניא להני אימורים דלאו דידיה משום דמגופא אחרינא נינהו עכ\"ל. וכתב הראב\"ד והוא שזורק דם האחר וכו'. ומבואר הוא בדברי רש\"י שכתבתי ואין מזה השגה על רבינו שלא כתבו שהוא העתיק דברי הגמרא כמנהגו:",1,0],[3,14,"הזבח הפסול והנסכים הפסולים שעלו למזבח וכו'. פלוגתא דתנאי במשנה ר״פ המזבח מקדש (זבחים דף פ״ג) ופסק כר״ש שסובר כר' יהושע.",1,0],[3,14,"ומ\"ש וכן נסכים הבאים בפני עצמן שנפסלו ועלו וירדו. שם (דף פ\"ד) נסכים הבאים בפני עצמן לדברי כולן ירדו:",2,0],[3,15,"עוף שמלקו זר ועלה וכו'. בפ' חטאת העוף (זבחים דף ס״ט) א״ר יצחק שמעתי שתים אחת קמיצת זר ואחת מליקת זר אחת תרד ואחת לא תרד [ולא ידענא] א״ר חזקיה מסתברא קמיצה תרד מליקה לא תרד מ״ש מליקה דישנה בבמה קמיצה נמי ישנה בבמה וכו' אלא אימא אין קידוש בכלי שרת במנחה בבמה. ופירש״י הילכך לא ילפינן זר במקדש לענין קמיצה מזר בבמה דלא דמי הך קמיצה להך קמיצה דבמקדש הואיל וקדשה בכלי שרת איפסלא בזר עכ״ל.",1,0],[3,15,"ומ\"ש רבינו כאילו לא נתקדש כלל. לעיל קאי וה\"ק וקומץ המנחה שקמצו זר ועלה ירד כאילו לא נתקדש כלל אע\"פ שזה פסול וזה פסול.",2,0],[3,15,"ומ\"ש ואחד הזר ואחד שאר הפסולים. הכי משמע משום דמהי תיתי לן לפלוגי בינייהו:",3,0],[3,16,"ואלו אם עלו ירדו וכו' עד אם עלו ירדו. משנה בפרק המזבח מקדש שם:",1,0],[3,17,"קומץ שמיצה שמנו על העצם וכו'. בפרק הקומץ רבה (מנחות דף כ״ג) בעיא דלא איפשיטא, ורש״י והראב״ד גורסים על העצים ומפרשים אותה בענין אחר וז״ל ההשגות א״א בנוסחא שלנו שמנו על העצים ומה שפירש וכו' עד וזה הבעיא במנחות פ' הקומץ. וז״ל הגמרא בעא רבא קומץ שמיצה שמנו על העצם מהו חיבורי עולים כעולים דמו או לאו כעולים דמו ומפרשה רבינו לענין ירד אם יחזיר ולא איפשיטא ופסק רבינו דיחזיר משום דמספיקא לא מזלזלינן בקדשים שלא להעלותם שמא הדין נותן להעלותם. ומה שהקשה הראב״ד שדבר הלמד מענינו הוא וכו' וחתם דבריו וזו הבעיא במנחות פ' הקומץ כלומר תדע שאין בעיא זו ענין עליה וירידה שהרי היא במנחות פרק הקומץ דמיירי בענין חסרון הקומץ או שמנו ואלו היתה ענין לירידה ועליה בזבחים פ' המזבח מקדש ה״ל לאתויי. ואני אומר שאע״פ שטענה זו טענה היא מ״מ אינה מכרחת ולפי גירסת רבינו הוצרך לפרש כמו שפירשה ויש כדמות ראיה לגירסת רבינו מדאמרינן עלה לאו היינו דר״י ור״ל דאתמר המעלה אבר שאין בו כזית ועצם משלימו לכזית וכו':",1,0],[3,18,"מזבח הפנימי מקדש פסולים וכו' עד וכן כל כיוצא בזה. בפרק שני דזבחים (דף כ\"ז:) ויהיבו טעמא בגמרא משום דמזבח הפנימי כלי שרת ופירש\"י שהוא כלי שרת ונמשח עם המשכן:",1,0],[3,18,"כשם שהמזבח מקדש את הראוי לו וכו'. משנה פרק המזבח מקדש (זבחים דף פ״ו).",2,0],[3,18,"ומ\"ש וכן כשיגיע לכלי שרת כל דבר הראוי לו מתקדש. שם.",3,0],[3,18,"ומ\"ש ולא יפדה לעולם. משנה בריש פרק המנחות (דף ק'):",4,0],[3,19,"אין כלי הלח מקדשות את היבש וכו'. משנה פרק המזבח מקדש (זבחים דף פ״ח).",1,0],[3,19,"ומ\"ש בד\"א במדות הלח ויבש וכו' אבל המזרקות מקדשות הלח והיבש. מימרא דשמואל שם ופ\"ק דמנחות (דף ח':):",2,0],[3,19,"כלי שרת מקדשים דם הפסול ליקרב. בר\"פ בתרא דכריתות (דף כ\"ג) תנן אשם תלוי שנודע שלא חטא לר' יוסי אם כבר נשחט וקיבל הדם בכוס יזרק ופסק כר' יוסי דנימוקו עמו:",3,0],[3,20,"כל כלי השרת אין מקדשין אלא במקדש. מימרא דשמואל בפ' המזבח מקדש.",1,0],[3,20,"ומ\"ש אלא מדעת. מימרא דר\"י פ\"ק דמנחות (דף ז').",2,0],[3,20,"ומ״ש ואין מקדשין אלא מתוכן. מימרא דשמואל בפ' המזבח מקדש (זבחים דף פ״ח).",3,0],[3,20,"ומ\"ש ואין מקדשין אלא שלימים ניקבו אם עושים מעין מלאכתן שהיו עושים והם שלימים מקדשין ואם לאו אין מקדשין. משנה שם.",4,0],[3,20,"ומ\"ש ואין מקדשין אלא מליאים. מימרא דשמואל שם.",5,0],[3,20,"ומ\"ש אבל המדות אין מקדשות חסרות אלא אם דעתו למלאותם וכו'. שם ופ\"ק דמנחות (דף ח') מימרא דר\"י וברייתא שניהם מליאים אין מליאים אלא שלימים וכו' א\"ר יוסי אימתי בזמן שאין דעתו להוסיף אבל דעתו להוסיף ראשון ראשון קידש ופירוש מלאים פירש\"י שיש בהם שיעור הצריך לאותו דבר ואין דעתו להוסיף פירש שאין דעתו להשלים השיעור. ומדברי רש\"י נראה שיש בנוסחא דידן בגמרא חסרון לשון המדבר בענין המדות.",6,0],[3,20,"ומה שכתב ואם אין [דעתו] למלאותן מקדשות להפסל אבל לא ליקרב. נראה שלמד כן מדאמרינן בפ\"ק דמנחות (דף ז') בעא מיניה מר\"י כלי שרת מהו שיקדשו פסולים (ופירש\"י) כגון אם קמץ זר ונתן בכלי ויש לדקדק שדין זה סותר מ\"ש לעיל בפ' זה כלי שרת מקדשים דם הפסול ליקרב. ושמא י\"ל דשאני בין דם לשאר דברים ועי\"ל שלמד כן מדאמרינן בס\"פ המזבח (דף פ\"ח) אין כלי הלח מקדשים את היבש אמר רב אין מקדשין ליקרב אבל מקדשין ליפסל:",7,0],[3,21,"כלי שרת מקדשין שלא בזמנן כו'. בס״פ שתי הלחם (מנחות דף ק'):",1,0],[3,23,"מזבח שנפגם וכו' אבל קדשים חיים שהיו שם בעזרה כשנפגם לא נפסלו וכו'. בפ' קדשי קדשים (זבחים דף נ״ט) אמר רב מזבח שנפגם כל הקדשים שנשחטו שם פסולים והכי א״ר [שמעון] ברבי משום רבי ישמעאל בר' יוסי ומייתי לה מדכתיב וזבחת עליו את עולותיך ואת שלמיך וכי עליו אתה זובח אלא כשהוא שלם ולא כשהוא חסר וכו' ור״י אמר אחד זה ואחד זה פסולים במאי קא מיפלגי רב סבר בעלי חיים אינם נדחים ור״י סבר ב״ח נדחים. ופירש״י שנשחטו שם בעזרה כשהוא שלם והאי עליו בגינו ובשבילו קאמר. אחד זה ואחד זה בין שנשחטו בשעת פגימתן בין שנשחטו אחר תיקונו פסולים. ופסק רבינו כרב ונתבאר בפט״ו מהלכות מעשה הקרבנות:",1,0],[3,24,"הקדיש בהמות עד שלא נבנה המזבח כו'. שם אהא דתניא כל הקדשים שהיו עד שלא נבנה המזבח פסולים פריך נבנה דחויים מעיקרא נינהו כלומר וכשרים הם:",1,0],[3,25,"וכן אין אוכלים קדשים והמזבח פגום וכו'. שם (דף ס') א\"ר אלעזר מזבח שנפגם אין אוכלים בגינו שירי מנחה שנאמר ואכלוה מצות אצל המזבח וכי אצל המזבח אכלוה אלא בזמן שהוא שלם ולא בזמן שהוא חסר אשכחן שירי מנחה קדשי קדשים מנ\"ל ת\"ל קדש קדשים קדשים קלים מנין אמר אביי אתיא מדרשא דר' יוסי וכו':",1,0],[4,1,"ולד חטאת ותמורת חטאת וכו'. משנה רפ\"ד דתמורה (דף כ\"א:) ופ\"ג דמעילה (דף י':).",1,0],[4,1,"ומ\"ש נמצאת אחר שנשחטה החטאת השניה שהפריש קודם שיזרק דמה ה\"ז ספק וכו'. בפ\"ד דתמורה (דף כ\"ב:) בעיא דלא איפשיטא.",2,0],[4,1,"ומ\"ש וכיצד הן מתות וכו'. פ\"ק דע\"ז ופ\"ד דנזיר (דף כ\"ה).",3,0],[4,1,"ומ\"ש ודברים אלו כולם מפי משה רבינו נשמעו. ברפ\"ג דתמורה (דף י\"ח) ופ\"ב דבכורות (דף ט\"ז):",4,0],[4,1,"אין כל הדברים אמורים וכו' עד ואין כל ישראל מתים. בפרק שני דתמורה (דף ט\"ו):",5,0],[4,2,"פר ושעיר של יום הכפורים וכו'. בפ' שני שעירי (יומא דף ס״ה) פלוגתא דתנאי ופסק כר' אלעזר בר״ש דסתם מתני' כוותיה ובפירקא קמא דשבועות (דף י״ב) מייתי לה וגריס ר' אלעזר ור״ש ולפי גירסא זו פסק כוותייהו משום דרבים נינהו.",1,0],[4,2,"ומ\"ש ולמה לא יקרבו עצמם נדבה וכו'. בפ\"ק דשבועות שם:",2,0],[4,3,"המפריש חטאתו ואבדה וכו'. בפ\"ד דתמורה (דף כ\"ב:) איפליגו ר' ורבנן בנמצאת קודם כפרה דלרבי תמות ולרבנן תרעה וידוע דהלכה כרבנן ואמר רב הונא אמר רב (דף כ\"ג) הכל מודים שאם משך אחת והקריבה שהשניה מתה לא נחלקו אלא בבא לימלך דרבי סבר לא עשו תקנה בקדשים וכו' ורבנן סברי עשו תקנה בקדשים ואמרינן ליה התכפר באבודה ושאינה אבודה תרעה. ופירש\"י שאם משך אחת מהן והקריבה מדעתו דחה האחרת בידים דגלי דעתיה דלא איכפת לי' מינה ואפי' משך האבודה ונתכפר בה והנשארת היא שלא נאבדה מעולם מתה וכי פליגי רבנן היינו בבא לימלך דגלי דעתיה דניחא ליה עכ\"ל. ואע\"ג דר' אבא פליג ארב הונא פסק רבינו כרב הונא משום דמסתבר טעמיה ועוד דאתיא ליה סתם מתני' כדברי הכל:",1,0],[4,3,"היתה אחת מהן תמימה ואחת בעלת מום וכו'. בפ\"ד דתמורה (דף כ\"ד) תניא היו לפניו שתי חטאות אחת תמימה ואחת בעלת מום תמימה תקרב בעלת מום תפדה נשחטה בעלת מום עד שלא נזרק דמה של תמימה מותרת משנזרק דמה של תמימה אסורה ר' אלעזר בר\"ש אומר אפילו בשר בעלת מום בקדירה ונזרק דמה של תמימה יוצא לבית השריפה. ונראה מדברי רבינו שהוא פוסק כר' אלעזר בר\"ש וצריך טעם למה פסק כיחידאה ואפשר שטעמו משום דבגמרא העמידו ברייתא דאין מרגילין כראב\"ש ושקלו וטרו אמוראי בטעמא. ויותר נראה לומר שפסק כרבנן ויש חסרון בדברי רבינו וכך צריך להגיה נשחטה בעלת מום קודם שיזרק דם התמימה מותרת אחר שנזרק דמה אסורה בהנאה:",2,0],[4,3,"היו שתיהן בעלי מומין ימכרו שתיהם וכו'. משנה שם (דף כ\"ב):",3,0],[4,4,"הפריש חטאתו ואבדה וכו'. מימרא דר' זירא פ' התודה (מנחות דף פ':) ואע״ג דאביי פליג עליה פסק רבינו כר' זירא וצריך טעם למה מאחר דאביי בתרא הוא, ואפשר שטעמו משום דאמאי דאמר התם רבא הפריש תודתו ואבדה וחזר והפריש אחרת תחתיה וכו' א״ר זירא וכן לענין חטאות הפריש חטאתו ואבדה והפריש אחרת תחתיה וכו' וכיון דר״ז בשיטת רבא אמרה פסק כמותו ולא חש לדאביי:",1,0],[4,5,"המפריש שתי חטאות וכו'. פרק כיצד מערימין (תמורה כ\"ה).",1,0],[4,5,"ומה שכתב והשניה תרעה וכו'. פרק ולד חטאת (שם כ״ד) ופרק מי שהיה טמא (פסחים צ״ז:):",2,0],[4,6,"הפריש חטאת מעוברת וילדה וכו'. מימרא דר״י פרק כיצד מערימין (תמורה דף כ״ה):",1,0],[4,7,"המפריש חטאתו ועברה שנתה וכו'. מימרא דר\"ל רפ\"ד דתמורה.",1,0],[4,7,"מ\"ש וכן הפריש חטאתו ונפל בה מום יביא בדמיה אחרת. משנה בספ\"ד דתמורה (דף כ\"ב):",2,0],[4,8,"כל חטאת שאבדה וכו'. ברפ\"ד דתמורה תנן ולד חטאת וחטאת שמתו בעליה ימותו שעברה שנתה ושאבדה ונמצאת בעלת מום אם משכיפרו הבעלים תמות וכו' ואם עד שלא כיפרו הבעלים תרעה עד שתסתאב ותמכר ויביא בדמיה אחרת ובגמרא אמר ר\"ל חטאת שעברה שנתה רואין אותה כאילו עומדת בבית הקברות ורועה. ופירש\"י רועה עד שתסתאב. תנן שעברה שנתה ואבדה ונמצאת בעלת מום אם אחר שכיפרו בעלים מתה תיובתא ופירש\"י תיובתא דר\"ל דפסיק ואמר רועה ומשמע אפי' כפרו הבעלים. ואסיקנא הכי קתני עברה שנתה ואבדה או אבדה ונמצאת בעלת מום אחר שכיפרו הבעלים מתה קודם שכיפרו הבעלים תרעה עד שתסתאב ותמכר ופירש\"י עברה שנתה ואבדה ונמצאת תמימה וכיפרו הבעלים באחרת או אבדה ונמצאת בעלת מום דאיכא נמי תרתי לריעותא וכיפרו הבעלים באחרת מתה קודם שכיפרו הבעלים שאין רוצים להתכפר באחרת תרעה הך דעברה שנתה ואבדה ונמצאת תמימה וכי אמר ר\"ל דאפי' כיפרו אח\"כ רועה בלא אבדה דחדא הוא דאיכא לריעותא. ונראה שיש ייתור לשון בדברי רבינו וצריך למוחקו וכך צריך להגיה כל חטאת שאבדה ונמצאת קודם כפרה אינה מתה אלא תרעה עד שיפול בה מום ויפלו דמיה לנדבה:",1,0],[4,9,"היתה גנובה או גזולה וכו'. מימרא דאביי שם:",1,0],[4,9,"היתה עיקר אבידתה בלילה אע\"פ שהיתה אבודה בשעת כפרה אינה מתה אלא תרעה. ג\"ז שם:",2,0],[4,10,"אבדה ממנו ולא מן הרועה וכו'. מימרא דרב פפא שם:",1,0],[4,11,"וכל אלו שרועות רועות עד שיפול בהם מום ויפלו דמיהן לנדבה. בפ' שלישי דתמורה (דף י\"ט):",1,0],[4,12,"היתה אבודה ממנו ומן הרועה וכו'. בפ\"ד דתמורה (דף כ\"ב:) בעיא דלא איפשיטא:",1,0],[4,13,"היתה נחבאת אחורי הדלת. שם ה\"ד אבודה א\"ר אושעיא אפילו אחת בעדרו וכו' ור\"י אמר אחורי הדלת הוא דליכא דקא חזי לה אבל אבראי דאיכא דחזי לה לא הויא אבודה או דילמא אחורי הדלת דאי מהדר אפיה חזי לה הויא אבודה וכ\"ש אבראי דלא קחזי לה תיקו. ופסק רבינו כר\"י ונראה שהוא מפרש אבראי בסתר המדרגה ומספק פסק לחומרא. ורש\"י פירש בע\"א:",1,0],[4,13,"היתה בשדה או באגם וכו'. אפשר שרבינו מפרש שגם זה בכלל אבראי שכתבתי בסמוך:",2,0],[4,14,"השולח חטאתו ממדינת הים וכו'. משנה בפ' כל הגט (גיטין דף כ״ח).",1,0],[4,14,"ומ\"ש בד\"א בחטאת העוף וכו'. שם בגמרא (כ\"ח:) והא בעי סמיכה אמר רב יוסף בקרבן נשים רב פפא אמר בחטאת העוף:",2,0],[4,14,"אבל אשם ודאי שמתו בעליו וכו'. משנה פ\"ג דתמורה (דף כ\"א ע\"ב).",3,0],[4,14,"ומ\"ש שכל שבחטאת תמות באשם ירעה וכו'. ברפ\"ג דתמורה (דף י\"ח):",4,0],[4,15,"וכל אשם שניתק לרעייה אם הקריבו עולה כשר. שם ופ״ק דמנחות (דף ד') ובפסחים פרק אלו דברים (פסחים דף ע״ג) [ובזבחים פ״א (דף ה':)] אמר רב הונא אמר רב אשם שניתק לרעייה ושחטו סתם כשר לעולה ניתק אין לא ניתק לא ופירש״י שניתק לרעייה שמתו בעליו או שנתכפרו באחר וניתק מדין אשם לרעייה שאמרו לו ב״ד הוציאו וירעה ושחטו סתם כשר לעולה הואיל וסופו לקיץ המזבח שהוא עולה. ניתק אין דמיעקר שם אשם מיניה משנמסר לרועה וקם סתמיה לעולה לא ניתק לא הוי סתמיה לעולה דאמר קרא [אשם] הוא בהוייתו יהא. ובפסחים פרק אלו דברים מסיק עלה לא תימא ששחטו סתם [כשר לשום עולה] אלא אימא שחטו לשום עולה כשר.",1,0],[4,15,"ומ\"ש רבינו ולמה לא יקרב בעצמו לכתחלה וכו'. בפסחים פ' אלו דברים שם:",2,0],[4,16,"המפריש נקבה לאשמו וכו' עד ויפלו דמיה לנדבה. משנה בפ\"ג דתמורה (דף י\"ט:).",1,0],[4,16,"ומ\"ש וכן ולדה. שם אהא דתנן דמפריש נקבה לעולה וילדה זכר ירעה עד שיסתאב וימכר ויביא בדמיו עולה ר\"א אומר הוא עצמו יקרב עולה א\"ר יוסי בר חנינא מודה ר\"א במפריש נקבה לאשם דאין בנה קרב אשם:",2,0],[4,17,"הפריש נקבה לעולתו וילדה זכר וכו'. משנה כתבתיה בסמוך:",1,0],[4,18,"ומ\"ש אבל הדיוט שהפריש זכר לחטאת ונשיא שהפריש שעירה לחטאת וכו'. שם ת\"ר המפריש נקבה לעולתו ולפסחו ולאשמו עושה תמורה וכו' עד ראב\"ע אומר תור או בן יונה. ופירש\"י לפסחו ולאשמו לא מצינו אשם ופסח נקבה וכו' עד דאפילו גבי נדבה דעשיר סתם חזיא עולת העוף:",1,0],[4,18,"וכתב הראב\"ד אבל הדיוט וכו' עד הרי אלו אין מתקדשים א\"א אין דבריו מחוורים שכל אותם דברים וכו' עד לפרושי טעמא דר\"ש באשם. ואיני יודע איך נתפייס הראב\"ד ביישוב השגה זו במ\"ש ואולי מפני שאמר רבינו אין אני רואה דבריו של ר\"ש בפסח וכו' שאילו היה רבינו פוסק במפריש נקבה לאשם תמכר כר\"ש היו טענות אלו טענות אבל מאחר שרבינו פוסק בה שתרעה וכרבנן אין טענות אלו טענות דה\"ל כמזכי שטרא לבי תרי. ואפשר לדחוק ולומר שטעם רבינו הוא מדאמרינן אלא מעתה כהן גדול שהקדיש פרה לפרו תקדש יחיד שהפריש שעיר לשעירתו תקדש א\"נ נשיא שהפריש שעירה לשעירו תקדש משמע דפשיטא ליה לגמרא בכל הני דלא קדש לדברי הכל ואע\"ג דבמקריב נקבה לאשם סבר ת\"ק דתרעה בהני דחטאת נינהו סבר דלא קדשי:",2,0],[4,19,"הביא אשם תלוי ונודע לו שלא חטא וכו'. בכריתות רפ\"ו (דף כ\"ג:) המביא אשם תלוי ונודע לו שלא חטא [אם עד שלא נשחט] יצא וירעה בעדר דברי ר\"מ וחכ\"א ירעה עד שיסתאב וימכר ויפלו דמיו לנדבה ובגמרא במאי פליגי ר\"מ סבר כיון דלא צריך ליה לא מקדיש ליה ורבנן סברי מתוך שלבו נוקפו גומר ומקדיש תנא בין שנודע לו שחטא ובין שנודע לו שלא חטא פליגי ר\"מ ורבנן.",1,0],[4,19,"ומ\"ש הפרישו אפי' ע\"פ עדים והוזמו יפלו דמיו לנדבה. שם (דף כ\"ד) א\"ר יהודה אמר רב מודים חכמים [לר\"מ] באשם תלוי שהוזמו עדיו שיצא וירעה בעדר מ\"ט ע\"כ לא פליגי רבנן עליה אלא היכא דאפרשיה על פי עצמו דאמרי' לבו נוקפו אבל היכא דע\"פ עדים אפרשיה לא הוה סמוך עילוויהו דעדים דסבר דילמא אתו אחרים ומזמי להו מתיב רבא שור הנסקל אינו כן וכו' בפלוגתא אשם תלוי שהוזמו עדיו ר' אלעזר אומר הרי היא כמנחת קנאות וכו' תצא לחולין ר\"י אמר ירעה עד שיסתאב וימכר ויפלו דמיו לנדבה ופסק רבינו כר\"י לגבי רב ועוד דרבא דבתרא הוא מתיב לרב ואע\"ג דשני שינויא דחיקא הוא.",2,0],[4,19,"ומ\"ש רבינו יפלו דמיו לנדבה. כלומר אחר שרעה עד שנסתאב.",3,0],[4,19,"ומ\"ש ואם אחר שנשחט נודע לו הדם ישפך והבשר ישרף וכו'. שם במשנה.",4,0],[4,19,"ומ\"ש נודע לו אחר שנזרק הדם הבשר יאכל וכו'. ג\"ז שם במשנה:",5,0],[4,20,"אשם ודאי אינו כן וכו' עד הבשר יצא לבית השריפה. גם זה שם במשנה:",1,0],[4,21,"מי שנתחייב באשם תלוי וכו'. שם א\"ר ששת דמודה ר\"מ בהא [ויהיב טעמא] משום דכיון דאפריש תרי סבר אי מירכס חד מיכפרנא באידך וכיון דגלי דעתיה דלבו נוקפו היה כו' גמר והקדישו ופירש\"י לאחריות שאם יאבד האחד יקריב לחבירו:",1,0],[4,22,"כל האשמות שבתורה באים בני שתים וכו'. משנה בפרק כל התדיר (זבחים דף צ':) ופירש רש\"י ובאים בכסף שקלים (כדיליף בפרק דם שחיטה) דכתיב בערכך כסף שקלים באשם מעילות ואתי אשם תלוי ואשם גזילות בג\"ש בערכך בערכך ואשם שפחה חרופה גמר באיל באיל וכו'. חוץ מאשם נזיר. דכתיב כבש בן שנתו ומדאיל בן שתי שנים בשתי סלעים כבש בן שנה לאו בשתי סלעים הוא:",1,0],[4,22,"אשם תלוי בא מן הקטנים או מן הגדולים. ומה שכתב מפי השמועה למדו שאינו בא אלא בכסף שקלים. בפרק דם שחיטה (כריתות דף כ״ב:) יליף מקרא דאשם תלוי בכסף שקלים:",2,0],[4,23,"הוזלו אילים וכו'. בסוף כריתות (דף כ\"ז):",1,0],[4,24,"הפריש אשמו והיה בשעת הפרשה יפה סלע וכו'. שם איבעיא להו אדם מתכפר בשבח הקדש או לא ואסיקנא ת\"ש בשעת הפרשה יפה סלע בשעת כפרה יפה שתי סלעים יצא:",1,0],[4,24,"היה בשעת הפרשה יפה שתים וכו'. תוספתא בסוף כריתות.",2,0],[4,24,"ומ\"ש חזר ונעשה יפה שתים יחזור לכשרותו שאין ב\"ח נדחים כמו שביארנו. בפט\"ו ממעשה הקרבנות:",3,0],[4,25,"הפריש שתי סלעים לאשם וכו'. משנה שם (דף כ\"ו:):",1,0],[4,26,"היה חייב באשם בן שנה והביא בן שתים וכו' עד ויצא לבית השריפה. [בתוספתא דזבחים פ״ק] ובפ' התכלת (מנחות דף מ״ח:):",1,0],[4,26,"זה הכלל כל הפסול בחטאת פסול באשם וכו'. בתוספתא דזבחים פ\"ק שם:",2,0],[4,27,"עולת נזיר עולת יולדת וכו'. בתוספתא דזבחים פ\"ק אלא שכתוב שם שלא עלו לבעלים לשם חובה ולא ידעתי למה השמיטו.",1,0],[4,27,"ומ\"ש זה הכלל כל שאינו פוסל בעולת נדבה וכו'. ג\"ז שם:",2,0],[5,1,"המפריש מעות לחטאתו וכו'. משנה בכמה מקומות מהם פרק ד' דנזיר (דף כ\"ד) ופרק ג' דמעילה (דף י\"א):",1,0],[5,2,"הפריש מעות לחטאתו ואבדו וכו' עד ולא הספיק ליקח בהם עד שנמצאת חטאתו והרי היא בעלת מום תמכר ויביא מאלו ומאלו חטאת והשאר יפלו לנדבה. הכל משנה בפ\"ד דתמורה (דף כ\"ב):",1,0],[5,5,"הפריש שני צבורי מעות לאחריות וכו'. מימרא דר' אמי שם (דף כ\"ג:):",1,0],[5,6,"המפריש חטאתו או דמי חטאתו וכסבור שהוא חייב וכו'. ירושלמי בפ\"ב דשקלים.",1,0],[5,6,"ומ\"ש הפריש שתים או דמי שתים וכו'. שם הפריש ב' וסבור שהוא חייב ב' ונמצא שאינו חייב אלא אחת אותה השניה מה את עביד לה אלא רועה.",2,0],[5,6,"ומ\"ש והשאר יפלו לנדבה, אדמי שתים קאי כפשטיה ואשתים היינו לומר רועה עד שתסתאב ויפלו דמיה לנדבה:",3,0],[5,7,"הלוקח מעות בידו או וכו'. שם במשנה המכנס מעות ואמר הרי אלו לשקלי ב\"ש אומרים מותרן נדבה ובית הלל אומרים מותרן חולין אלו לחטאתי שוין שהמותר נדבה שאביא מהם חטאתי שוין שהמותר חולין ופירושה מבואר דכשאומר שאביא מהם חטאתי לא הקדיש אלא מה שצריך מהם לחטאתו בלבד ורבינו כתב סיפא והשמיט רישא אלו לחטאתי ולא ידעתי למה.",1,0],[5,7,"ומ\"ש הלוקח מעות בידו או שהיה מלקט. שם בירושלמי לגבי שקלים חילקו בין מכניס פרוטרוט לאומר אלו לשקלי ורבינו שהשוה אותם לענין שאביא מהם חטאתי צ\"ע מהיכא יליף לה.",2,0],[5,7,"ועל מ\"ש רבינו שנ\"ל שהדבר ק\"ו בשאר הקרבנות. כ' הראב\"ד א\"א אני אין לי אלא קרבן חובה וכו'. ואני בעניי נ\"ל שי\"ל דאפי' בעולה ושלמים כל שאמר שאביא מהם משמע שלא התנדב כל אותם הדמים דלשון שאביא מהם מורה שלא הקדיש מהם אלא כדי עולה ושלמים בלבד ומה ששנינו מותר עולה לעולה מותר שלמי' לשלמי' אינו אלא באומר הרי אלו לעולה או לשלמים אבל אם אמר שאביא מהם עולה או שלמים דינו כאומר שאביא מהם חטאתי או אשמי שלא הקדיש מהם אלא כדי אותו קרבן שאמר בין שהוא חובה בין שהוא נדבה:",3,0],[5,8,"המפריש מעות למנחת חוטא וכו'. בפירקא בתרא דמנחות (דף ק\"ח):",1,0],[5,8,"וכן מותר לחמי תודה. בפ\"ב דשקלים ירוש' מותר לחמו של נזיר ירקב א\"ר יוסי ויאות להקריבו בפ\"ע אי אתה יכול שאין לך לחם קרב בפ\"ע להקריבו עם נזירות אחרת אי אתה יכול שאין לך נזירות באה בלא לחם לפום כן איצטריך למימר מותר לחמו של נזיר ירקב סברין למימר הוא מותר לחמו הוא מותר נסכים א\"ר יוסי בר ביבין מותר נסכים קדשי קדשים אינון ויפלו לנדבה.",2,0],[5,8,"ומ\"ש מותר לחמי תודה. נראה שהוא נלמד מדין מותר לחמו של נזיר שהטעם בשניהם שוה:",3,0],[5,8,"כבר ביארנו בשקלים שמותר השקלים חולין וכו' עד מותר נזיר לאותו נזיר. הכל משנה במס' שקלים פ\"ב:",4,0],[5,9,"במה דברים אמורים שמותר חטאת לנדבה וכו'. מה שכתב רבינו שאם הפריש מעות לחטאת בהמה והעני מביא תחתיהן עוף וכו' עד שאין לעוף פדיון. הכל משנה בסוף כריתות ומתוך שנראה דמתני' דשקלים ומתני' דסוף כריתות (דף כ\"ז:) קשו אהדדי תירץ רבינו דמתני' דשקלים בחטאת קבועה ומתני' דסוף כריתות בקרבן עולה ויורד:",1,0],[5,11,"כל חייבי קינין שבתורה שהפרישו מעות לקיניהם וכו' עד שאין הקינין מתפרשות אלא בלקיחת הבעלים. בפרק טרף בקלפי (יומא דף מ״א) ובסוף כריתות (דף כ״ח) אמר רב חסדא אין הקינין מתפרשות אלא או בלקיחת הבעלים או בעשיית כהן. פי' בלקיחת הבעלים כשקנאם אמר זה לחטאתי וזה לעולתי אבל אם קנה שנים לחובתו ואחר זמן אמר זה לחטאתי וזה לעולתי לא הוקבעו ויכול לשנותם:",1,0],[5,12,"ומ\"ש לפיכך אם הפריש מעות לקינין סתם וכו'. הוא ע\"פ מה ששנינו בפ' ולד חטאת וכתבו רבינו בפ' זה:",1,0],[5,13,"מי שהיה מחוייב וכו' רצה להביא בהם חטאת בהמה יביא עולת בהמה יביא תוספתא בפ\"ק דמעילה אלא שאינה מכוונת בלשון רבינו וזה לשון הראב\"ד א\"א מצאתי דבר זה בגמרא דנזיר ובתוספתא שהוא בחילוף וכו' עד אמאי ילכו לים המלח. ומ\"ש שהוא בגמ' נזיר הוא בפ\"ד (דף כ\"ו) מי שהיה מחוייב חטאת ואמר הרי עלי עולה והפריש מעות ואמר הרי אלו לחובתי רצה להביא בהם חטאת בהמה לא יביא עולת בהמה לא יביא מת והיו לו מעות סתומים ילכו לים המלח ורבינו גורס יביא.",1,0],[5,13,"ומ\"ש הראב\"ד מסתבר דהכי הוא וכו' כלומר הוא משיג על גירסת רבינו שאם רצה להביא מהם חטאת או עולה יביא וא\"כ למה כשמת ילכו לים המלח מ\"ש ממה שנתבאר בסמוך גבי הפריש מעות לקינין סתם ומת שיפלו לנדבה מפני שהם ראויים לבא כולם עולה. ואפשר שגירסת רבינו רצה להביא חטאת בהמה יביא עולת בהמה לא יביא והטעם מבואר דלא שביק איניש מלהביא מה שהיה חייב מקודם ומביא מה שנתחייב אח\"כ וכ\"ש בהיות מה שנתחייב תחלה חטאת ומה שנתחייב אח\"כ עולה. ומ\"ש הראב\"ד בשם התוספתא שאם מת יפלו המעות לנדבה מפני שכולם ראויים לבא עולה. הוא בפ\"ק דמעילה ומסיים בה מת הדמים ילכו לים המלח מפני שדמי חטאת מעורבין בהם וקשה עליו וגם על התוספתא למה אם רצה להביא בהם עולת העוף לא יביא מ\"ש ממ\"ש בסמוך שאפי' אמר אלו דמי חטאתי ואלו דמי עולתי יש לו לערב המעות ולוקח בכל חטאת או עולה. ונראה שמפני שהרגיש הראב\"ד בקושיא זו כתב והתוספתא יותר מתוקנת מן הגמרא כלומר אע\"פ שגם על התוספתא קשה למה לא יביא עולה מ\"מ היא מתוקנת יותר מהגמרא מפני שעל הגמ' קשה מינה ובה:",2,0],[6,1,"כל הזבחים שנתערב וכו'. משנה ריש פרק התערובות (דף ע':).",1,0],[6,1,"ומה שכתב ואם הקריב הורצה. שם אמר רבא אי אקריב ארצי ואותבוה ממתני' דקינין ואוקמוה ההיא מתניתין כמאן דאמר בעלי חיים אין נדחים. וכבר נתבאר בפרק ט\"ו ממעשה הקרבנות דהלכה כמאן דאר אין בעלי חיים נדחים:",2,0],[6,2,"נתערב בהם אחד וכו'. עד שהרי דמי חולין הם. משנה שם:",1,0],[6,4,"נתערב שור הקדש בשוורים. בפ' בתרא דמנחות (דף ק\"ח:) שור של הקדש שנתערב באחרים הגדול שבהם הקדש וכלם ימכרו לצרכי עולות ודמיהם חולין, ודבר פשוט דלדוגמא נקט עולות כלומר אם היה אותו שור עולה ומינה נילף שאם היה מין זבח אחר ימכרו לצרכי אותו המין וכן מפורש בתוספתא בפרק הנזכר:",1,0],[6,4,"נתערבו קדשים בקדשים וכו'. משנה בפרק התערובות (דף ע\"ח:).",2,0],[6,4,"ומ\"ש בד\"א בקרבנות נשים וכו'. שם מימרא דרב יוסף (דף ע\"ד:):",3,0],[6,5,"נתערבו מין בשאינו מינו וכו'. משנה שם (דף ע\"ה:):",1,0],[6,6,"ומ\"ש שאין ממעטין באוכליהן ולא במקום אכילתן. נתבאר בפ\"י ממעשה הקרבנות:",1,0],[6,7,"ומ\"ש אע\"פ שכבר הקריב עולה שחייב בה או שלמים וכו'. תוספתא בפ\"ח ממס' זבחים:",1,0],[6,8,"חטאת שנתערבה וכו'. תוספתא פרק ח' דזבחים אלא ששם כתוב שנתערבה באחת מכל הזבחים:",1,0],[6,8,"ואם קדם והקריב וכו'. שם:",2,0],[6,9,"וכן אם נתערבו וכו'. גם זה שם:",1,0],[6,9,"כתב הר\"י קורקוס ז\"ל איני יודע טעם למיתה זו או להולכת מעות לים המלח כי כבר נתבאר שלא קבלו ההלכה שחטאת מתה אלא באבודה דוקא לא בגנובה. ואפשר היה לומר דנתערבה הוי אבידה טפי מגניבה וכאשר הוזכר פ\"ד דתמורה (דף כ\"ב:) בדעת ר' אושעיא שאפילו נתערבה אחת באחת הויא אבודה ואפי' בדברי ר\"י שאמרו שם אבל אבראי כתב רש\"י שהלכה ונתערבה. אלא שאין נראה כן דעת רבינו כלל כי דברי הבעיא דבעי אליבא דר\"י פי' באבודה ומשום שמא יש אחד שרואה אותה ולא הזכיר נתערבה או שסובר דאביי דאמר נקטינן אבודה ולא גזולה פליג או שר\"י חולק וסובר שאין תערובת אבודה אלא אחורי הדלת וכאשר כתב רש\"י בצד אחד מהבעיא דבעדר כיון דחזו לכולהו אף על פי שאינה ניכרת אינה אבודה ופסק כר\"י כיון דבעי אליביה ואם כן מיתה זו כאן למה כיון דאפשר ברעיה וצל\"ע עכ\"ל:",2,0],[6,10,"תודה שנתערבה וכו'. שם:",1,0],[6,10,"כתב הראב\"ד תודה שנתערבה א\"א והא קא ממעט באכילת זרוע בשלה עכ\"ל. ואסיפא דמלתא קאי דקתני נתערבה באיל נזיר שניהם יקרבו וכו' ומשיג על רבינו שמאחר שכל אחד מהם ספק איל נזיר צריך ליקח מכל אחד מהם זרוע בשלה ואינו נאכל אלא לכהנים ובני ביתם ונמצא שממעט באכילת זרוע של תודה שדינה ליאכל לכל אדם. ואני אומר שאם השגה זו השגה אינה על רבינו מפני שהוא העתיק דברי התוספתא אבל לפי האמת אפשר לומר דכיון שאינו ממעט באכילת כל הקרבן אלא במקצתו לא חיישינן:",2,0],[6,10,"כתב הראב\"ד ויביא בדמי היפה א\"א אינה טעונה לחם עכ\"ל. ונ\"ל שהשגה זו היא על",3,0],[6,10,"מ\"ש וכן אם נתערבה התודה בשאר זבחים וכו' ויביא בדמי היפה תודה אחרת וכתב על זה שאינה טעונה לחם וכ\"נ מדברי התוספתא ורבינו שלא הזכירו כאן לחם וצריך טעם למה לא יביא לחם בשביל התודה כשם שהוא מביא בנתערבה בתמורתה שאע\"פ שאין התמורה טעונה לחם מביא לחם בשביל התודה. ונ\"ל דלא קאי אלא אסיפא דקתני אע\"פ שקרבה תודתו דהשתא כיון דקרבה תודתו שוב אין כאן לחם. ומכל מקום תמיהא לי דמילתא דפשיטא היא ולא היה צריך הראב\"ד לכתבו ושמא י\"ל דאתא לאשמועינן דבבא זו אע\"פ שנראה ששוה סיפא דידה לרישא דידה אינם שוים לגמרי דרישא דנתערבה בשאר זבחים יביא עמה לחם וסיפא דקרבה תודתו לא יביא עמה לחם:",4,0],[6,12,"בכור שנתערב בפסח שניהם ירעו וכו'. בפרק מי שהיה טמא (פסחים דף צ\"ח) תנן הפסח שנתערב בבכורות רבי שמעון אומר אם חבורת כהנים יאכלו ובגמרא והא קא מייתי קדשים לבית הפיסול וכו' ורבנן היכי עבדינן אמר רבא ממתין לו עד שיוממו ויביא בהמה שמינה ולימא כל היכא דאיתיה לפסח תחול עליה דהאי ואכיל להו בתורת בכור בעל מום. ופירש רש\"י ורבנן דאמרי אין מביאין (קדשים לבית הפיסול) היכי עבדי לפסח שנתערבה בבכורות בשלמא גבי אשם שנתערב בשלמים או פסח שנתערב בעולה ואשם איכא למימר ירעו וימכרו ויביא בדמיהם אותם קרבנות וכו' אבל בכור נאמר בו לא תפדה ואין לו פדיון ואינו תופס את דמיו ואינו יוצא מקדושתו לחול על המעות אלא נאכל לכהן במומו ופסח בר פדיון הוא ואינו נאכל בלא פדיון. ממתין עד שיוממו ויביא בהמה שמינה כיפה שבהם ונימא כל היכא דאיתיה לפסח תיחול קדושתה אהנך מעות ומייתי בהנך מעות שלמים כדין מותר הפסח עכ\"ל:",1,0],[6,12,"כתב הראב\"ד בכור שנתערב ויאכלו כבכור א\"א והבכור בעל מום וכו'. ואני תמה על מה שהשיג על רבינו בכור בעל מום אי זו אכילה חמורה יש בו שאין תלונתו על רבינו דרבינו לישנא דגמ' נקט דקאמר דאכיל להו בתורת בכור בעל מום כ\"ש שלפי האמת אין כאן תלונה כלל שהרי פירש רש\"י ואכיל להו לכל התערובת בתורת בכור בעל מום ואי זו היא תורתו אינו נשחט באיטליז ואינו נמכר באיטליז ואינו נשקל בליטרא ואם היה מכיר בפסח שנפדה היה שוחטו ומוכרו באיטליז אם ירצה עכ\"ל. ומ\"ש מה תיקן לבעל הפסח והיה צריך לפרש תיקונו. י\"ל שרבינו סמך על מ\"ש בפרק רביעי מקרבן פסח:",2,0],[6,13,"וכן מעשר וכו'. בתוספתא דזבחים פרק שמיני:",1,0],[6,13,"הבכור והמעשר שנתערבו וכו'. שם ודלא כר\"ש:",2,0],[6,14,"וכן שאר קדשים וכו'. משנה בפרק התערובות (דף ע\"א:):",1,0],[6,15,"אשם שנתערבה וכו'. משנה בפרק התערובות (דף ע\"ה:) וכרבנן דפליגי ארבי שמעון.",1,0],[6,15,"ומה שכתב ואם קדם והקריב אשמו שניהם יפלו לנדבה. תוספתא פרק ח' דזבחים:",2,0],[6,16,"כל הקדשים אפשר וכו'. משנה בפרק התערובות (דף ע\"א:):",1,0],[6,17,"וכל אלו המתערבים וכו'. שם אמר רבא השתא דאמרי רבנן לא נקריב אי אקריב לא מרצי ואותביה ממתני' דקינים ושני הא כמאן דאמר בעלי חיים נדחים הא כמאן דאמר אינם נדחים וכיון דפסק רבינו כמאן דאמר בעלי חיים אינם נדחים כמו שנתבאר בפרק ט\"ו ממעשה הקרבנות ממילא קמה לה הלכתא דלא כרבא ואע\"ג דרבא בתרא הוא וה\"ל למיפסק כוותיה איכא למימר דאליבא דמאן דאמר בעלי חיים נדחים אמרה וליה לא ס\"ל:",1,0],[6,18,"בהמה שנמצאת מירושלים ועד וכו'. בפ״ז דשקלים תנן בהמה שנמצאת מירושלים ועד מגדל עדר וכו' זכרים עולות ונקבות זבחי שלמים ומייתי לה בפרק האיש מקדש (קידושין דף נ״ה) ומסיק עלה ר״י ממתין לה עד שתומם ומייתי שתי בהמות ומתנה וכו' זכרים עולות דילמא תודה היא דמייתי נמי תודה והא בעיא לחם דמייתי נמי לחם ודילמא אשם הוא אשם בן שתי שנים ואישתכח בן שנה ודילמא אשם מצורע הוא נזיר הוא לא שכיחי ודילמא פסח הוא פסח בזמנו מיזהר זהירי ביה ושלא בזמנו שלמים הוא ודילמא בכור ומעשר הוא למאי הלכתא למיכלינהו במומן ה״נ במומן מתאכלי וכו' נקבות זבחי שלמים דילמא תודה היא דמייתי תודה והא בעי לחם דמייתי נמי לחם ודילמא חטאת היא חטאת בת שנתה ואשתכח בת שתי שנים ודילמא חטאת שעברה שנתה לא שכיח אשתכח בת שנתה מאי וכו' אמר אביי (בת שנתה) כחטאת (ודאי) כונסה לכיפה והיא מתה מאליה ומשמע מדברי רבינו דכי אמרינן דמייתי תודה היינו לומר דמייתי לה ומתנה עליה ואומר אם שלמים היא הריני מקריבה לשם שלמים ואם תודה היא הריני מקריבה לשם תודה דתרווייהו קדשים קלים נינהו ומתנותיהם שוה ותאכל כחמור שבהם ליום ולילה עד חצות.",1,0],[6,18,"ומ\"ש רבינו ונסכיו משל צבור. בפ\"י דשקלים:",2,0],[6,19,"נתערבו קדשים בקדשים וכו'. נלמד ממה ששנינו במשנה בפרק התערובות שם:",1,0],[6,19,"נתערבו בפסולי המוקדשין וכו'. נלמד מדאיפליגו בפ' התערובות במשנה ר' אליעזר ורבנן באיברים שנתערבו באיברי בעלי מומין ופסק כרבנן:",2,0],[6,20,"איברי חטאת שנתערבו באיברי עולה וכו' עד ה\"ז ישרף בעזרה וכו'. משנה בפרק התערובות (דף ע\"א) פלוגתא דר\"א ופסק כרבנן:",1,0],[6,21,"ומ\"ש אפילו אבר באלף איברים:",1,0],[6,22,"חתיכות קדשי קדשים וכו'. משנה שם (דף ע\"ה ע\"ב):",1,0],[6,23,"חתיכה של חטאת טמאה וכו' עד סוף הפרק. ברייתא בפרק הערל (יבמות דף פ\"א ע\"ב) ופירש רש\"י דטעמא דקתני לא יעלו משום דאפשר למכרן לכהן בהפסד מועט:",1,0],[7,1,"כל הפסולים לעבודה שמלקו מליקתן פסולה וכו'. משנה בפ' חטאת העוף (זבחים דף ס\"ח) כל הפסולים שמלקו מליקתן פסולה ואינם מטמאות בבית הבליעה.",1,0],[7,1,"ומ\"ש וכן אם מלק בלילה וכו' עד אלא דבר שהוא כשר למזבח. שם במשנה:",2,0],[7,4,"ומ״ש אבל הנרבע והמוקצה וכו' עד והרי אין פיסולן בקדש. נלמד מהמשנה הנזכרת והוא מפורש בברייתא פרק המזבח מקדש (זבחים דף פ״ה:):",1,0],[7,5,"כבר ביארנו במעשה הקרבנות. בפ\"ז:",1,0],[7,5,"חטאת העוף שעשאה למעלה פסולה וכו' עד ובלבד שלא עלתה לבעלים לשם חובה. בפ' חטאת העוף (זבחים דף ס״ו) ודקדק רבינו לכתוב בחטאת העוף ושעשה הזייתה משום דאילו מליקתה בכ״מ כשירה כמו שמפורש שם ע״ב בגמ':",2,0],[7,9,"כל אלו העופות שנפסלו מפני מקום עשייתן וכו' עד שכל אלו פיסולן בקדש. נלמד מהמשנה שהזכרתי בר\"פ זה:",1,0],[7,10,"חטאת העוף הבאה וכו'. מתבאר ממה שיבא בסמוך:",1,0],[7,10,"וכיצד תבא על הספק וכו'. פשוט הוא.",2,0],[7,10,"ומ\"ש ואין לנו חטאת בהמה על ספק וכו'. ג\"ז פשוט. ומ\"כ שדקדק רבינו לכתוב כגון שהיתה ספק זבה או ספק יולדת מפני שאינן יכולות לאכול בקדשים עד שיביאו כפרתן ולכך התירו להן להביא ספק חולין לעזרה אבל ספק מטמא מקדש לא התירו לו להביא ספק חולין לעזרה:",3,0],[7,11,"חטאת העוף הבאה על הספק וכו'. משנה בכריתות פ' דם שחיטה (כריתות דף כ״ב:) האשה שהביאה חטאת העוף ספק אם עד שלא נמלק נודע לה שילדה ודאי תעשנה ודאי שממין שהיא מביאה על לא הודע מביאה על הודע. ובפרק המביא אשם תלוי (דף כ״ו:) אתמר עלה אמר רב מזה דמה וממצה דמה וכיפרה ומותרת באכילה ור״י אמר אסורה באכילה גזירה שמא יאמרו חטאת העוף הבאה על הספק נאכלת ופירש״י האשה שהביאה וכו' ועלה קאי רב ואמר אם משנמלקה נודע לה כן שילדה ודאי מזה וכו' תניא כוותיה דר״י חטאת העוף הבאה על הספק אם עד שלא נמלקה נודע לה שלא ילדה תצא לחולין או תמכר לחברתה אם עד שלא נמלקה נודע לה שילדה ודאי תעשה ודאי שממין שמביאה על לא הודע מביאה על הודע אם משנמלקה נודע לה שילדה אסורה ופסק כר״י ואע״ג דתני לוי כוותיה דרב ברייתא דתני סתם גמרא עדיפא מינה וגם מתניתין בפרק דם שחיטה דקתני אם עד שלא נמלקה וכו' כר״י דייקא דלרב ה״ל למיתני אם עד שלא הזה:",1,0],[7,12,"ומה שכתב נודע לה שאינה חייבת בה מאחר שנמלקה ה\"ז תקבר. משנה בפרק המביא אשם תלוי:",1,0],[8,1,"חטאת העוף שנתערב בעולת העוף וכו'. פ\"ק דקינים ופירש\"י אחד בריבוא ימותו כולם דבכל אחת איכא לספוקי שמא עולה היא ופסולה למטה או שמא חטאת ופסולה למעלה:",1,0],[8,1,"בד\"א כשהיו מפורשות בשעת לקיחת הבעלים וכו':",2,0],[8,4,"וכיצד דיניהם אם נתערבה חטאת בחובה זו הסתומה וכו'. וכן אם נתערבו עולה בחובה זו הסתומה וכו'. שם ופירש\"י חובה קרי קן שלם של יולדת או של זבה והוא אחת חטאת ואחת עולה וכו' ואם פרידה המופרשת לחטאת מעורבת עם ב' קינים של חובה שהם סתומים ועתה חמש פרידים מעורבין יחד אין יכול לעשות אלא שתים חטאת שזהו מנין הכשר בשני קינין של חובה דאי עבד ג' חטאות שמא משני קינין עבד להו ולא מהמעורב בהם ומב' קינים אינו יכול לעשות רק ב' חטאות ולא מצי עביד אפי' אחת עולה שמא יקח החטאת המעורבת וכן עולה שנתערבה בחובה בקן סתומה אין כשר אלא שנתערבה זו בזו אחת לזו ואחת לזו שתים לזו ושתים לזו שלש לזו ושלש לזו מחצה כשר ומחצה פסול אחת לזו ושתים לזו ושלש לזו ועשר לזו ומאה לזו הממועט כשר. ופירש\"י אבל חובה שנתערבה זו בזו קן סתומה של לידה שהוא אחד חטאת ואחד עולה ונתערבו השני פרידין בקן אחת סתומה של לידה או של זיבה מאשה אחרת מחצה כשר ומחצה פסול יכול להקריב שני פרידין אחד עולה ואחד חטאת ולא יותר דאי עבד שני עולות שמא יעשה אותן מקן אחד של לידה או של זיבה וכן אם נתערבו הרבה קינים יחד יקריב חציו אחד חטאת ואחד עולה וחציו האחר פסולים והיינו כי נתערבו בשוה כדאמרינן אחת לזו ואחת לזו או שתים לזו ושתים לזו או שלש לזו ושלש לזו שיכול ליקח השלשה קינים אי זה שלש פרידים שירצה אי זה לחטאת ואי זה לעולה אבל אחד לזו ושנים לזו ושלש לזו ועשר לזו ומאה לזו הממועט כשר. אם נתערבו קן חטאת סתומה של זיבה בשני קינים של לידה או בשלשה אינו יכול להקריב אלא קן אחד פרידה אחת לחטאת ופרידה אחת לעולה אבל שתי עולות לא מצי עביד פן יקח הקן שהוא מבורר תחלה ללידה אחת שאינו יכול להקריב ממנו רק אחת חטאת ואחת עולה וכן אם נתערבו כולם יחד האחת והשתים והשלש והעשר לא יוכל להקריבו רק קן אחד שני פרידים או עשר קינים במאה יקריב עשרים פרידים כמו שיכול לעשות מעשר קינים וזהו המועט כשר. בין משם אחד לידה ולידה משתי נשים בין שני שמות לידה וזיבה אפי' מאשה אחת כדמפרש (במתני') כיצד משם אחד. וז\"ל רבינו בפירוש המשנה אומר כי מה שהקדים לומר אין כשר אלא מנין עולות שבחובה אינו אלא אם נתערבו קינים נדבה שהם עולות כולם בקיני חובה שחציין עולות וחציין חטאות אבל חובה שנתערבה בחובה וכו' שאם היו שוות אלו כנגד אלו יהא המחצית כשר והמחצית פסול בהכרח באי זה צד שעשאן וכו' ויהיה שוה בזה כהן נמלך ר\"ל ששואל לאשה אי זה יעשה חטאת ואי זה יעשה עולה וכהן שאינו נמלך אלא שהדבר מסור לו אבל אם היה מנין אחת משתיהן יותר ממנין האחרת [הרי יש בזה חילוק והוא] שאם עשה הכל למעלה או למטה המחצית כשר והמחצית פסול בהכרח וכו' ואם עשה החצי למעלה והחצי למטה וכו' המועט אז כשר ע\"מ שיהא נמלך ולא יהיה מסור לו לעשות עולה מה שירצה וחטאת מה שירצה הרי בעלת המנין המועט אומרת לו שזה המחצית שנעשה למעלה בו נבלעה עולה שלי לפי שהוא המועט והמחצית שעשית למטה בו נבלעה חטאת שלי לפי שהוא ג\"כ המועט ואני לא מסרתי הדבר אליך ולא הרשות עכ\"ל:",1,0],[8,6,"עשה חציין למטה וחציין למעלה אם אחר ששאל עשה כן המועט כשר וכו' זה הכלל כל שעשה הכהן מדעתו וכו'. שם בפ\"ג בד\"א בכהן נמלך אבל בכהן שאינו נמלך אחת לזו ואחת לזו שתים לזו ושתים לזו שלש לזו ושלש לזו עשה כולן למעלה מחצה כשר ומחצה פסול כולם למטה מחצה כשר ומחצה פסול חציין למעלה וחציין למטן את שלמעלה מחצה כשר ומחצה פסול ואת שלמטה מחצה כשר ומחצה פסול אחת לזו ושתים לזו ושלש לזו ועשר לזו ומאה לזו עשה כלן למעלה מחצה כשר ומחצה פסול כולם למטה מחצה כשר ומחצה פסול חציין למעלה וחציין למטה המרובה כשר זה הכלל כ\"מ שאתה יכול לחלוק את הקינים ולא יהו משל אשה אחת בין למעלה בין למטה מחצה כשר מחצה פסול וכ\"מ שאי אתה יכול לחלוק את הקינין עד שיהיו משל אשה אחת בין למעלה בין למטה המרובה כשר. ופירש המפרש בד\"א בכהן נמלך אפירקא קמא קאי והכי קאמר בד\"א דחטאת שנתערבה בעולה ועולה בחטאת אפי' אחת בריבוא ימותו כלם וכן אחת לזו ושתים לזו ושלש לזו דמועט כשר כל אלו הדינין בכהן נמלך כלומר לכתחלה נמלך הכהן איך משפטן אבל בכהן שאינו נמלך ועשה הכל מדעתו בדיעבד ועשה קן שלם למעלה לאשה אחת וכן קן שלם לאשה אחת הילכך כולם למעלה מחצה כשר עולות ומחצה פסול חטאות וכן למטה בענין זה וכן משמע בריש פרק התערובות דהאי בד\"א אפרקין קמא קאי. וז\"ל רבינו בפירוש המשנה זה שהוציא מן הכלל הוא שב על הלכה רביעית מהפרק הראשון שאמר המועט כשר אמר שאין זה אלא בכהן נמלך אם עשה חציין למעלה וחציין למטה אבל כהן שאינו נמלך אלא עושה לרצונו למעלה ולמטה כשר המרובה והוא מגיד מאי זה טעם יהיה כן ואמר שכל זמן שאפשר לחלק הכלל המעורב ואין מעופות האשה האחת בשני החצאין יחד הרי כשעשה חציין למטה וחציין למעלה מחצה כשר ומחצה פסול לפי שאנו אומרים אפשר שעופות של אחת היו כולן למעלה או למטה שחציו לעולם כשר וזה אפשר לעולם כל זמן שיהיה מנין כנגד מנין (הנה הכל אפשר) לחלק בשני חצאין ומקריבין החצי למעלה והחצי למטה ושלא יהיו מקצת העופות שהקריבו למעלה ומקצת מה שהקריבו למטה משל אשה אחת ואז המחצית שנעשה באחד משני הצדדין וכל זמן שא\"א לחלק הכלל המעורב ולעשות חציו למעלה וחציו למטה אלא שעופות האחת כבר נעשה מהם למעלה ולמטה הרי הרוב כשר לפי שבעלת הרוב היא שנעשה מעופות שלה למעלה [ולמטה] בהכרח וא\"א זה אלא כשיהיה מנין זו יותר ממנין זו עכ\"ל. והראב\"ד כתב על דברי רבינו עשה חציין למטה א\"א זה כתב בשביל שראה במשנה רפ\"ג וכו' עד וממעט בהשלמת חובתה. ונ\"ל להגיה ולכתוב במקום חבירותיה חבירתה כלומר אותה שנתערב קינים עמה. וטעם רבינו לחלק בין נמלך לשאינו נמלך נתכוון רבינו לבאר בפירוש המשנה שכתבתי בסמוך ואין דבריו מובנים לי:",1,0],[8,8,"שנים שלקחו קיניהם בעירוב וכו'. שם בשם ר' יוסי.",1,0],[8,8,"ומ״ש שאין הקינין מתפרשים וכו' כמו שביארנו. הוא בפ״ה ושם נתבאר ואע״ג דבפ' בכל מערבין (עירובין דף ל״ו) בעי לאורויי מהכא דרבי יוסי סבר יש ברירה ומוקי לה בשהתנו ורבינו פוסק דבדאורייתא אין ברירה וכיון שכן קשה על רבינו שהיה לו לומר דבשהתנו מיירי. וי״ל דאמרינן עלה א״ה מאי למימרא קמ״ל כדרב חסדא דאמר אין הקינין מתפרשות אלא או בלקיחת בעלים או בעשיית כהן ומפרש דהשתא דקמ״ל כדרב חסדא אין צריך להתנות אלא אע״ג דלא התנו כהתנו דמי:",2,0],[8,9,"היו לפני הכהן חטאות ועולות וכו' עד סוף הפרק. בפ' ג' דקינים חטאת לזו ועולה לזו עשה כולן למעלה מחצה כשר ומחצה פסול וכו' ואם תאמר והא תנן חטאת שנתערבה בעולה אפי' אחד בריבוא ימותו כולם. וי\"ל שאין כאן תערובת כלל אלא כל קן היה בפני עצמו וכל אחד הקריב בפני עצמו אלא שטעה הכהן בהקרבתן וכשהקריב חציין וחציין יודע היה ואח\"כ שכח ומסופק אם טעה אם לא. זה דעת רבינו בפירוש המשנה:",1,0],[8,10,"היו לפניו ג' צבורי עופות וכו'. ג\"ז שם ופירש רבינו במשנה זו על דרך שכתבתי שפירש במשנה שקודם זו שלא היה כאן תערובת כלל וע\"ש:",1,0],[9,1,"קן סתומה שפרח ממנה גוזל לאויר וכו'. בפרק ב' דקינים וכתב רבינו שם דע כי (כל) מה שנאמר בכל הלכות אלו חזר אינו ר\"ל שחזר אותו העוף בעצמו לפי שכל זמן שיהא כן אין שם הפסד כל עיקר אבל ר\"ל כשאמר וחזר שמאחר שפרח לכת ראשונה והרי אפשר שהוא הראשון בעצמו שחזר לחבורתו או הוא עוף אחר:",1,0],[9,5,"ומ\"ש והשלישית יש לה שני עופות והרביעית יש לה ארבעה והחמישי' יש לה ששה והששית יש לה שמנה והשביעית יש לה י\"ב. במשנה [שם] שנינו השלישית יש לה אחת הרביעית שתים החמישית יש לה שלש הששית יש לה ארבע השביעית שש. והענין דבמתני' נקט מנין הקינים וכל קן זוג אחד ורבינו נקט מנין הפרידין והיינו דנקט בלישניה עופות וע\"ד זה תקיש ותדין בשאר. וע\"ש בפירוש המשנה לרבינו ותמצא הכל מבואר:",1,0],[9,6,"קן סתומה וקן מפורשת וכו'. גם זה שם:",1,0],[9,7,"חטאת מכאן ועולה וסתומה באמצע וכו' עד סוף הפרק. שם:",1,0],[10,1,"האשה שאמרה הרי עלי קן כשאלד זכר וכו' עד סוף הפרק. בפ' ד' דקינים ואיתא בפרק חטאת העוף (זבחים ס\"ז:):",1,0],[10,1,"כתב הראב\"ד בד\"א כשהביאה וכו' עד ושתים למטה א\"א ולא ידע הכהן אי זה מין עשה למטה ואי זה מין עשה למעלה עכ\"ל. ואני אומר שזה פשוט הוא ובכלל לא ידע אי זה מהן עושה למעלה הוא:",2,0],[10,3,"פירשה נדרה ואמרה לכהן אלו לנדרי וכו' ויעשו השלשה למעלה. תיבת השלשה צריך למחוק ולכתוב במקומה",1,0],[10,3,"השנים וכן מ\"ש",2,0],[10,3,"אצל קבעה נדרה ואמרה אם אלד זכר וכו' שכבר עשה שנים למטה שהם חטאת שש תיבות אלו נראה שהם שיבוש וצריך למוחקם:",3,0],[10,3,"כתב הראב\"ד בד\"א כשהביאה הארבעה בתחלה וכו' עד וכן אם. א\"א דבריו מבולבלים וכו'. והר\"י קורקוס ז\"ל כתב וז\"ל כתב רבינו במשנה ענין קבעה שפירשה (בשעת נדרה) מין פלוני ותביא אותו לכהן עם חובתה ועשה שתים למטה ושתים למעלה ולא ידע אם הנדר נעשה למעלה או למטה וגם היא נסתפק לה איזה משני המינים קבעה בו נדרה אם התורים או בני יונה וזה הוא ההפרש שיש בין קבעה לפירשה שפירשה הוא שתאמר בשעת הבאת נדרה וחובתה אלו לנדרי ואלו לחובתי וקבעה נדרה הוא שתאמר בשעת הנדר הרי עלי קן ממין פלוני והוא מדבר כאן במי שקבעה נדרה והביאה אותו ואח\"כ שכחה מאיזה מין קבעה אבל ודאי אצלה שהוא קבוע עכ\"ל בספר מוגה. ונראה שבבא זו מדברת שאינה יודעת אי זה מין הם הד' פרידים שנתנה לכהן אבל מ\"מ יודעת היא שהם מין אחד שאם יודעת אי זה מין הוא שנתנה א\"א להסתפק באי זה מין קבעתו שהרי נדרה נתנה. וזה נראה מוכרח וביארו רבינו במשנה וז\"ל וזה אם היו הארבעה מין אחד והיה ודאי אצלה שנתנה לכהן מין ולא ידעה מאי זה מין הוא גם כתב שאין אנו יודעים מאי זה מין הוא הארבעה שנולד בהם הספק ע\"כ. והוא מוכרח וע\"פ הקדמה זו הדבר ברור שלא נפטרה מספק נדרה כלל וצריכה להביא ד' לנדרה שתי תורים ושני בני יונה. אבל קשה טובא איך יספיק אחד לתשלום חובתה והרי אינה יודעת מאי זה מין היה החטאת ואם תביא תור שמא היה בן יונה או להפך וכבר נתבאר שצריך חטאת ועולה ממין אחד ובמשנה כתב ותביא גוזל אחד תור או בן יונה להשלים חובתה והצריכו תור או בן יונה לפי שאין אנו יודעים מאיזה מין היו הארבעה וכו'. ודברים אלו צריכים ביאור וכפי הכתוב בספרים שהגוזל הוא לעולה א\"א ליישבו שהרי גבי פירשה חייבת להביא כל החובה מספק לפי שאינה יודעת מאי זה מין היו העולות שתביא חטאתה מאותו המין ומה לי אם היו שני מינים או מין אחד ואינה יודעת אי זה מין היה הכל ספק אחד הוא. ואפשר לפרש כוונת רבינו ביודעת איזה מין נתנה לכהן אלא ששכחה באיזה מין קבעה נדרה וד\"מ נתנה תורים ונסתפקה שמא בני יונה פירשה ושלא כדין נתנה לכהן תורים ואם היו יודעים שמה שנתנה לנדרה נעשו למעלה לא היה נשאר עליה מספק נדרה אלא שני בני יונה ובהם נפטרה מנדרה ועתה שמא מה שנתנה לנדרה עשו למטה ונמצא כל ספיקה עליה לכך מביאה שתי תורים ושני בני יונה וכולם למעלה בספק נדרה ומחובתה תביא גוזל אחד כי מעולה אחת נפטרה בתורים ראשונים ממ\"נ אם שלמעלה היו נדרה הרי לא היתה צריכה להביא אלא שני בני יונה לתשלום נדרה ומהשני תורים שמביאה עתה אחד יעלה לחובתה והאחר פסול וצריכה חזרה לחטאת לתשלום חובתה ואינה צריכה יותר ואם שנים ראשונים היו נדרה הרי שלמעלה היו חובתה והרי נפטרה מהעולה בראשונים ונמצא לפי זה שממ\"נ צריכה להביא גוזל אחד לחטאת ממין הראשונים.",4,0],[10,3,"ומ\"ש בספרי רבינו גוזל אחד למעלה. מ\"כ שהוא טעות ובמשנה כתב בפירוש תביא תור ובן יונה ותעשה חטאת ממ\"נ והוא הנשאר מחובתה. והשתא דאתינא להכי שהכרחתי שהאחד הוא חטאת י\"ל שתקריב מאיזה מין שתרצה ויוצאה ממ\"נ שאם תביא תור כשר ממ\"נ אם הראשונים היו תורים א\"כ הנדר היו תורים ואם קרבו למעלה הרי נפטרה והשתי תורים אחרונים יעלה אחד מהם לחובתה והרי תור לחטאת ויצאה ידי חובתה ואם קרבו למטה הרי יצאה מידי עולת חובה באחד מתורים ראשונים של מעלה ותורים שניים לנדרה והרי תור לחטאת ואם היו בני יונה א\"כ הנדר היה בני יונה ובבני יונה אחרונים ממ\"נ יצאה ונמצא תורים שניים עולה אחד מהם לחובתה וכן כשמביאה בני יונה יוצאה ממ\"נ על הדרך שנתבאר כי ידוע כי מין שהביאה נדרה. ובהשגות א\"א דבריו מבולבלים וכו'. ובודאי כי הלשון סתום ומוטעה כאשר הכרחתי ולא פירשה איזה מין נתנה לכהן וצריך לתקן כאשר כתבתי וילמוד סתום אשר כאן ממפורש במשנה. וכתב עוד אבל וכו'. טעם בבא זה מבואר שכיון שהראשונים שני מינים ואינו יודע מה עשה למעלה ומה עשה למטה א\"א שיועיל דבר לנדרה כי שמא נדרה קרב למטה ולא לחובתה כי אינו יודע איזה מין למעלה ואיזה למטה ואנן בעינן עולה וחטאת מין אחד ולכך מביאה הכל. וצריך לדעת כי גם בבא של קבעה מיירי לשיטת רבינו כשפירשה אלו לנדרי דאל\"כ איך שייך לומר ולא ידע איזו עשה וכו' כיון שהכל מין אחד מה שייך לומר כן גם אין שייך לומר שמא הנדר עשה למטה שכתב במשנה אלא דודאי היא ייחדה אשר לנדרה אלא שלא אמרה כן לכהן כמו בפירשה והיא שכחה ומ\"מ בשנים שמביא מקריב סתם ולכך שייך ממ\"נ שנתבאר. ואפשר שלא ידע שכתב רבינו מפני בבת שני מינים נקט לה ולעולם לא ייחדה. אלא שלשון המשנה אינו מוכיח כן גם הענין נראה שהוא כאשר כתבתי:",5,0],[10,3,"וכתב",6,0],[10,3,"עוד וכן אם נתנתם וכו'. טעם בבא זו מבואר כי לא עולה לה דבר מחמת הספק לכך תביא כל חיובה וחלוקה זו לא הוזכרה במשנה אמנם אמרו שם נתנתם לכהן ואינה יודעת מה נתנה ועשה הכהן ואין ידוע מה עשה צריכה להביא ד' פרידים לנדרה ושתים לחובתה וחטאת א' בן עזאי אומר שתי חטאות והוקשה לרבינו חטאת זה למה כיון שהביאה כל חובתה ולכך פירשה דקבעה גם חובתה ולא ידעה מה קבעה ולפ\"ז הוצרך להוסיף כבש אע\"פ שלא הוזכר שכיון שקבעה ולא ידעה מה קבעה מביאה קן מאיזה מין שתרצה וכבש ופרידה וא\"ת וניחוש דילמא חובתה בתורים או בבני יונה ולמה תפטר בקן מאיזו מין שתרצה ונראה דלהא לא חיישינן כי אין דרך לפרש לחיובה תורים או בני יונה רק קרבן עני או קרבן עשיר עכ\"ל.",7,0],[10,3,"ומ\"ש ששני פרידין שבהן צריך שיהיו ממין אחד נלמד בספרא מדכתיב שתי תורים וכו' אחת לעולה ואחת לחטאת ממין שיביא עולה יביא חטאת:",8,0],[10,5,"ומ\"ש וכל החטאות האלו אינן נאכלות מפני שהן ספק. פשוט הוא בסוף תמורה (דף ל\"ד) חטאת העוף הבאה על הספק תשרף:",1,0],[11,1,"כל המנחות שקמצן אחד מהפסולים לעבודה הרי הן פסולים. משנה בפ\"ק דמנחות (דף ו').",1,0],[11,1,"ומ\"ש וכן אם לקט הלבונה פסל אע\"פ שלא קמץ. ברפ\"ב (דף י\"ג:) מימרא דר' ינאי ופירש\"י ליקוט לבונה דלאחר הקטרת הקומץ היה מלקט [הלבונה] מעל הסולת ומקטירו:",2,0],[11,2,"קמץ הכשר ונתן לפסול וכו'. בפ״ג דזבחים (דף ל״ב) תנן קיבל הכשר ונתן לפסול יחזיר לכשר קיבל בימינו ונתן לשמאלו יחזיר לימינו קיבל בכלי קדש ונתן לכלי חול יחזיר לכלי קודש ופריך בגמרא (דף ל״ד:) ולהוי דחוי ואסיקנא כל שבידו לא הוי דחוי ומדין זבחים יש ללמוד למנחות. וא״ת אמאי לא תנא רבינו בהו תקנתא כדתנן במתני' שכתבתי בסמוך לענין קבלת דם. וי״ל משום דאיתא בתוספתא דמנחות פ״ה קמץ הכשר ונתן לפסול יחזיר לכשר וכו' קמץ בימינו ונתן לשמאלו יחזיר לימינו וכו' בכלי קדש ונתן לכלי חול יחזיר לכלי קדש וכו' דברי ר' אלעזר ור״ש וחכ״א קמץ הכשר ונתן לפסול פסלתו מתנתו קמץ בכלי קדש ונתן לכלי חול פסלתו מתנתו קמץ בימינו ונתן לשמאלו פסלתו מתנתו וידוע דהלכה כחכמים. ואם תאמר ולחכמים מאי שנא קמיצה מדם וי״ל דבפרק הקומץ רבה (מנחות דף כ״ו:) מייתי מאי דתני בהאי תוספתא וחכ״א כיון שנתנו לשמאל פסלתו מתנתו וקאמר עלה בגמ' מ״ט משום דבעי לקדושי בכלי וכיון שנתן לשמאל נעשה כדם שנשפך מצואר בהמה על הרצפה ואספו שפסול. ופירש רש״י פסלתו מתנתו (מה שנתן בשמאלו) ושוב אין לו תקנה בחזרה מאי טעמא משום דבעי לקדושי בכלי וכו' ואספו שפוסל עוד להקדישו בכלי דאי לא הוי עוד האי קומץ קידוש כלי לא הוה מיפסל דהוה כדם שנשפך מן הכלי על הרצפה שכשר אבל מאחר דבעי כלי לית ליה תקנתא בחזרה כדפרישית דהוה ליה כנשפך על הרצפה מן הצואר שפסול דנפקא לן מולקח מדם הפר דם מהפר יקבלנו וקידוש קומץ במקום קבלת דם ושמאל בלא כלי הרי היא כרצפה עכ״ל:",1,0],[11,3,"קמץ ועלה בידו צרור או גרגיר מלח או קורט לבונה פסול. משנה בפירקא קמא דמנחות (דף י':):",1,0],[11,4,"קמץ עד שהוא בחוץ ונכנס לפנים וכו'. תוספתא פ\"ה דמנחות. ומה שצריך קמיצה בפנים איתיה בפ\"ק דמנחות. ופירוש בפנים כל העזרה:",1,0],[11,5,"נתפזר הקומץ על גבי הרצפה יחזור ויאספנו. תוספתא פ\"ה דמנחות. מ\"כ מ\"ש נתפזר הקומץ על הרצפה יחזור ויאספנו מיירי שנתפזר אחר שנתנו לכלי שרת אבל אם קמץ ונפל מידו לארץ פסול כמו שהוא דין הדם:",1,0],[11,6,"היתה המנחה שלא בכלי שרת וכו'. בפ' הקומץ רבה (מנחות דף כ״ו) תניא חכמים אומרים קומץ טעון כלי שרת כיצד קמצו מכלי שרת ומקדשו בכלי שרת ומעלו ומקטירו בכלי שרת:",1,0],[11,6,"ומה שכתב או שבללה בשמנה חוץ לעזרה פסולה וכו'. בפירקא קמא דמנחות (דף ע') אתמר בללה חוץ לחומת העזרה רבי יוחנן אמר פסולה ריש לקיש אמר כשירה וידוע דהלכה כרבי יוחנן ועוד דתניא כוותיה ומפרש בגמרא טעמא דרבי יוחנן אף על גב דבלילה כשרה בזר כיון דעשייתו בכלי היא אף על גב דכהונה לא בעיא קדושת פנים מיהת בעיא:",2,0],[11,7,"כל המנחות שיצק עליהם השמן פסול לעבודה וכו'. בפרק הקומץ רבה (מנחות דף י״ח) תנן לא יצק לא בלל ולא פתת ולא מלק ולא הניף לא הגיש וכו' כשירה ובגמ' מאי לא יצק אילימא לא יצק כלל עיכובא כתיב בה אלא לא יצק כהן אלא זר אי הכי לא בלל נמי לא בלל כהן אלא זר הא לא בלל כלל פסולה והתנן ששים נבללין ששים ואחד אין נבללין והוינן בה כי אין נבללין מאי הוי והא תנן לא בלל כשירה ואמר ר' זירא כל הראוי לבילה אין בילה מעכבת בו וכל שאינו ראוי לבילה בילה מעכבת בו מידי איריא הא כדאיתא והא כדאיתא לא יצק לא יצק כהן אלא זר לא בלל לא בלל כלל ובתר הכי אמרינן מתני' (דמכשיר יציקה בזר) דלא כר״ש (דאמר יציקה ובלילה ופתיתה ומליחה בעו כהן) מ״ט דרבנן אמר קרא ויצק עליה שמן ונתן עליה לבונה והביאה אל בני אהרן הכהן מקמיצה ואילך מצות כהונה לימד על יציקה ובלילה שכשירה בזר.",1,0],[11,7,"ומ\"ש רבינו הגישן או הניפן חוזר הכהן ומגיש או מניף. ומ\"ש ואם לא הגיש ולא הניף הכהן כשירות וכו'. נתבאר בסמוך:",2,0],[11,8,"מנחה שנפל לתוכה שמן מנחה אחרת וכו'. בפ' ראשון דמנחות (דף י\"א) תנן ריבה שמנה חיסר שמנה וכו' פסולה ובגמ' היכי דמי ריבה שמנה א\"ר אלעזר כגון שהפריש לה שני לוגין ולוקמה כגון דעריב בה שמן דחולין ושמן דחבירתה וכו' ר\"א לא מיבעיא קאמר לא מיבעיא דחולין ודחבירתה דפסיל אבל הפריש לה שני לוגין הואיל והאי חזי ליה והאי חזי ליה אימא לא ליפסיל קמ\"ל:",1,0],[11,8,"חיסר לבונתה כשירה וכו'. שם במשנה חיסר לבונתה פסולה ובגמ' ת\"ר חסרה ועמדה על קורט אחד פסולה על שני קורטים כשירה דברי ר' יהודה ר\"ש אומר על קורט אחד כשירה פחות מכאן פסולה וכו' א\"ר יצחק בר יוסף א\"ר יוחנן ג' מחלוקת בדבר דר\"מ סבר קומץ בתחלה וקומץ בסוף. ופירש\"י ר\"מ סתם מתני' דקתני חיסר לבונתה פסולה ופסק רבינו כר' יהודה וצריך ליתן טעם למה לא פסק כסתם מתני' ואפשר שטעמו משום דר\"י ור\"ש פליגי עליה והו\"ל ר\"מ יחידאה לגבייהו ולא חיישינן לסתמא כיון דרבים פליגי עליה ובפלוגתא דר\"י ור\"ש ידוע דהלכה כר\"י וא\"ת כיון דסתם רבי כר\"מ הוה ליה למיפסק כוותיה י\"ל דכיון דלא אשכחן בברייתא דפליגי אלא ר\"י ור\"ש טפי הוה עדיף לפרושי מתני' אליבא דר\"י דהלכתא כוותיה לגבי ר\"ש מלאוקומי לה בפלוגתא תליתאה ור\"י דאמר ג' מחלוקות בדבר בעא לדיוקי לישנא דחסר לבונתה דמשמע אפי' חיסר כל שהוא. ואינו מוכרח. ועוד דמדר\"י נשמע דס\"ל דהלכה כר\"י מדאמר ג' מחלוקות בדבר ר\"מ ור\"י ור\"ש בידוע דהלכה כר\"י לגבייהו דאל\"כ לא הל\"ל הכי אלא אמתני' דחיסר לבונתה הול\"ל א\"ר יוחנן אפילו חיסר כל שהוא:",2,0],[11,9,"ריבה שמנה ולבונתה וכו'. שם בגמרא אמתני' דחיסר לבונתה פסולה הא יתיר [כשירה והתניא יתיר] פסולה אמר רמי בר חמא כגון שהפריש לה שני קמצים ומשמע לרבינו דכי אמר ר' אלעזר גבי ריבה שמנה כגון שהפריש לה שני לוגין שני לוגין דוקא קאמר ויגיד עליו רעו יתיר לבונתה דלא מיפסיל בפחות משני קמצים ולא כדפירש\"י שכתב אהא דאמרינן ולוקמה כגון דעריב שמן דחולין וכו' ולוקמה כגון דעריב ביה פורתא שמן דחול וכו':",1,0],[11,10,"מנחת חוטא שנתן עליה שמן וכו'. בפ' כל המנחות באות מצה (מנחות דף נ״ט:) וחייב על השמן בפני עצמו ועל הלבונה בפני עצמה נתן עליה שמן פסלה לבונה ילקטנה.",1,0],[11,10,"ומ\"ש או על הקומץ שלה. ומ\"ש היתה שחוקה ה\"ז פסולה מספק וכו'. שם בעא רבה בר רב הונא מר\"י נתן עליה לבונה שחוקה מהו משום דאפשר ללוקטה והא לא אפשר ללקטה או דילמא משום דלא מיבלעא והא נמי לא מיבלעא ובתר הכי אמרינן מאי הוי עלה אמר ר\"נ בר יצחק תניא מנחת חוטא ומנחת קנאות שנתן עליה לבונה מלקט את הלבונה וכשירה וכו' ופירש\"י אלמא מדקאמר כל זמן שלבונה בתוכה פסולה היא ש\"מ בלקיטה תליא מילתא. ורבינו שכתב מספק צ\"ל דלא גריס מאי הוי עלה וברייתא דמייתי ר\"נ בר יצחק מילתא באפי נפשה היא דמייתי לה לאקשויי עלה ואמאי פסלה במחשבה דחוי הוא ואינה ענין לבעיא דילן:",2,0],[11,11,"נתן שמן על שיריה וכו'. שם במשנה:",1,0],[11,12,"נתן משהו שמן ע\"ג כזית מן המנחה וכו' עד פסל עד שילקט. שם א\"ר יצחק בר יוסף א\"ר יוחנן נתן משהו שמן ע\"ג כזית מנחה פסל מ\"ט לא ישים שימה כל דהו עליה עד דאיכא שיעורא וא\"ר יצחק בר יוסף א\"ר יוחנן נתן כזית לבונה ע\"ג משהו מנחה פסל מ\"ט לא יתן כתיב עד דאיכא נתינה עליה הוי ריבוי אחר ריבוי ואין ריבוי אחר ריבוי אלא למעט ואיכא דאמרי א\"ר יצחק בר יוסף בעי ר' יוחנן נתן משהו שמן ע\"ג כזית מנחה מהו מי בעינן שימה כנתינה או לא תיקו. ופירש\"י בלבונה כתיב נתינה ונתינה בכזית כדכתיב ונתן לכהן את הקדש ובההיא נתינה כתיב אכילה וכל אכילה בכזית. עליה משמע דבמנחה בעינן כזית הוי ריבוי אחר ריבוי דגבי שמן כתיב עליה דהיינו כזית וגבי לבונה עליה הוי ריבוי אחר ריבוי ואינו אלא למעט דגבי לבונה לא בעינן כזית מנחה דעל משהו נמי חייב:",1,0],[11,14,"גבלה במים וקמץ כשירה וכו':",1,0],[11,15,"מנחה שקמצה פעמים כשירה וכו'. בפ' הקומץ רבה (מנחות דף כ״ו) תנן הקטיר קמצה פעמים כשירה ובגמרא אמר ריב״ל פעמים ולא פעמי פעמים ור״י אמר פעמים ואפילו פעמי פעמים מאי בינייהו א״ר זירא יש קומץ פחות משני זיתים ויש הקטרה פחותה מכזית ריב״ל סבר אין קומץ פחות משני זיתים ואין הקטרה פחותה מכזית ור״י סבר יש קומץ פחות משני זיתים ויש הקטרה פחותה מכזית ופסק כריב״ל לגבי ר״י כמו שכתבו התוס' בפ' בני העיר (מגילה דף כ״ז בד״ה כוותיה דרב פפי) ומשמע דלרבינו ה״פ ריב״ל סבר אין קומץ פחות משני זיתים ומשום הכי קתני מתני' הקטיר קומצה פעמים כלומר שהקטיר בכל פעם חצי קומץ דהיינו כזית כשירה אבל אם הקטיר קומצה בפעמי פעמים דהיינו שיקטיר בכל פעם פחות מכזית פסולה דאין הקטרה פחותה מכזית ולפי זה אם היה הקומץ גדול שיש בו כמה זיתים אפי' הקטירו בכמה פעמים כשירה והוא שלא יהא בכל קומץ פחות מכזית:",1,0],[11,16,"הקריב הקומץ בלא מלח פסולה וכו'. הכי דרשינן בפרק הקומץ רבה (מנחות דף כ'):",1,0],[11,16,"מנחה שחסרה וכו'. בפ\"ק דמנחות (דף ט') פלוגתא דרבי יוחנן וריש לקיש וידוע דהלכתא כר\"י ועוד דהא איתותב ר\"ל:",2,0],[11,17,"התנדב קומץ לבונה בפ\"ע וכו'. בפ\"ק דמנחות (דף י\"א:) מימרא דרב יצחק בר' יוסף אמר ר\"י:",1,0],[11,18,"הפריש שני קמצים למנחה אחת וכו' וכן אם הפריש ארבעה קמצים וכו'. שם מימרא דרמי בר חמא:",1,0],[11,19,"קומץ מנחה שנטמא וכו' יצא הקומץ חוץ לעזרה וכו'. משנה בפרק הקומץ רבה (מנחות דף כ\"ה):",1,0],[11,20,"קמץ את המנחה ואחר כך נטמאו שיריה כולם וכו'. משנה שם (דף כ\"ו) נטמאו שיריה נשרפו שיריה אבדו שיריה כמדת רבי אליעזר כשירה וכמדת ר' יהושע פסולה, ופירש\"י כמדת ר' אליעזר דאמר בפרק כיצד צולין דם אע\"פ שאין בשר ה\"נ קומץ אע\"פ שאין שירים (בשיריה) כשירה להקטיר הקומץ. כמדת ר' יהושע דאמר אם אין בשר אין דם אם אין דם אין בשר. ובגמרא אמר רב והוא שנטמאו כל שיריה אבל מקצת שיריה לא ואסיקנא דהוא הדין לנשרפו ואבדו. ובתוספתא פ\"ד דמנחות תניא דהוא הדין ליצאו חוץ לקלעים. ופירש\"י והוא שנטמאו כל שיריה הוא דאמר ר' יהושע דפסול להקטיר הקומץ וידוע דהלכה כרבי יהושע.",1,0],[11,20,"ומ\"ש ואם הקטיר הורצה. תוספתא בפרק ד' דמנחות:",2,0],[11,20,"נשאר מעט מן השירים וכו'. בפ\"ק דמנחות (דף ט'):",3,0],[11,21,"היתה מחיצה מלמטה וכו'. בפרק הקומץ רבה (מנחות דף כ״ג כ״ד) איבעיא לן עשרון שחלקו והניחם בביסא מהו לקמוץ מזה על זה אמר רבא ת״ש דתניא והרים ממנו מן המחובר שלא יביא עשרון בשני כלים ויקמוץ הא בכלי אחד דומיא דשני כלים קומץ אמר ליה אביי דילמא שני כלים ה״ד כגון קפיזא דקבא דאע״ג דעריבי מעילאי כיון דמפסקן מחיצתא דקפיזא מתתא. הא כלי אחד דומיא דשני כלים ה״ד כגון עריבת תרנגולים ואע״ג דמפסקן מחיצתא הא נגיע אבל הכא דלא נגיע כלל תיבעי לך. ונראה שרבינו מפרש כגון קפיזא דקבא היינו שהיתה מחיצה מלמטה והוא מעורב מלמעלה ולהכי קרי שני כלים ופסול כלומר והתם משום דמפסקי מחיצתא מתתא מיהא פסול אבל הכא דליכא מחיצה כלל אפשר דכשר וכגון עריבת התרנגולים היינו שהוא חלוק מלמעלה ומעורב מלמטה ולהאי קרי כלי אחד וכשר:",1,0],[11,23,"ומ\"ש חלק העשרון בכלי אחד וכו' לא יקמוץ ואם קמץ לא יקטיר. הטעם משום דכיון דהיא בעיא דלא איפשיטא ספיקא היא.",1,0],[11,23,"ומה שכתב ואם הקטיר הורצה ולא יאכלו השירים. נראה דיליף לה מהדין שכתב לעיל בסמוך:",2,0],[11,24,"קמץ ונתן הקומץ למעלה על השלחן וכו'. בפ' שתי מדות (מנחות דף פ״ז:) בעא מיניה רמי בר חמא מרב חסדא שלחן מהו שיקדש קמצים בגודש שלו מדמקדש לחם קמצים נמי מקדש או דילמא דחזי ליה מקדש דלא חזי ליה לא מקדש [א״ל אינו מקדש] איני והא אמר ר' יוחנן לדברי האומר טפחים ומחצה כופל נמצא שולחן מקדש ט״ו טפח למעלה לדברי האומר טפחים כופל נמצא שלחן מקדש י״ב טפח למעלה א״ל אינו מקדש ליקרב אבל מקדש ליפסל. ודברי רבינו באינו מקדש ליקרב וכו' כפירוש רש״י בפירוש ראשון שכתב הא דאמרינן אינו מקדש מאי דלא חזי ליה היינו ליקרב שאין הקומץ מתקדש שם שעדיין יש לו לקדשו בכלי אחר קודם שיקטירנו אבל מקדש הקמצים ליפסל דקדשי ליפסל בלינה:",1,0],[11,25,"הדביק הקומץ לדופן הכלי וכו'. בפ״ק דמנחות (דף י״א) ובר״פ הוציאו לו (יומא מ״ז:) בעיא דלא איפשיטא:",1,0],[11,26,"עשרון שחלקו ואבד אחד מחלקיו וכו' עד והרי החלקים אינן נוגעים זה בזה. מימרא דרבא פרק שלישי דמנחות (דף כ\"ד):",1,0],[11,28,"קומץ מנחה שנתערב בקומץ מנחה אחרת וכו' עד הרי אלו כשירות. משנה בפ' הקומץ רבה (מנחות דף כ״ב):",1,0],[11,29,"שתי מנחות שלא נקמצו ונתערבו זו בזו וכו' עד סוף הפרק. הכל משנה שם (דף כ\"ג):",1,0],[12,1,"שתי הלחם ולחם הפנים וכו'. תוספתא פ״ח דמנחות ואיתא בגמ' ס״פ אלו מנחות (מנחות דף ע״ו:) ת״ר כל המנחות שריבה במדת עשרונן או שמיעט במדת עשרונן פסולות:",1,0],[12,2,"חלות תודה ורקיקי נזיר שחסרו וכו' עד ויביא נסכים אחרים למלאותן. תוספתא פרק רביעי דמנחות:",1,0],[12,6,"נסכים שקדשו בכלי ונפסל הזבח וכו'. משנה בפ' התודה (מנחות דף ע״ט) הנסכים שקדשו בכלי ונמצא זבח פסול אם יש שם זבח אחר יקרבו עמו ואם לאו יפסלו בלינה, ובגמ' אמר זעירי אין הנסכים מתקדשים אלא בשחיטת הזבח מ״ט אמר קרא זבח ונסכים תנן נסכים שקדשו בכלי ונמצא הזבח פסול אם יש זבח אחר יקרבו עמו ואם לאו יפסלו בלינה מאי לאו דאיפסיל בשחיטה לא דאיפסיל בזריקה כמאן כרבי דאמר שני דברים המתירים מעלים זה בלא זה אפי' תימא ר״א בר״ש כגון שקיבל דמן בכוס ונשפך וכו' סבר לה כוותיה דאבוה דאמר כל העומד ליזרק כזרוק דמי. ונראה שרבינו מפרש דהכי פריך מאי לאו דאיפסיל הזבח בשחיטה ואם איתא דשחיטת הזבח מקדש את הנסכים ולא קודם אמאי יפסלו בלינה הא לא קדשו כלל דהא שחיטה דפסול לא חשיבא שחיטה לקדושי נסכים. ומשני לא דאיפסיל בזריקה דהואיל וכבר קדשו נסכים בשעת שחיטה הילכך אע״ג דאיפסיל זבח בזריקה אם יש שם זבח אחר יקרבו עמו וכן פירש״י בלשון אחר. והראב״ד כתב על דברי רבינו נפסל מקבלה ואילך א״א זה כתב לר״א בר״ש דבעי שני דברים המתירים ואם נתקבל הדם ונשפך כמי שנזרק דמי אבל לרבי אפי' בשחיטה לחודה קדשו ליקרב עם זבח אחר עכ״ל:",1,0],[12,6,"ודע שפירש\"י כמאן כרבי דאמר בפרק התכלת שחט הכבשים לשמן וזרק דמן שלא לשמן הלחם קדוש ואינו קדוש. שני המתירים כגון זריקה ושחיטה מקדשין הקרבן לקדושה. מעלים זה בלא זה והני שחיטה וזריקה מקדשים הם הנסכים וכיון דנסכים אלו הוקדשו בשחיטה אע\"ג דאיפסיל זבח בזריקה קדשו נסכים בשחיטה וכו'. אפילו תימא ר' אלעזר דאמר אין מעלין זה בלא זה דאמר לא קדש הלחם עד שישחוט ויזרוק דמן לשמן. הב\"ע כגון שקיבל הדם בכוס ונשפך אח\"כ נפסל בזריקה ור' אלעזר סבר לה כאבוה דאמר כל העומד ליזרק כזרוק דמי להכי דנתקדשו שני המתירים בשחיטה ובזריקה אבל להכי לא הוי כזרוק שיהא הזבח כשר עכ\"ל. ופסק רבינו כרבי וזהו",2,0],[12,6,"שכתב אם נפסל בשחיטה לא קדשו הנסכים ליקרב נפסל מקבלה ואילך קדשו הנסכים ליקרב כלומר אם השחיטה היתה כתקנה אע\"פ שנפסל אח\"כ בקבלה או בזריקה קדשו הנסכים ליקרב. וזה מבואר בדברי רבינו ואיני יודע למה כתב הראב\"ד על רבינו זה כתב לר' אלעזר בר\"ש וכו' שהרי מבואר בדבריו שאינו פוסק אלא כרבי וכדפרישית. ואין לדחוק ולומר שטעמו מפני שהיה לו לרבינו לכתוב ואם לא נפסל בשחיטה קדשו הנסכים ואם נפסל אח\"כ אם היה זבח אחר זבוח וכו' ומאחר שכתב נפסל מקבלה ואילך משמע ליה דנפסל אחר קבלה קאמר דהוה ליה שני דברים המתירים בכשרות שחיטה וקבלה ואח\"כ נשפך הדם וכר\"א בר\"ש שא\"א לפרש כן בדברי רבינו משום דהא זעירי דאמר אין הנסכים מתקדשים אלא בשחיטה לא אתי אלא כרבי דאילו לר\"א בר\"ש אינם מתקדשים עד שיעשה שני המתירים דהיינו שחיטה וזריקה בכשרות וכי שני אפילו תימא ר\"א בר\"ש קאי אאוקימתא דאוקימנא במתני' דאיפסיל בזריקה דאילו זעירי פשיטא דלא אתי כוותיה וא\"כ מאחר שרבינו פסקה לדזעירי שאין הנסכים מתקדשים ליקרב אלא בשחיטת הזבח וכמבואר בדבריו עוד בפרק י\"ז גבי כבשי עצרת ע\"כ לומר שפסק כרבי ולא כר\"א בר\"ש.",3,0],[12,6,"ומ\"ש ואם נפסל מקבלה ואילך היינו לומר שנפסל בקבלה עצמה או באחת משאר עבודות שאחר קבלה ומה שלא כתב ואם לא נפסל בשחיטה מפני שהיה צריך להאריך ולכתוב עוד ואח\"כ נפסל בקבלה או באחת משאר עבודות. וליישב דברי הראב\"ד נראה לומר שהוא ז\"ל היה מפרש דכי שני אפי' תימא ר\"א בר\"ש לזעירי נמי קאי לומר דשפיר אתי כר\"א בר\"ש והא דלא אדכר זעירי אלא שחיטה משום דעיקר מילתיה אתא לאשמועינן דלא נימא דבכניסתן בכלי בלבד נתקדשו אלא שצריך ג\"כ שחיטת הזבח וזעירי לא נחית נפשיה לפלוגתא דלכ\"ע צריך נמי שחיטת הזבח אלא לרבי בהכי סגי ולר' אלעזר בר\"ש צריך נמי קבלה ואף על גב דמייתי לה מדכתיב זבח ונסכים דמשמע דבשחיטה בלחוד סגי איכא למימר דלר' אלעזר בר\"ש כיון דגלי קרא דצריך שחיטה כיון דס\"ל דב' דברים המתירים אין מעלין זה בלא זה ממילא משמע דקבלה נמי צריך. כל זה לתת מקום לדברי הראב\"ד אבל דברי רבינו מבוארים שהם כרבי וכמו שנתבאר:",4,0],[12,6,"ומ\"ש רבינו אם היה שם זבח אחר זבוח באותה שעה. הכי אמרינן בגמרא דמתני' הכי מיפרשא אם יש שם זבח אחר יקריבו עמו בד\"א בשהיה זבח זבוח באותה שעה אבל (אם) אין זבח זבוח באותה שעה נעשה כמי שנפסלו בלינה ופסולים.",5,0],[12,6,"ומ\"ש רבינו בד\"א בקרבן צבור וכו' שם אם יש שם זבח אחר יקרבו עמו והאמר רב חסדא שמן שהפרישו לשם מנחה זו פסול לשם מנחה אחרת אמר רבי ינאי לב ב\"ד מתנה עליהם אם הוצרכו הוצרכו ואם לאו יהו לזבח אחר.",6,0],[12,6,"ומ\"ש רבינו דלא אמרינן לב בית דין מתנה עליהם אלא בקרבנות צבור. בפרק קמא דזבחים (דף ו':) קרבנות צבור קאמרת שאני קרבנות צבור דלב ב\"ד מתנה עליהם:",7,0],[12,7,"וכל הזבחים שנזבחו שלא לשמן יקרבו נסכיהם:",1,0],[12,8,"ולד תודה ותמורתה והמפריש תודתו ואבדה וכו' עד בין לפני כפרה בין לאחר כפרה. משנה וגמרא בפרק התודה (מנחות דף ע״ט:):",1,0],[12,9,"הפריש תודתו ואבדה והפריש אחרת תחתיה וכו' עד שתיהם אינן טעונות לחם. מימרא דרבא שם (דף פ':):",1,0],[12,10,"המפריש מעות לתודתו וכו' עד וזו התודה האחרונה תקרב בלא לחם. תוספתא פ\"ח דמנחות:",1,0],[12,11,"האומר הרי זו תודה והרי זה לחמה וכו'. בפרק התודה (מנחות דף פ') מימרא דרבי אבא:",1,0],[12,12,"הפריש מעות לתודתו וכו'. שם מימרא דרבא ומפרש טעמא משום דלחם איקרי תודה תודה לא איקרי לחם:",1,0],[12,13,"האומר הרי זה תודה וכו'. שם תני רבי חייא תודה שנתערבה בתמורתה ומתה אחת מהן חבירתה אין לה תקנה היכי נעביד נקריב לחם בהדה דילמא תמורה היא לא נקריב לחם בהדה דילמא תודה היא והראב\"ד כתב על דברי רבינו א\"א מה תקנה יש בזה וכו'. ואיני מבין מה השגה היא זו דהא בגמרא אמרינן היכי דמי אי דאמר עלי לא סגי דלא מייתי ליה בהמה אחרינא ולחם ולימא אי הך דקיימא תמורה היא הא תודה והא לחמה אי הך דקיימא תודה היא הא לחמה והא תהוי אחריות לא צריכא דאמר הרי זו ע\"כ. ומאחר שרבינו פתח באומר הרי זו תודה וכדאוקימנא לדרבי חייא לא נשארה עליו שום תלונה. ואין לומר שמשיג על רבינו שכתב אלא תרעה שלא נזכר בדברי רבי חייא ואם בא לומר שיש לה תקנה ברעייה הא לאו תקנה היא ואם היה רוצה לומר תקנה הל\"ל יביא אחרת ולחמה וכו' דמי הגיד לו שבא לומר תקנה שכל עצמו לא בא לומר אלא שלא תקרב זו לעולם וכדתני רבי חייא אין לה תקנה אלא שסיים לומר מה יעשה בה. גם אין לומר שסובר הראב\"ד שמה שאמר רבי חייא אין לה תקנה היינו לומר שלה בעצמה אין תקנה אבל ליפטר מחיובו צריך לעשות תקנה שיביא אחרת ולחמה וכו' דכיון דלא אמר הרי זו אין כאן שום חיוב:",1,0],[12,14,"תודה שנפרסה חלה מחלותיה כולן פסולות. ברייתא בסוף פרק קמא דמנחות (דף י\"ב:) ודייק רבא הא יצתה הני דאיכא גוואי כשירות ומוקי לה כר\"ע ואע\"ג דאביי דחי התם ואמר דילמא ר' אליעזר היא דחייה בעלמא היא ועוד דכרבא נקטינן וכיון דמכשר ביצאה כ\"ש דמכשר בנטמאת שהציץ מרצה ומפרש לה רבינו בתודה דאף על גב דקרא דמייתי בגמרא בלחם הפנים כתיב ילפינן מיניה לתודה וגם במנחה כתיב הכי ולשון הגמ' שאמרו זריקה מועלת בתודה הוא דשייך.",1,0],[12,14,"ומה שכתב נפרס לחמה או נטמא או יצאה וכו' עד וממה שבפנים על מה שבחוץ. הכל ברייתא פרק התכלת (מנחות דף מ\"ו):",2,0],[12,14,"וכתב הראב\"ד תודה שנפרסה וכו'. א\"א במאי עסקינן אי קודם שחיטה נפרסה וכו'. תחלת דבריו דבר פשוט הוא נלמד מברייתא דפ' התכלת שהזכרתי בסמוך. ומ\"ש בין נפרס בין יצא בין נטמא הכל פסול וכו'. למדו הראב\"ד מהברייתא הנזכרת דקתני מששחטה נפרס לחמה הדם יזרק והלחם פסול וכו' מששחטה יצא לחמה הדם יזרק והלחם פסול מששחטה נטמא לחמה הדם יזרק וכו' והלחם פסול ומשמע ליה להראב\"ד דכיון דנפרס לחמה ויצא ונטמא בחדא גוונא תננהו אין חילוק ביניהם וכיון דתניא בספ\"ק דמנחות שאם נפרסה אחת מהן כולן פסולות וע\"כ היינו בין שחיטה לזריקה כמו שנתבאר הוא הדין לנטמא אחת מן החלות או שיצאה ואע\"ג דבברייתא בספ\"ק דמנחות אהא דתניא שאם נפרסה אחת מהן כולן פסולות דייק רבא הא יצתה הני דאיכא גוואי כשירות ואביי דייק הא נטמאת הנך כשירות אפשר דאכתי לא הוה שמיע להו ברייתא דפ' התכלת ורבינו לא נראה לו לומר דלא הוה שמיע להו ההיא ברייתא אע\"ג דשמיע להו ההיא ברייתא דייקי מהאי ברייתא דנפרס לחמה דוקא קתני ואע\"ג דברייתא דהתכלת תני להו בחד גוונא איכא למימר מידי איריא הא כדאיתא והא כדאיתא:",3,0],[12,15,"תודה שנשחטה על שמונים חלות וכו' ואם אמר יקדשו ארבעים מתוך שמונים וכו'. בפ' התודה (מנחות דף ע״ח:) פלוגתא דחזקיה ור״י ומייתי לה בפ' האיש מקדש (קידושין דף נ״א) ובפ' מי שהוציאוהו (עירובין דף נ') ופסק רבינו כר״י ויש לתמוה אמאי לא פסק כחזקיה דרביה הוא.",1,0],[12,15,"ומ\"ש מושך וכו'. נתבאר בפ' התכלת:",2,0],[12,16,"השוחט את התודה וכו'. משנה וברייתא בפ' התודה (מנחות ע״ח:) ופירש רש״י חוץ לחומת בית פגי היינו לחומת הר הבית:",1,0],[12,17,"שחטה עד שלא קרמו פני הלחם בתנור וכו' עד סוף הפרק. משנה שם:",1,0],[12,18,"שחטה ונפסלה בשחיטתה וכו' קדש הלחם. אע\"ג דאחר שנתפגל הביאה קדוש להפסל בטבול יום ובלינה דאין חייבים משום פגול ומשום נותר אלא הבשר שהותר שעה אחת קאמר קדש הלחם להתחייב עליו משום פגול.",1,0],[12,18,"ומ\"ש וכן הדין באיל נזיר וכו'. שם בגמרא:",2,0],[13,1,"שלש מחשבות הן וכו'. מתבאר והולך.",1,0],[13,1,"ומה שכתב מחשבת שינוי השם וכו'. בפרק קמא דזבחים תנן כל הזבחים שנזבחו שלא לשמן כשרים אלא שלא עלו לבעלים לשם חובה חוץ מן הפסח והחטאת ובגמרא יליף מקראי דבפסח וחטאת פוסל בין שינוי קדש בין שינוי בעלים.",2,0],[13,1,"ומה שכתב רבינו כגון שהיה עולה ויחשב שהוא שלמים אע\"ג דכל הזבחים חוץ מפסח וחטאת כשרים שלא לשמן כיון דלא עלו לבעלים לשם חובה שפיר שייך למימר בהו שם פיסול.",3,0],[13,1,"ומה שכתב או ישחטנו לשם עולה ושלמים או לשם שלמים ולשם עולה. הוא ממה ששנינו בסוף פרק קמא דזבחים (דף י\"ג) גבי פסח וחטאת ששחטן לשמן ושלא לשמן או שלא לשמן ולשמן:",4,0],[13,1,"מחשבת המקום כיצד וכו'. מבואר במשנה פרק ב' דזבחים (דף כ\"ה):",5,0],[13,1,"מחשבת הזמן כיצד וכו' עד הרי הקרבן פגול. מבואר שם במשנה:",6,0],[13,2,"ומ\"ש מפי השמועה למדו שזה שנאמר בתורה ואם האכל יאכל וכו'. בפ\"ב דזבחים (דף כ\"ט).",1,0],[13,2,"ומה שכתב אחד אכילת אדם ואחד אכילת מזבח וכו'. שם (דף כ\"ח):",2,0],[13,4,"ומ\"ש אבל קרבן שלא נפסדה מחשבתו אלא נזרק על המזבח כהלכתו וכו'. שם (דף כ\"ו כ\"ט).",1,0],[13,4,"ומ״ש לפיכך אין מתפגל אלא דבר שיש לו מתירין בין לאדם בין למזבח. משנה בפ' ב״ש (זבחים דף מ״ג):",2,0],[13,4,"אחד זבח שחשב בו אחת משלש מחשבות אלו וכו' נמצאת למד שבארבע עבודות הזבח נפסל וכו'. משנה בספ\"ק דזבחים (דף י\"ג):",3,0],[13,5,"ומ״ש והעוף בשני דברים וכו'. משנה בפ' קדשי קדשים (זבחים דף ס״ד ס״ה):",1,0],[13,6,"ומ\"ש והמנחות הנקמצות בד' וכו'. משנה בפירקא קמא דמנחות (דף י\"ב) ובריש פ\"ב דמנחות [י\"ג] ובספ\"ק דזבחים (דף י\"ג:) מדמה ארבע עבודות אלו לארבע עבודות שבזבח דקומץ היינו שוחט. מוליך היינו מוליך. מקטיר היינו זורק. נותן בכלי דמי לקבלה. ופירש\"י קומץ דמי לשוחט שזה נוטל ומפריש חלק לגבוה מחלק כהנים וכן זה:",1,0],[13,8,"וכן המחשב באחת מארבע עבודות אלו וכו' כיצד המחשב בשעת שחיטה וכו' להניח דם הזבח או אימוריו למחר וכו' עד הזבח כשר. משנה בפרק שלישי דזבחים (דף ל\"ו).",1,0],[13,8,"ומ\"ש וכן אם חשב בשעת קמיצת המנחה וכו' להניח קומצה או לבונתה למחר וכו'. הוא נלמד מדין הזבח:",2,0],[13,9,"כבר ביארנו שהולכה שלא ברגל אינה הולכה וכו'. בסוף פ\"ק דזבחים (דף י\"ד ט\"ו) אמר ר\"י הולכה שלא ברגל לא שמה הולכה ואע\"ג דאמרינן התם דאותביה ר\"נ ואסיקנא בתיובתא משמע לרבינו דלא אותביה לעיקר מימריה אלא למאי דסיים בה אלמא לא אפשר לתקונה הוא דאותביה. וכן יש לדקדק ממה שפירש\"י תיובתא דעולא כלומר לעולא דאמר אלמא לא אפשר לתקונה הוא דמותבינן ולא למאי דאמר משום ר\"י הולכה ברגל לא שמה הולכה:",1,0],[13,9,"ומ\"ש רבינו והמהלך במקום שא\"צ הרי זה הולכה וכו'. בספ\"ק דזבחים (דף י\"ג) תנן שהזבח נפסל בארבעה דברים בשחיטה ובקיבול ובהילוך ובזריקה ר\"ש מכשיר בהילוך וכו' ר\"א אומר המהלך במקום שהוא צריך להלך מחשבה פוסלת ובמקום שא\"צ להלך אין מחשבה פוסלת ואמרינן בגמ' (דף ט\"ו:) דלר\"א קבלו בפנים והוציאו לחוץ זהו הילוך שאין צריך הא חזר והכניסו הילוך שצריך להלוך הוא. ופרש\"י בפנים לצד המזבח והוציאו לחוץ כלומר ריחקו מהמזבח [הנך] חוץ ופנים כולהו בעזרה. ולת\"ק אפי' קבלו בפנים והוציאו לחוץ וחשב עליו בשעה שהוציאו לחוץ פוסלת וידוע דהלכה כת\"ק. והראב\"ד כתב כבר ביארנו וכו' עד הרי זו הלכה א\"א לא נהיר דסוגיין כולה כר' אלעזר דאמר לא שמה הולכה עכ\"ל. וליישב דעת רבינו י\"ל שאין הכרח לומר דסוגיין כר' אלעזר דאע\"ג דאיפליגו אביי ורבא בפירוש מילתיה דר' אלעזר ורבנן לאו משום דס\"ל הלכה כר\"א אלא לפרושי מילתיה דת\"ק דמדר\"א נשמע לת\"ק. ודעת רבינו שלא כדברי רש\"י באי תניא תניא שרבינו מפרש דלתנא קמא הילוך פוסל בכל גוונא אפילו במקום שאינו צריך להלך:",2,0],[14,1,"אין המחשבה הולכת אלא אחר העובד וכו'. בס\"פ ב\"ש (זבחים מ\"ו:) א\"ר יוסי שאין המחשבה הולכת אלא אחר העובד ובגמ' (דף מ\"ז) מתני' דלא כי האי תנא דתניא א\"ר אליעזר בר' יוסי שמעתי שהבעלים מפגלים. ומשמע לרבינו דהלכה כמתני' ועוד דאמרינן התם בגמרא אמר אביי ר\"א בר' יוסי ור' אלעזר ורשב\"א כולהו ס\"ל זה מחשב וזה עובד הויא מחשבה וכל כה\"ג ה\"ל שיטה ולית הלכתא כחד מינייהו:",1,0],[14,2,"ואין המחשבה [מועלת] וכו'. מימרא דרבא בפ\"ב דזבחים (דף כ\"ו ע\"ב) ובמנחות (דף ה':).",1,0],[14,2,"ומ\"ש ממי שהוא ראוי כיצד אחד מן הפסולים לעבודה שקבל הדם או הוליך כו' ואותו דם שקיבל או שזרק מקצתו ישפך לאמה. פשוט הוא.",2,0],[14,2,"ומ\"ש ואם נשאר דם הנפש יחזור הראוי לעבודה ויקבל וכו'. משנה בפ\"ג דזבחים (דף ל\"ב).",3,0],[14,2,"ומ\"ש אבל אם חשב הפסול במחשבתו בשעת שחיטה פסל במחשבתו וכו'. שם במשנה.",4,0],[14,2,"ומ\"ש יש קרבנות שאם נעשו שלא לשמן כשרים כמו שיתבאר. הוא פט\"ו:",5,0],[14,2,"לפיכך אם קיבל הדם כהן זה וכו' פסל הזבח כאילו עשאו לשמו וכו'. נראה שהטעם שמאחר דשלא לשמו פסל בעלמא והכא לא פסל הוי כמי שאינו ראוי לעבודה כראוי לענין שיהא פוסל במחשבה שאע\"פ שיש דם הנפש לא מהני שיחזור הכשר ויקבל אכן צריך לימוד מנין לו לרבינו זה:",6,0],[14,3,"בדבר הראוי לעבודה כיצד וכו'. בפ\"ק דמנחות (דף ה':) איפליגו אמוראי במילתא ורבא דהוא בתרא אמר מנחת העומר שקמצה שלא לשמה כשירה ושיריה נאכלין ואינה צריכה מנחת העומר אחר להתירה שאין המחשבה מועלת אלא במי שהוא ראוי לעבודה ובדבר הראוי לעבודה ובמקום הראוי לעבודה במי שהוא ראוי לעבודה לאפוקי כהן בעל מום ובדבר הראוי לעבודה לאפוקי מנחת העומר דלא חזיא דחידוש הוא ובמקום הראוי לעבודה לאפוקי נפגם המזבח. ופירש\"י מנחת העומר של שעורים ואינה ראויה אלא לעבודה זו להתיר ולא משום קרבן אתיא וכו' והא דפסלה מחשבה במנחת קנאות משום דרחמנא קרייה חטאת.",1,0],[14,3,"ומ\"ש וכן המחשב במנחת קנאות והלבונה עליה וכו'. כן משמע בתוספתא דמנחות ספ\"ה:",2,0],[14,3,"וכתב הראב\"ד על דברי רבינו לא מחוורא האי גירסא וכו' עד שקרב העומר והותר באכילה. ולפי נוסחתו מנחת העומר היינו מנחה שהוקרבה אחר שהביאו העומר קודם שיביאו שתי הלחם והנך רואה כמה דחוק פירוש זה וההכרע שכתב אינו כדאי לדחות גירסת רבינו ורש\"י דאיכא למימר לבונה דנקט במנחת קנאות חדא ועוד קאמר חדא שהיא של שעורים ועוד שאין עליה לבונה:",3,0],[14,4,"במקום הראוי לעבודה כיצד מזבח שנפגם וכו'. מבואר במימרא דרבא שכתבתי בסמוך.",1,0],[14,4,"ומ\"ש קמץ את המנחה בחוץ וחשב וכו'. פשוט הוא:",2,0],[14,5,"אלו דברים שאינם ראויים לאכילה וכו' עד דבר העומד לשריפה. הוא הקדמה למה שיבא אח\"כ:",1,0],[14,7,"ומ\"ש ואלו שאינם ראויים לא לאכילה ולא להקטרה בשר חטאת הנשרפת. זה פשוט דלא מיקרי ראוי להקטרה אלא דבר הנקטר ע\"ג המזבח בלבד.",1,0],[14,7,"ומ\"ש והעור של בהמה כולו חוץ מעור שתחת האליה הוא ראוי לאכילה. בפרק שני דזבחים (דף כ\"א) אמרינן דעור שתחת האליה ראוי למאכל אדם.",2,0],[14,7,"ומ\"ש אבל המוראה בפרק ג' דזבחים (דף ל\"ה) מני בברייתא מוראה בהדי הנך דאין מפגלין ולא מתפגלין מפני שאינם ראויים לא למאכל אדם ולא למאכל מזבח. ומה שפירש בו רבינו שהוא הקרום הדק הדבק בעור ומבדיל בינו ובין הבשר אפשר שפירש כן מפני שהוא שם בברייתא סמוך לאלל.",3,0],[14,7,"ומ\"ש וכן העצמות והגידים והטלפים. משנה שם בפרק ג' דזבחים.",4,0],[14,7,"ומ\"ש והנוצה של עוף. משנה בפ\"ק דטהרות דאינה מצטרפת לטומאה.",5,0],[14,7,"ומה שכתב והצפרניים והחרטום. שם במשנה החרטום והצפרניים מטמאין ומיטמאים ומצטרפין ובפ' העור והרוטב (חולין דף קכ״א) מקשה חרטום עץ בעלמא הוא ומוקי לה בחרטום תחתון של עליון ופירש״י קליפת רצועה דקה יש בתוך הפה דבוקה לחרטום עליון לארכו וצפרניים מוקי לה במקום שמובלעים בבשר.",6,0],[14,7,"ומה שכתב וראשי גפיים וראש הזנב. גם זה שם וכת\"ק ולא כר' יוסי דאמר התם דמצטרפין לטומאה שכן מניחים בפטומות.",7,0],[14,7,"ומ\"ש אפילו מקומות הרכים מכל אלו הדבוקים בבשר וכו'. נתבאר במ\"ש בסמוך דמוקי בגמרא הא דקתני צפרניים מצטרפים במקום שמובלעים בבשר משמע דראשי גפיים וראשי הזנב דקתני אינם מצטרפין אפי' במובלעין בבשר נמי קאמר דאינם מצטרפין.",8,0],[14,7,"ומ\"ש וכן המרק והתבלין והשליל והשיליא וביצת העוף והבשר שפולטתו הסכין בשעת הפשטן וכו'. משנה בפ' ג' דזבחים (דף ל\"ז):",9,0],[14,8,"ומ\"ש ומחשבין על דבר העומד לאיבוד או לשריפה. בפ\"ק דמעילה (דף ז'):",1,0],[14,8,"המחשב באחת מאותן ארבע העבודות וכו' עד הזבח כשר. גם זה שם במשנה.",2,0],[14,8,"ומה שכתב כיצד חשב לשתות מדם הזבח וכו'. בפרק הקומץ רבה (מנחות דף י״ז:) תניא השוחט את הזבח לשתות מדמו למחר וכו' כשר.",3,0],[14,8,"ומה שכתב וכן אם חשב לאכול מפרים ושעירים הנשרפים וכו'. בפ\"ג דזבחים (דף ל\"ה) חישב באכילת פרים ובשריפתן לא עשה ולא כלום. וצריך טעם למה השמיט מלכתוב דה\"ה אם חשב לשרפן למחר שהם כשרים:",4,0],[14,9,"חשב שיאכלו הטמאים וכו'. בספ\"ג דזבחים (דף ל\"ו ע\"ב) אמר רב חסדא אמר רבינא בר שילא חישב שיאכלוהו טמאים למחר חייב (כרת) אמר רבא תדע דבשר לפני זריקה לא חזי וכי מחשב ביה מיפסיל ולא היא התם זריק ומיחזי הכא לא מיחזי כלל ומשמע לרבינו דהא דקאמר ולא היא לא לדחויי דינא דרב חסדא אתמר אלא לדחויי סייעתא דאייתי רבא ואע\"ג דסייעתא אידחיא דינא לא אידחי מאחר דרב חסדא ורבינא בר שילא ורבא ס\"ל הכי וליכא מאן דפליג עלייהו. ויש סעד לזה מדאמר ר' ינאי זבחים (דף ל\"א) חישב שיאכלוהו כלבים למחר הוי פגול דכתיב יאכלו הכלבים ומי עדיפי כלבים מטמאים.",1,0],[14,9,"ומ\"ש כמו שביארנו. כלומר שהזבח מתפגל במחשבת חוץ לזמנו:",2,0],[14,10,"אין אכילה פחותה מכזית וכו' עד הזבח כשר. משנה בפרק ג' דזבחים (דף כ\"ט:).",1,0],[14,10,"ומ\"ש חשב לאכול כחצי זית בחוץ ולהקטיר כחצי זית בחוץ וכו' שאין אכילה והקטרה מצטרפין. שם.",2,0],[14,10,"ומ\"ש ואם הוציאו בלשון אכילה וכו' לשון אכילה אחד הוא. שם בגמ' (דף ל\"א):",3,0],[14,10,"חשב לאכול או להקטיר כחצי זית וכו'. מתבאר בספ\"ב דזבחים (דף ל\"א):",4,0],[14,10,"חשב לאכול כחצי זית ושתאכל בהמה או חיה כחצי זית וכו'. שם מימרא דר' ינאי:",5,0],[14,10,"חשב על כזית שיאכלוהו שנים הרי אלו מצטרפין. שם ע\"ב בעיא דאיפשיטא:",6,0],[14,10,"חשב לאכול כזית ביותר מכדי אכילת פרס הרי זה מצטרף. שם בעיא דרבא ובעי אביי למפשטה ממתניתין ודחי ליה. ומשמע לרבינו דדחייה בעלמא היא דפשטא דמתני' כדאמר אביי היא והכי הלכתא. ואפשר שלא היה בגירסתו דחייה כלל:",7,0],[14,10,"חשב בשעת זביחה לאכול כחצי זית וכו'. ברייתא בפ\"ב דמנחות (דף י\"ד:).",8,0],[14,10,"ומ\"ש וכן אם חשב על כזית בשעת קבלה ועל כזית בשעת הולכה. נ\"ל שטעות סופר יש כאן וצריך להגיה כחצי זית בשעת קבלה וכחצי זית בשעת הולכה והוא שם בגמרא אהאי ברייתא דבסמוך א\"ד שחיטה וזריקה דתרוייהו מתירין אין קבלה והולכה לא ואיכא דאמרי הנך דמירחקן וכ\"ש הני דמיקרבן ופסק רבינו כלישנא דמחמיר ועוד דבתרא הוא ועוד דבגמ' משמע דלרבנן מצטרפות ארבע עבודות:",9,0],[14,10,"חשב להקטיר כחצי זית וכו'. ברפ\"ב דמנחות (דף י\"ג) תנן דלת\"ק לבונה נמי מפגלת כמו המנחה עצמה וכן מבואר במתניתין בפ\"ק:",10,0],[14,10,"אחד המחשב לזרוק דם הזבח וכו'. משנה בפ' שני דזבחים (דף כ\"ח).",11,0],[14,10,"ומ\"ש כיון שחשב על כדי הזיה מן הדם פסל. פשוט הוא שאם לא חשב על כדי הזיה לא פסל:",12,0],[15,1,"כל הזבחים שנשחטו במחשבת שינוי השם וכו'. משנה בריש זבחים.",1,0],[15,1,"ומ\"ש ואחד המשנה שם הזבח בשעת שחיטה או בשעת קבלה או בשעת הולכה או בזריקה. גם זה משנה שם (דף י\"ג).",2,0],[15,1,"ומ\"ש בין בקרבנות יחיד בין בקרבנות הצבור. מתבאר בפ\"ק דזבחים (דף ד') דשנוי קדש ישנו בצבור כביחיד אבל שינוי בעלים לא שייך בצבור שהרי הכל בעליו:",3,0],[15,1,"כיצד לא עלו לשם חובה וכו' וכן אם שחט עולות ראובן וכו'. שם בגמ' יליף מקראי דבין שינוי קדש בין שינוי בעלים בעינן בכולהו קרבנות לשמן למצוה ובפסח וחטאת לעכב.",4,0],[15,1,"ומ״ש בד״א כשעקר שם הזבח בזדון אבל אם טעה ודימה שזו העולה שלמים הוא וכו'. בפ' התכלת (מנחות דף מ״ט) איפליגו אמוראי עקירה בטעות אי הויא עקירה או לא ורבא דהוא בתרא אמר דעקירה בטעות לא הויא עקירה ואביי נמי משמע דסבר כוותיה ובפסחים פ' אלו דברים (פסחים דף ע״ב.) מתמה גמרא אמתני' דהתם שמע מינה עקירה בטעות הויא עקירה משמע דס״ל דלא הויא עקירה.",5,0],[15,1,"ומ\"ש וכן החטאת והפסח שעשאן במחשבת שינוי השם בטעות כשרים וכו'. הוא מה שכתבתי בסמוך דאיתא בפ' אלו דברים גבי הפסח:",6,0],[15,1,"וכן עולת העוף שמלקה וכו'. אריש פירקא קאי דקתני כל הזבחים שנשחטו במחשבת שינוי השם כשרים אלא שלא עלו לבעלים לשם חובה חוץ מן החטאת והשתא קאמר דהוא הדין לקרבן העוף דשינוי השם פסול בחטאת ובעולה כשר אלא שלא עלה לבעלים לשם חובה והוא מבואר במשנה פ' קדשי הקדשים (ס\"ד:):",7,0],[15,2,"וכן כל המנחות וכו'. משנה בריש מנחות כל המנחות שנקמצו שלא לשמן כשירות אלא שלא עלו לבעלים משום חובה חוץ ממנחת חוטא ומנחת קנאות.",1,0],[15,2,"ומ\"ש שאם חשב באחת מארבע עבודות שלהן מחשבת שינוי השם פסולות וכו'. משנה שם (דף י\"ב) ובפי\"ג ביאר רבינו מה הן ארבע עבודות דמנחות:",2,0],[15,2,"שינוי השם במנחה כיצד וכו'. מתבאר בגמ' בריש מנחות:",3,0],[15,3,"אסור לחשב בקדשים וכו' לפיכך זבח ששחטו שלא לשמו וכו' חייב להשלים שאר עבודות לשמן וכו'. דיוקא דמתני' ומימרא דרבא בריש זבחים ובריש מנחות.",1,0],[15,3,"ומה שכתב אפילו שחט וקבל והוליך וכו' חייב לזרוק במחשבה נכונה. מימרא דרבא בפ\"ק דזבחים (דף ז').",2,0],[15,3,"ומ\"ש רבינו כמו שיתבאר. הוא בפרק י\"ז:",3,0],[15,3,"ומפני מה נשתנה דין החטאת והפסח וכו'. בריש זבחים (דף ז') וריש מנחות (דף ד':):",4,0],[15,4,"חטאת ששחטה לשם זבח אחר וכו' אבל אם שחטה לשם חולין הרי זה כשירה וכו' עד ואין החולין מחללין קדשים. מימרות אמוראים בס\"פ ב\"ש (זבחים מ\"ו:):",1,0],[15,6,"שחטה לשם חטאת אחרת וכו' פסולה. בפ\"ק דזבחים (דף ז') אמר רבא חטאת ששחטה לשם חטאת כשירה וכו' מ\"ט ושחט אותה לחטאת אמר רחמנא והרי חטאת וכו' שחטה על מי שמחוייב חטאת פסולה על מי שמחוייב עולה כשירה מ\"ט וכפר עליו ולא על חבירו חבירו דומיא דידיה דמחוייב כפרה כמותו. ופירש\"י חטאת חלב ששחטה לשם חטאת דם כשירה ועולה לבעלים אפי' שינוי קדש אין כאן. ובדף ט' ע\"ב גרסינן אמר רבא חטאת חלב ששחטה לשם חטאת ע\"ז כשירה לשם חטאת נזיר לשם חטאת מצורע פסולה. הני עולות נינהו כלומר דכיון שאינן באות אלא להכשיר ולא לכפר על חטא ידוע ה\"ל עולות. בעי רבא חטאת חלב ששחטה לשם חטאת דטומאת מקדש מהו מי אמרינן כרת כמותה או דילמא אין קבוע כמותה. רב אחא בריה דרבא מתני כולהו לפיסולא ושחט אותה לחטאת לשם אותה חטאת אמר ליה רב אשי לרב אחא בריה דרבא היכי מתניתו לה א\"ל אנן בשינוי בעלים מתנינן לה אמר רבא חטאת ששחטה על מי שמחוייב חטאת דם וחטאת ע\"ז פסולה על מי שמחוייב חטאת נזיר וחטאת מצורע כשירה ובעינן לה הכי בעי רבא חטאת חלב ששחטה על מי שמחוייב חטאת דטומאת מקדש וקדשיו כלומר שהיא בעולה ויורד מהו מי אמרינן כרת כמותה או דילמא אין קבוע כמותה תיקו. ופסק רבינו כרב אחא בריה דרבא משום דרב אשי דהוא בתרא משמע דסבר כוותיה דמדלא אהדר ליה מידי משמע דקיבלה מיניה. ועוד דסתם גמרא דסוף כריתות (דף כ\"ז) כוותיה דקאמר שאם הפריש בהמה על החלב והביאה על הדם על הדם והביאה על החלב לא כפר ובבעיא דרבא דסלקא בתיקו פסק לחומרא. ומ\"מ עדיין יש לתמוה למה השמיט הא דאמר רבא חטאת ששחטה על מי שמחוייב חטאת נזיר חטאת מצורע כשירה וצ\"ל שלא היה כן בגירסתו אלא הכי גריס א\"ל רב אשי לרב אחא בעיא דרבא היכי מתניתו לה א\"ל אנן בשינוי בעלים מתנינן לה והכי מתנינן לה בעי רבא חטאת חלב ששחטה וכו':",1,0],[15,9,"שחטה לשם מת כשירה וכו'. מימרא דרבא שם:",1,0],[15,9,"שחטה לשם מי שאינו חייב קרבן כלל וכו'. גם זה מימרא דרבא שם (דף ז') ולקמן בסמוך אבאר:",2,0],[15,10,"שחטה לשמה וכו'. שם (זבחים ט':) פלוגתא דר\"י ור\"ל ופסק כר\"י דהלכה כוותיה לגבי ר\"ל ועוד דר\"נ אמר פסולה ורבה אמר כשירה והדר ביה רבה מק\"ו דרב אשי:",1,0],[15,11,"הפסח ששחטו במחשבת שינוי השם וכו'. אפשר שהטעם מדכתיב ביה לה' משמע דלשם חולין פסול:",1,0],[15,11,"בד\"א ששחטו בזמנו וכו' אבל אם שחטו שלא בזמנו במחשבה שלא לשמו כשר. משנה בריש זבחים כל הזבחים שנזבחו שלא לשמן כשרים אלא שלא עלו לבעלים לשם חובה חוץ מן הפסח והחטאת הפסח בזמנו והחטאת בכל זמן.",2,0],[15,11,"ומ\"ש אפילו שחטו בשחרית וכו'. שם במשנה (דף י\"ב) פלוגתא דתנאי ופסק כבן בתירא דפסל משום דשקלי וטרו אמוראי אליביה והראב\"ד שכתב על דברי רבינו א\"א זהו כבן בתירא ור' יהושע מכשיר עכ\"ל. משיג עליו למה הניח ר' יהושע דהוא מארי דגמרא טפי וכבר כתבתי טעם לדבר.",3,0],[15,11,"ומ״ש שלא לשם בעליו נעשה כמי שאין לו בעלים בזמנו ופסול. בפסחים פרק תמיד נשחט (פסחים דף ס':) בעיא דאיפשיטא:",4,0],[15,12,"פסח ששחטו (שלא) לשמו בארבעה עשר קודם חצות פסול וכו'. נתבאר בסמוך ואיני יודע למה שנאו. וצ\"ל דהאי שלא טעות סופר הוא ומוכיחים הדברים כן מדמסיים בה פסול לפי שאינו זמנו והיינו טעמא לא שייר אלא בלשמו והוא מדאמר ר\"י פוסל היה בן בתירא בפסח ששחטו [בארבעה עשר] שחרית בין לשמו בין שלא לשמו לשמו דבעי בין הערביים ובפ' תמיד נשחט שם תנן שחטו (לפסח) קודם חצות פסול שנאמר בו בין הערבים:",1,0],[15,12,"עברה שנתו ושחטו בזמנו וכו' הרי אלו כשרים וכו'. בפירקא קמא דזבחים (דף י״א:) ובפסחים פרק תמיד נשחט (פסחים דף ס״ב:) פלוגתא דרבי אליעזר ורבי יהושע ופסק כרבי יהושע:",2,0],[15,13,"תודה ששחטה לשם שלמים וכו'. פירקא קמא דזבחים (דף ד'):",1,0],[15,14,"עולה ששחטה על מי שאינו מחוייב קרבן כלל וכו'. נלמד ממ\"ש בסמוך שאמר רבא גבי חטאת בפ\"ק דזבחים (דף ז') אלא שיש לגמגם ששם נתן טעם שמא מחוייב הוא ואינו יודע וכאן נתן טעם שא\"א שלא יהיה חייב כפרה לשמים וכו' ובגמרא נתנו טעם זה ולא הראשון. ומשמע לי דרבינו הוה גריס בגמרא תרווייהו כלשון שכתבם והוי כיהיב תרי טעמי חדא שמא מחוייב הוא ואינו יודע ועוד שודאי הוא מחוייב שאין לך אדם מישראל וכו':",1,0],[15,15,"עולה הבאה לאחר מיתה וכו'. מימרא דרבא בפרק קמא דזבחים (דף ז':) ואע\"ג דאיכא מאן דפליג עליה התם פסק כרבא דבתרא הוא:",1,0],[15,16,"שני כבשי עצרת ששחטן לשם אילים וכו' עד מפני שהיא עקירה בטעות. בפרק התכלת (מנחות דף מ״ט) תני רבה בר בר חנה קמי דרב כבשי עצרת ששחטן לשם אילים כשירים ולא עלו לבעלים לשם חובה א״ל רב עלו ועלו אמר רב חסדא מסתברא מילתיה דרב בכסבור אילים ושחטן לשם כבשים שהרי כבשים לשם כבשים נשחטו אבל כסבור אילים ושחטן לשם אילים לא עקירה בטעות הויא עקירה רבא אמר עקירה בטעות לא הויא עקירה. ופסק כרבא דבתרא הוא ועוד דאביי משמע התם דסבר כוותיה ומשמע דדוקא משום דהוי עקירה בטעות קאמר רבא דעלו לבעלים אבל אם לא היתה בטעות לא עלו:",1,0],[15,17,"אשם מצורע ששחטו שלא לשמו וכו'. ברייתא בפ\"ק דמנחות (דף ה') ובפרק שתי מדות:",1,0],[15,18,"ומ\"ש כבש הבא עם העומר ששחטו שלא לשמו וכו'. שם (דף פ\"ט) א\"ר יוחנן אשם מצורע ששחטו שלא לשמו טעון נסכים שאם אי אתה אומר כן פסלתו מתקיף לה רב מנשיא בר גדא אלא מעתה כבש הבא עם עומר ששחטו שלא לשמו תהא מנחתו כפולה שאם אי אתה אומר כן פסלתו ותמיד של שחר ששחטו שלא לשמו יהא טעון שתי גזירים בכהן אחד שאם אי אתה אומר כן פסלתו וכו' אין ה\"נ אלא אמר אביי חדא מינייהו נקט רבי אבא אמר בשלמא הנך עולות נינהו אי לא חזי לעולת חובה קרבי לעולת נדבה אלא הכא אי לא מוקמת ליה במילתיה אשם נדבה מי איכא ופסק כר' אבא דמסתבר טעמיה:",1,0],[15,19,"שני כבשי עצרת ששחטן שלא לשמן וכו' עד להקטיר אימורים בערב. ברייתא בפ' התכלת (מנחות דף מ״ז):",1,0],[15,20,"וכן שלמי נזיר ששחטן שלא לשמן אע\"פ שלא וכו'. שם תני לוי:",1,0],[15,20,"וכן אשם נזיר ואשם מצורע ששחטן שלא לשמן וכו'. גם זה שם תני לוי ובפ\"ק (דף ד') דאמר רב וכו' אשם נזיר ואשם מצורע ששחטן שלא לשמן פסולים ואסיקנא בתיובתא:",2,0],[16,1,"כבר ביארנו וכו' ואם חשב מחשבת הזמן הקרבן פגול עד אין זה פגול אלא פסול. משנה בפ\"ב דזבחים (דף כ\"ט).",1,0],[16,1,"ומ\"ש וה\"ה בעופות. משנה בפ' קדשי הקדשים (דף ס\"ד:).",2,0],[16,1,"ומ\"ש ובמנחות. משנה בפ\"ק דמנחות:",3,0],[16,2,"המחשב באחת מד' עבודות וכו' עד הרי הקרבן פסול ואינו פגול. משנה בפרקים הנזכרים.",1,0],[16,2,"ומ\"ש וכן אם עירב המחשבה בהקטרה ה\"ז פסול ואינו פגול. גם זה משנה בפרקים הנזכרים לאכול כחצי זית להקטיר כחצי זית כשר שאין אכילה והקטרה מצטרפין:",2,0],[16,3,"חשב לאכול או להקטיר וכו'. מתבאר ממה שיבא:",1,0],[16,4,"חשב על חצי זית במחשבת הזמן וכו'. פלוגתא דאמוראי בסוף פרק שני דזבחים (דף ל\"א) ופסק כרבא:",1,0],[16,4,"וכן אם חשב על חצי זית וכו'. שם מימרא דרב אשי:",2,0],[16,5,"חשב על הדמים הניתנים למטה וכו' ועירב עמהם מחשבת הזמן ה\"ז פגול. ברייתא שם (כ\"ז).",1,0],[16,5,"ומ\"ש ואם חשב עמהם וכו'. ברייתא הנזכרת ופשוט הוא.",2,0],[16,5,"ומ\"ש לבדה לאו דוקא דה\"ה דאפי' עירב עם מחשבת המקום מחשבת הזמן אינו פגול כמו שנתבאר:",3,0],[16,6,"חשב על הדם הניתן למעלה וכו' עד הרי זה פסול ואינו פגול. שם:",1,0],[16,6,"כתב הראב\"ד חשב על הדם א\"א כדומה לי שיש כאן שבוש עכ\"ל. טעמו מדאמרינן התם בגמרא דטעמא מידי דהוה אמחשבת הינוח ופירש\"י ור' יהודה היא דפסל ליה, ורבינו פסק דלא כר' יהודה ונמצא סותר מ\"ש פה ולכן כתב שיש כאן שיבוש. וי\"ל שרבינו אינו מפרש כפירוש רש\"י אלא לפי שהקשה א\"ה איפסולי נמי לא ליפסול אהדר ליה דכי היכי דאשכחן לר' יהודה במחשבת הינוח דאע\"ג דלא הוי פגול מיפסיל ה\"נ לרבנן דחשב על הדם הניתן וכו' אע\"פ שאינו פגול מיפסיל.",2,0],[16,6,"ומ\"ש ומאחר שביארנו וכו' למה לא יהיה פגול במחשבה זו וכו' עד הרי זה פסול ואינו פגול. שם בדף הנזכר:",3,0],[16,7,"חשב מחשבת זמן בשעת קמיצה וכו' אינה פגול עד שיחשב מחשבת הזמן בכל המתיר. משנה בפ\"ב דמנחות (דף ט\"ז) פלוגתא דת\"ק ור\"מ ופסק כת\"ק. ומה שכתוב בדברי רבינו או בשעת זריקתן ט\"ס הוא וצריך למוחקו ולכתוב במקומו או בשעת הקטרתן:",1,0],[16,8,"חשב בשעת הקטרת הקומץ וכו'. פלוגתא דאמוראי בספ\"ב דמנחות (דף י\"ז) ופסק כמ\"ד דאין הקטרה מפגלת הקטרה משום דרב וכמה אמוראי סברי הכי.",1,0],[16,8,"ומ\"ש וכן אם הקטיר הלבונה לבדה או הקומץ לבדו וכו'. כבר נתבאר בסמוך דהלכה כת\"ק דאמר אין מפגלין בחצי מתיר.",2,0],[16,8,"ומ\"ש אבל אם הקטיר הקומץ לבדו וחשב שיקטיר לבונה למחר ואח\"כ הקטיר הלבונה וחשב שיאכל השירים למחר הרי זה פגול וכו'. שם הקטיר קומץ להקטיר לבונה ולבונה לאכול שירים למחר פיגול מאי קמ\"ל אי הקטרה מפגלת הקטרה קמ\"ל לימא הקטיר קומץ להקטיר לבונה אי מפגלין בחצי מתיר קמ\"ל לימא הקטיר קומץ (להקטיר לבונה) ולאכול שירים למחר אי תרוייהו קמ\"ל לימא הקטיר קומץ להקטיר לבונה ולאכול שירים למחר אמר רב אדא בר אהבה לעולם קסבר אין הקטרה מפגלת הקטרה ואין מפגלין בחצי מתיר ושאני הכא דפשטא לה מחשבה בכולה מנחה. ופירש\"י מאי קמ\"ל קס\"ד דמשום חדא מהנך מחשבות מיפגלא וחד מינייהו אשמעינן ופיגול משום מחשבה להקטיר לבונה למחר הוא ולא משום לאכול שירים דאין מפגלין בחצי מתיר, לימא הקטיר קומץ להקטיר לבונה ולא לימא לאכול שירים כיון דההיא מחשבה לא מהניא למה לי מחשבה בהדי קמייתא ואי פגול משום לאכול שירים הוא דמפגלין בחצי מתיר אבל להקטיר לבונה לא מהניא למה לי לצרפה בהדה. ואי תרווייהו קמ\"ל ואי לאכול קאמר שלא חישב באחד מהן לימא להקטיר לבונה ולאכול שירים דמשמע תרתי מילי וכו'. דפשטה לה מחשבה לכולה מנחה ואע\"ג דלא מיפגיל בחדא מינייהו השתא דחשיב בתרווייהו מיפגלא:",3,0],[16,9,"הקטיר כדי שומשום מן הקומץ וכו'. שם (דף ט\"ז:) הקטיר שומשום לאכול שומשום עד שכלה קומץ כולו רב חסדא ורב המנונא ורב ששת חד אמר פגול וחד אמר פסול וחד אמר כשר, ורבינו לא פסק כמ\"ד כשר משום דהוי ספיקא ולחומרא ולא פסק כמ\"ד פגול וחייב כרת משום דספק עונשים להקל. ועי\"ל דטעמיה משום דמ\"ד כשר ה\"ל חד לגבי תרי דפסלי ומ\"ד דחייב כרת הו\"ל חד לגבי תרי דפטרי ליה:",1,0],[16,10,"מנחת חוטא וכו'. ברייתא פרק כל המנחות (מנחות דף כ\"ט):",1,0],[16,11,"שירים שחסרו בין קמיצה להקטרה וכו'. בסוף פרק א' דמנחות (דף י\"ב) בעיא דלא איפשיטא:",1,0],[17,1,"כל הדמים הניתנים וכו' עד היא העיקר. משנה בר״פ ב״ש (זבחים דף ל״ו:).",1,0],[17,1,"ומ\"ש אבל כל הדמים הניתנים על מזבח הפנימי וכו'. שם במשנה כל הניתנים על מזבח הפנימי אם חיסר אחת מהמתנות לא כיפר לפיכך אם נתנן כולן כתקנן ואחת שלא כתקנה פסול ואין בו כרת. ופירש\"י לפיכך הואיל וכולן מתירות אין זו מתרת בלא זו ואין מפגלת בל\"ז אם נתנם כולם בשתיקה ואחת שלא כתקנה כגון שנתנה במחשבת חוץ למקומו או חוץ לזמנו פסול שלא כיפר בראשונות ואין בו כרת שאין האחרונה מפגלתו שאין מפגלין בחצי מתיר:",2,0],[17,3,"טבילת אצבע וכו'. בפרק קמא דזבחים (דף י\"ג):",1,0],[17,4,"היה עומד בעזרה וכו' עד שהרי חשב בחוץ בדבר הנעשה בחוץ. בפ״ב דמנחות (דף י״ד) ואיתיה נמי בפרק ב״ש (זבחים דף מ״ג):",1,0],[17,7,"התודה מפגלת את הלחם וכו' עד והכבשים אינם פגול. משנה בפרק שני דמנחות (דף ט\"ו):",1,0],[17,8,"ומ\"ש חשב באחת מארבע עבודות וכו'. שם ע\"א בעא מיניה ר\"א מרב השוחט את התודה לאכול למחר כזית ממנה ומלחמה מהו. ופירש רש\"י ממנה ומלחמה כחצי זית מזה וכחצי זית מזה. לאיפגולי תודה לא מיבעיא לי השתא כולו מלחמה לא מיפגלא ממנה ומלחמה מיבעיא כי קא מיבעיא לי לאיפגולי לחם מי מצרף תודה לאיפגולי לחם או לא א\"ל אף בזו הלחם מפוגל והתודה אינה מפוגלת וכו' ואיכא דמתני לה אכבשים בעא מיניה השוחט את הכבשים לאכול למחר כזית מהם ומלחמה מהו וכו' מי מצטרפי כבשים לאיפגולי לחם או לא אמר ליה אף בזו הלחם מפוגל והכבשים אינם מפוגלים וכו' מאן דמתני לה אתודה כ\"ש אכבשים ומאן דמתני לה אכבשים כבשים הוא דהוזקקו זה לזה לתנופה אבל תודה דלא הוזקקה זה לזה לתנופה לא. ופירש\"י אבל תודה לא פשיטא ליה דליפגול לחם. ופסק כלישנא דתודה פשט ליה וכ\"ש לכבשים ואע\"ג דלישנא קמא הוא משום דכיון דאיכא תרי לישני ה\"ל ספיקא ולחומרא. והר\"י קורקוס ז\"ל כתב טעם אחר דלא שבקינן מאי דפשיטא להאי לישנא למנקט ספיקא דאידך לישנא:",1,0],[17,9,"המקטיר שני בזיכי לבונה וכו'. מתבאר ממה שיבא:",1,0],[17,11,"השוחט שני כבשי עצרת וכו' עד שני הסדרים פיגול. משנה בפ\"ב דמנחות (דף י\"ג:) פלוגתא דתנאי ופסק כחכמים:",1,0],[17,12,"וכן אם חשב מחשבת הזמן וכו'. שם (דף י\"ד:) בעיא דר\"י ופשטוה מברייתא:",1,0],[17,13,"אבל אם נטמאת אחת משתי החלות וכו'. גם זה שם במשנה פלוגתא דתנאי ופסק כחכמים.",1,0],[17,13,"ומ\"ש בין לפני זריקה בין לאחר זריקה. שם א\"ר אלעזר מחלוקת לפני זריקה אבל לאחר זריקה דברי הכל וכו' והטהור יאכל:",2,0],[17,14,"חשב בעבודת אחד משני הכבשים וכו'. ג\"ז שם במשנה פלוגתא דתנאי ופסק כחכמים:",1,0],[17,15,"שחט אחד וחשב לאכול כחצי זית מחלה זו למחר ושחט השני וחשב לאכול חצי זית מחלה שנייה למחר הרי אלו מצטרפין לפגול. כ\"ה הגירסא הנכונה והדין בפ\"ב דמנחות (דף י\"ד) פלוגתא דרבי ורבנן ופסק כחכמים.",1,0],[17,15,"ומ\"ש וה\"ה בשני הבזיכים עם שני הסדרים. נלמד מהדין שכתב בסמוך:",2,0],[17,16,"חשב באחד משני הכבשים וכו'. משנה בפרק ב' דמנחות (דף ט\"ז):",1,0],[17,17,"ומ\"ש שחט אחד מהם וחשב בשעת שחיטתו שיאכל מבשר השני למחר וכו'. גם זה שם במשנה ולשונה שיאכל מחבירו למחר ובעי ר' אבא זוטי (דף ט\"ו) מחבירו כבש חבירו משמע ולא מיפגיל או דילמא לחם משמע ומפגיל ליה ואתינן למפשטה ממתניתין ודחי דילמא דפריש ואמר מחבירו כבש ולכך כתב רבינו מבשר דליכא לספוקי בלחם. ויש לתמוה למה השמיט רבינו דין האומר מחבירו:",1,0],[17,18,"שני כבשי עצרת אין מקדשין את הלחם אלא בשחיטה וכו' שחטו לשמן וכו' הלחם קדוש ואינו קדוש. כך היא הגירסא הנכונה בלשון רבינו והוא בפרק התכלת (מנחות דף מ״ז) פלוגתא דתנאי ופסק כרבי מחבירו. ועוד ששם העמידו דר״ע ור״א כרבי ס״ל והא דתניא קדוש ואינו קדוש מפרש רבא דהיינו לומר קדוש ואינו ניתר לכהנים:",1,0],[17,19,"שתי הלחם שיצאו בין שחיטה לזריקה וכו'. שם פלוגתא דתנאי ופסק כר\"ע. וכתב רבינו אע\"פ שהם בחוץ בגמרא מתקיף לה ר\"פ ממאי דכי איתנהו אבראי פליגי דילמא בדאיתנהו אבראי כ\"ע לא פליגי דאין זריקה מועלת ליוצא ובהדר עיילינהו פליגי. ומה שרצו להכריח מדרב גידל שאמרו ולאו איתותב רב גידל אעפ\"כ תפס רבינו דבדרך דחייה אמר כן ר\"פ אי נמי דגריס רבינו ולאו איתותב רב גידל בניחותא כמו שכתבו התוספות:",1,0],[17,20,"כבשי עצרת ששחטן לשמן וכו'. שם (דף מ\"ה) א\"ר יוחנן הכל מודים שאם הוזקקו זה לזה שמעכבין זה את זה ואיזהו זיקה שלהן שחיטה. ופירש\"י שאם הוזקקו זה לזה שהיו ביחד ואח\"כ אבד לחם או כבשים שמעכבים זה לזה והנותר לפנינו יצא לבית השריפה דנדחה באבוד חבירו.",1,0],[17,20,"ומ\"ש זרק דמן במחשבת הזמן אחר שאבד הלחם הרי אלו ספק אם הותרו באכילה או לא. שם (דף מ\"ז:) בעא מיניה ר' ירמיה מר' זירא כבשי עצרת ששחטן לשמן ואבד הלחם מהו שיזרקו דמן לשמן להתיר בשר באכילה א\"ל יש דבר שאינו כשר לשמו וכשר שלא לשמו ולא והרי פסח וכו' והרי תודה שאני תודה דרחמנא קרייה שלמים. ופירש\"י מהו שיזרוק דמן שלא לשמן אלא לשם שלמים להתיר בשר באכילה דודאי לשמן לא הוו כדאמרינן לעיל הכל מודים שאם הוזקקו זה לזה מעכבין זה את זה עכ\"ל. ומשמע דכיון דלא אשכחן מידי ה\"ל לתפוס בתמיהתו של ר' זירא ולומר דפסול ולפיכך יש לתמוה על רבינו שפסק דהוי ספק. וכתב הר\"י קורקוס ז\"ל שסובר רבינו דכיון דלא בדרך פשיטות אתמר בעיין לא איפשיטא. ודע שמ\"ש בספרי רבינו וזרק דמן במחשבת הזמן ט\"ס הוא וצריך להגיה וזרק דמן שלא לשמן. ומוכרח הוא דאי כגירסת הספרים אטו מחשבת הזמן גורמת היתר אכילה. והנגיד רבינו יהושע מבני בניו של רבינו ביאר הלכה זו בתשובה וז\"ל כששחטן לשמן וזרק דמן לשמן אחר אבד הלחם היו שני הכבשים פסולים להעדר הלחם לפי שהלחם מעכב את הכבשים כמו שנתבאר בפ\"ח וכשאבד הלחם נפסלו הכבשים וכשאבד הלחם תחלה הנה אין לשחיטת כבשי עצרת תכלית כלל וכאילו שחט חולין ולכן אם שחטן קודם שיאבד הלחם וזרק דמן במחשבת הזמן אחר אבידת הלחם היה זה אצל החכמים ספק אם הם חולין לגמרי ויותרו לפי שנזרק דמן אחר שאבד הלחם ואין כאן פגול או מאחר ששחטן קודם שיאבד הלחם לא יותרו באכילה ולכן היה ספק עכ\"ל:",2,0],[18,1,"כל המחשב מחשבה שאינה נכונה בקדשי' וכו'. בסוף פ\"ב דזבחים [דף כ\"ט]:",1,0],[18,2,"ומ\"ש ואעפ\"כ אינו לוקה אין המחשב' מעשה. פשוט הוא ומבואר סוף פרק ב' דזבחים:",1,0],[18,4,"כל קרבן שנאמר שהוא פסול וכו' עד הרי הם בכלל כל תועבה. בספרי פרשת ראה:",1,0],[18,5,"ומ\"ש עד שיולד להם מום אחר. כחכמים בפ\"ה דבכורות (דף ל\"ד):",1,0],[18,6,"כל קרבן שנתפגל במחשבת הזמן וכו'. משנה בריש כריתות.",1,0],[18,6,"ומ\"ש שנאמר והנפש האוכלת ממנו עונה תשא. שם בגמרא:",2,0],[18,8,"אין חייבין כרת אלא על אכילת דברים שהותרו וכו' עד והקטורת והדם. בפרק ב״ש (זבחים דף מ״ג) משנה.",1,0],[18,8,"ומה שכתב והיין בין יין הבא עם הנסכים בין יין הבא בפני עצמו. שם במשנה גבי אלו דברים שאין חייבין עליהם משום פגול תני והנסכים הבאים בפנ\"ע דברי ר\"מ וחכ\"א אף הבאים עם הבהמה ופסק כחכמים.",2,0],[18,8,"ומ\"ש ולוג שמן של מצורע. שם במשנה ר\"ש אומר אין חייבין עליו משום פיגול ור\"מ אומר חייב עליו משום פיגול שדם האשם מתירו ופסק כר\"ש דמיקל דלית לן לחיובי מספיקא ועוד דמסתבר טעמיה כמו שביאר רבינו בסמוך.",3,0],[18,8,"ומ\"ש וא\"ת והלא דם האשם מתירו אינו תלוי בו וכו'. בפ\"ב דמנחות (דף ט\"ו):",4,0],[18,9,"אסור להותיר וכו' שנאמר בקרבן תודה לא תותירו ממנו עד בקר. בפרשת אמור ובתורת כהנים פרשת צו מרבה כל הקרבנות.",1,0],[18,9,"ומ״ש אינו לוקה שהרי הכתוב ניתקו לעשה שנאמר והנותר ממנו עד בקר וכו'. בקרבן פסח בס״פ אותו ואת בנו (חולין דף פ״ג) לא תותירו וכו' והנותר באש תשרופו בא הכתוב ליתן עשה אחר לא תעשה לומר שאין לוקין עליו דברי ר״י רבי יעקב אומר לא מן השם הוא זה אלא משום [דהוה ליה לאו שאין בו מעשה וכל] לאו שאין בו מעשה אין לוקין עליו. ויש לתמוה על רבינו מאחר דקי״ל דלאו שאין בו מעשה אין לוקין עליו אמאי שבק האי טעמא ונקט טעמא אחרינא, וי״ל דלרבותא נקט לומר דאפילו אם היה לאו שיש בו מעשה לא היו לוקין עליו:",2,0],[18,10,"האוכל כזית מבשר קדשים וכו'. משנה בריש כריתות.",1,0],[18,10,"ומה שכתב שנאמר ואוכליו עונו ישא. שם (דף ה') בגמ' יליף לה בג\"ש נאמר כאן ואוכליו עונו ישא ונכרתה ולהלן הוא אומר והנפש האוכלת ממנו עונה תשא:",2,0],[18,10,"ומאימתי יתחייב כרת על אכילת הנותר וכו'. בפרק איזהו מקומן (זבחים דף נ״ז:) כר״י דת״כ ולאפוקי מחזקיה:",3,0],[18,10,"והיכן הזהיר הכתוב על הפגול ועל הנותר במלואים וכו'. פ' אלו הן הלוקין (מכות דף י״ח:):",4,0],[18,11,"ומ\"ש והפגול והנותר מצטרפים זה עם זה לכזית. בפ\"ד דמעילה (דף י\"ז.) במשנה הפגול והנותר אין מצטרפין (זה עם זה) ובגמרא אמר רב יהודה אמר שמואל ל\"ש אלא לטומאת ידים דמדרבנן היא אבל לענין אכילה מצטרפין דתניא ר\"א אומר לא יאכל כי קדש הם כל שבקדש פסול בא הכתוב ליתן לא תעשה על אכילתו.",1,0],[18,11,"ומ\"ש וכל הפגולין והנותרים מצטרפין. שם (דף ט\"ו) במשנה כל הפגולים מצטרפין זה עם זה כל הנותרים מצטרפין זה עם זה וכבר נתבאר בסמוך דלענין אכילה פגול ונותר מצטרפין זה עם זה:",2,0],[18,12,"אסור לטמא את הקדשים או לסבב להם טומאה. בפרק ג' דזבחים (דף ל״ג:) ובפ' אלו הן הלוקין (מכות דף י״ד) נחלקו רבי יוחנן ור״ל במטמא קדשים ר״ל אמר לוקה ור' יוחנן אמר אינו לוקה ומשמע דאיסורא מיהא איכא:",1,0],[18,12,"אבל אדם טהור שאכל כזית מקדשים שנטמאו לוקה. בפרק כל שעה (פסחים דף כ״ד:) והבשר כל טהור יאכל בשר למה לי לרבות אימורים, ופירש״י אימורים שנטמאו ואכלן הטהור ומקשי אימורים מהתם נפקא דתניא והנפש אשר תאכל בשר מזבח השלמים אשר לה' לרבות את האימורים התם טומאת הגוף בכרת הכא טומאת בשר בלאו, ולפ״ז הא דתנן בפרק השוחט ומעלה טהור שאכל טמא פטור שאינו חייב אלא על טומאת הגוף לענין כרת קאמר אבל מילקא לקי גם על טומאת בשר. ובפרק כל הפסולים (זבחים דף ל״ד) אתמר טמא שאכל בשר קדש לפני זריקה ר״ל אמר לוקה רבי יוחנן אמר אינו לוקה וכו' אמר אביי [מחלוקת] בטומאת הגוף אבל בטומאת בשר [ד״ה] לוקה וכו' ורבא אמר אבל בטומאת בשר ד״ה אינו לוקה וידוע דהלכה כרבא. ולפיכך צ״ל שמ״ש כאן רבינו שטהור שאכל כזית מקדשים שנטמאו לוקה באוכל אחר זריקה:",2,0],[18,12,"וה\"ה לשאר הקרבנות. כלומר דבשר לאו דוקא דה\"ה ללבונה וכדתנן בספ\"ג דמעילה (דף י\"ג) ובספ\"ד דזבחים (מ\"ו:) מרבה לה מוהבשר:",3,0],[18,12,"אחד קדשים שנטמאו לפני כפרה וכו': ואינו לוקה אלא האוכל אחר זריקת דמים וכו'. פלוגתא דר' יוחנן ור״ל בפ' כל הפסולין (זבחים דף ל״ד) ופסק כר' יוחנן:",4,0],[18,13,"כל אדם שנטמא וכו'. בר״פ השוחט ומעלה (דף ק״ו) תנן הטמא שאכל בין קדש טמא בין קדש טהור חייב. ומה שהתנה שצריך שיהא חייב על ביאת המקדש אפשר שהטעם מדמקיש קדש למקדש כדאיתא בפרק כל הפסולים (זבחים דף ל״ג:).",1,0],[18,13,"ומ\"ש במזיד הרי זה נתחייב כרת וכו' ואם אכל בשגגה מביא קרבן עולה ויורד. משנה בריש כריתות ומפורש בתורה.",2,0],[18,13,"ומ״ש ומנין שאינו מדבר אלא בטומאת הגוף וכו'. בפ' ב״ש (נזיר דף ל״ג:) מייתי לה מקראי אחריני ורבי מייתי לה מהאי קרא ומשמע לרבינו דמהאי קרא משתמע טפי:",3,0],[18,13,"והיכן הזהיר על עון זה ביולדת וכו'. בפרק כל הפסולין (זבחים דף ל״ג:) ובפרק אלו הן הלוקין (מכות דף י״ד) אמר ר״ל הכי ואע״ג דר״י פליג ויליף לה מקרא אחרינא כתב רבינו כר״ל משום דתניא כוותיה:",4,0],[18,14,"והאוכל קדש אחר שטבל וכו'. בפי\"א דמס' פרה תנן גבי טעון ביאת מים מן התורה אם בא אל המקדש בין לפני ביאתו בין לאחר ביאתו חייב ומשמע דה\"ה לאוכל קדש ומשמע לרבינו דהיינו דוקא לענין מלקות אבל פטור מכרת מדכתיב וטומאתו עליו ונכרתה דמשמע דלא מיחייב כרת אלא בזמן שכל טומאתו עליו:",1,0],[18,14,"וכתב הראב\"ד לוקה ואינו חייב [כרת] א\"א זה שיבוש שכבר כתבנו למעלה שהוא בכרת עכ\"ל. וכבר כתבתי בזה בפ\"ג מהלכות ביאת המקדש:",2,0],[18,15,"היה טמא בטומאת וכו'. פשוט הוא ואיתיה במשנה פי\"א ממסכת פרה:",1,0],[18,16,"אינו חייב כרת וכו'. משנה בפ\"ב דמעילה (דף י').",1,0],[18,16,"ומ״ש אבל אם אכל את הבשר קודם זריקת הדם אינו לוקה וכו'. בפרק כל הפסולים (זבחים דף ל״ג:) פלוגתא דר״י ור״ל ופסק כר״י.",2,0],[18,16,"ומ\"ש זה הכלל כל שיש לו מתירים אין חייבין עליו וכו' עד חייבים עליו משום טומאה. משנה בפ\"ב דמעילה (דף י').",3,0],[18,16,"ומ\"ש אפי' נטמא הבשר קודם שיטמא האוכל וכו'. בפרק השוחט ומעלה (דף ק\"ח) פלוגתא דר\"י הגלילי ורבנן ופסק כרבנן.",4,0],[18,16,"ומ״ש וכן אם אכל מבשר חטאות הנשרפות והוא טמא וכו'. משנה פ״ב דמעילה (דף ט') פרים [הנשרפים] ושעירים הנשרפים מועלים בהם משהוקדשו וכו' הוזה דמן חייבין עליהן משום פגול נותר וטמא ומייתי לה בפ' כל הפסולים (זבחים דף ל״ה:):",5,0],[18,17,"כבר נתבאר לך שאף דברים וכו'. משנה בפ' ב״ש (זבחים דף מ״ה:) דברים שאין חייבים עליהם משום פגול חייבין עליהם משום נותר ומשום טמא חוץ מן הדם ובגמרא יליף לה מקראי:",1,0],[18,19,"טמא שאכל אימורים חייב כרת אכל פסח שלא נצלה וכו'. בספ\"ג דזבחים (דף ל\"ז:) אמר רב חסדא מרגלא בפומיה דרב דימא בר חיננא בשר פסח שלא הוצלה ולחמי תודה שלא הורמה חייבין עליהם משום טומאה אמר רבא תדע דתניא אשר לה' לרבות אימורי קדשים קלים לטומאה אלמא אע\"ג דלאו בני אכילה נינהו חייבין עליהם משום טומאה ה\"נ אע\"ג דלאו בני אכילה נינהו חייבין עליהם משום טומאה ולא היא התם אימורי קדשים קלים חזו לגבוה לאפוקי בשר פסח שלא הוצלה ולחמי תודה שלא הורמה דלא חזו לא לגבוה ולא להדיוט, לישנא אחרינא אימורים לא חזו ולא היא הנך חזו למילתייהו הני לא חזו כלל, דמשמע לכאורה דכיון דאסיקנא ולא היא אידחייא לה מהלכתא ויש לתמוה על רבינו שפסקה. וצ\"ל שרבינו סובר דלא אמרינן ולא היא אלא לדחויי ראייה דבעא רבא לאתויי מאימורי קדשים קלים אבל עיקר דינא דאמר רב חסדא דמרגלא בפומיה דרב דימא בר חיננא לא אידחי ועוד דרבא הכי סבר ותיבת אבל שכתב רבינו לעיל קאי שכתב אינו חייב כרת על קדש שיש לו מתירים עד שיאכל ממנו אחר שקרבו מתיריו ולפ\"ז הוה ס\"ד דה\"ה לפסח שלא נצלה ולחמי תודה שלא הורמה חלתן מאחר שאינם ראויין כמות שהן הם דומים לאוכל קדש קודם שיקרבו מתיריו ולא ליחייב כרת עלייהו קמ\"ל:",1,0],[18,19,"אי אפשר שיתחייב אדם על וכו'. בפ\"ג דכריתות (דף י\"ד) אהא דתנן יש אוכל אכילה אחת וחייב עליה ד' חטאות פריך וניתני חמש חטאות ונוקמה כגון [דאכל] כזית פגול בחדא בהמה קמיירי בשתי בהמות לא קמיירי ונותר ופגול בחדא בהמה לא משכחת לה. ופירש\"י ונותר ופגול בחדא בהמה ליכא דפגול אינו אלא בארבע עבודות של דם הילכך מדפגלה לא חזיא לא לאכילת אדם ולא לאכילת מזבח הילכך לא חייל עלה נותר. ודע דבתר הכי פריך אלמה לא משכחת לה כגון שהעלה אבר פגול לגבי מזבח דפקע פגוליה מינה וה\"ל נותר וכדאמר עולא קומץ פגול שהעלה לגבי מזבח פקע פגולו ממנו וה\"ל נותר באבר אחד קא מיירי בשני איברים לא קא מיירי, ומשמע לי דה\"פ דההוא אבר פגול שהעלהו ע\"ג המזבח דפקע פיגוליה מיניה וה\"ל נותר תו לא מיחייב עליה משום פגול ואי בעית לחיובי על אכילה אחת משום פגול ומשום נותר צריך לאוקומי בשאכל חצי אכילה מאבר פגול זה שהעלהו ע\"ג המזבח וחצי אכילה משאר איברי בהמה הפגולה שלא העלם ע\"ג המזבח ובשני איברים לא קא מיירי מתני'. ויש לתמוה עליו שסתם דבריו ולא פירש דה\"מ באבר אחד אבל בשני איברים משכחת לה וצ\"ל דנקט לישנא דמתני' לבד:",2,0],[18,20,"הפגול והנותר והטמא וכו'. בפ' התערובת (זבחים דף ע״ח) פלוגתא דר״פ ור״א ופסק כר' אלעזר משום דרבא אותביה לר״פ ושני ליה בשינויי דחיקי. עוד דבירושלמי פ״ק דחלה איפלגו ר״י ור״ל במילתא ור״י סבר כר״א:",1,0],[18,21,"ופגול או נותר או טמא וכו'. בפרק ב״ש (זבחים דף מ״ג) מימרא דר״י ופריש לה ר' זירא:",1,0],[18,21,"ואימורים מצטרפים וכו'. ברייתא וגמ' דזבחים (דף ק\"ט):",2,0],[18,22,"זבח שנתפגל וכו'. משנה בפ\"ג דזבחים (דף ל\"ה).",1,0],[18,22,"ומ\"ש מן הצפרנים מן החרטום ומן הנוצה. נתבאר בפרק י\"ד:",2,0],[18,23,"אכל מן השליל או מן השליא וכו'. שם מימרא דר\"א:",1,0],[18,23,"כתב הראב\"ד א\"א דוקא בשפיגל הזבח וכו'. וכך מבואר שם בגמ' ואע\"פ שגם רבינו לא איירי אלא בשפיגל הזבח וכן מבואר בדבריו בפי\"ד מפני שכתב רבינו כאוכל משאר בשר הזבח נזהר הראב\"ד שלא נטעה לומר שדינן לגמרי כשאר בשר הזבח וכתב אבל במחשבת עצמן לא:",2,0],[18,24,"קדשי עכו״ם אין חייבים עליהם משום פגול ולא משום נותר וכו'. משנה בפ' ב״ש (זבחים דף מ״ה) פלוגתא דר״ש ור' יוסי ופסק כר״ש וצריך טעם למה. ואפשר שטעמו מדגרסינן בריש תמורה (דף ב':) דבעי רמי בר חמא עכו״ם מהו שימיר ולא אפשר לאוקומי הבעיא לר' יוסי וכמו שכתבו התוס' שם בתירוץ שני וכיון דרמי בר חמא בעי אליבא דר״ש אלמא הלכתא כוותיה ועוד דגמ' מפרש טעמיה בסתם. ויש מי שאומר שרבינו מפרש דמתני' דקתני דברי רבי שמעון ורבי יוסי מחייב לא קאי אלא אשוחטן בחוץ דסמיך ליה לא לאין חייבין עליהם משום פגול נותר וטמא דלעיל מיניה דההוא סתם מתני' היא:",1,0],[18,24,"וכן הלבונה והקטרת והעצים וכו'. משנה בפ' ב״ש (זבחים דף מ״ה:) דברים שאין חייבין עליהם משום פגול חייבין עליהם משום נותר וטמא חוץ מן הדם ר״ש מחייב בדבר שדרכו לאכול אבל כגון העצים והלבונה והקטרת אין חייבין עליהם משום טומאה, ופסק רבינו כר״ש ולא ידעתי למה וכבר השיגו הראב״ד וכתב לא משום פגול א״א זה לדעת ר״ש אבל לרבנן חייבים עליהם כרת עכ״ל. ועוד יש לתמוה דר״ש נמי לא פליג אלא בטומאה ולא בנותר וא״כ למה כתב רבינו שאין חייבין עליהם משום נותר וטמא י״ל דמשמע ליה דנותר וטמא בחדא שייטא שייטי וילפי מהדדי. ועוד יש לתמוה על",2,0],[18,24,"מ\"ש ולא משום טומאת הגוף דמשמע אבל משום טומאת עצמן חייבין בגמ' (דף מ\"ו:) איפליגו אמוראי חד אמר מחלוקת בטומאת בשר אבל בטומאת הגוף דברי הכל אינו לוקה וחד אמר מחלוקת בטומאת הגוף אבל בטומאת בשר ד\"ה לוקה וח\"א כמחלוקת בזו כך מחלוקת בזו אמר רבא מסתברא כמ\"ד כמחלוקת בזו כך מחלוקת בזו מ\"ט כיון דלא קרינן ביה וטומאתו עליו ונכרתה לא קרינן ביה והבשר אשר יגע בכל טמא והאמר מר והבשר לרבות עצים ולבונה ההוא לפיסולא בעלמא ופירש\"י מעלה דרבנן היא וקרא אסמכתא בעלמא, והשתא ה\"ל לרבינו למיפסק כרבא דבתרא הוא, ואפשר לדחוק ולומר דלא פסק כרבא משום דמשמע ליה דדרשא דוהבשר לרבות עצים ולבונה דרשא גמורה היא מדאורייתא ולא כרבא דאמר דאסמכתא בעלמא היא והשתא אע\"ג דלמ\"ד מחלוקת בטומאת הגוף אבל בטומאת בשר ד\"ה לוקה פסק כר\"ש למ\"ד מחלוקת בטומאת בשר אבל בטומאת הגוף ד\"ה אינו לוקה פסק בטומאת הגוף כדברי הכל ובטומאת בשר כת\"ק. אבל קשה דבנותר משמע שפסק כר\"ש כמ\"ש ואפשר לומר דלא איפליגו ת\"ק ור\"ש אלא לענין מלקות אבל לכ\"ע אין חייבין כרת ומדכתב רבינו אין חייבין עליהם כרת משמע אבל מלקות חייבין והיינו כת\"ק:",3,0],[19,1,"מצות עשה לשרוף כל הקדשים שנטמאו וכו': וכל פסולי המוקדשין הכל נשרפין. משנה בסוף תמורה (דף ל״ג:) ואיתיה בפ' כל שעה (פסחים דף ל״ד.) ואמרינן בפ' כיצד צולין (דף כ״ב:) דגמרא גמירי לה:",1,0],[19,2,"קרבן שנתפגל או וכו'. בפ' כל שעה ובפ' כיצד צולין (פסחים דף פ״ב) תנן הפסח שיצא או שנטמא ישרף מיד נטמאו הבעלים או שמתו תעובר צורתו וישרף בי״ו ותנן תו התם (דף פ״א:) נטמא שלם או רובו שורפין אותו לפני הבירה מעצי המערכה נטמא מיעוטו והנותר שורפין אותו בחצרותיהם ועל גגותיהם מעצי עצמם וכתבו רבינו בפ״ד מהל' קרבן פסח:",1,0],[19,3,"פרים ושעירים הנשרפים וכו'. בס״פ טבול יום (זבחים דף ק״ה:) בעיא דלא איפשיטא:",1,0],[19,3,"כתב הר\"י קורקוס ז\"ל יש לתמוה על רבינו שכתב ספק זה שהרי לא נסתפקו בגמ' אלא לדעת ר\"ל שאמר פרק כל התדיר עדיין לא הגיע זמנו לצאת אבל לר\"י שסובר שבשר כיון שסופו לצאת ליכא לספוקי מידי מכ\"ש כאן שחייב להוציאו וכמו שהקשו מאי קא מבעיא ליה ותירצו דלא מיבעיא אלא לר\"ל וכיון דרבינו פ\"א פסק כר\"י אין עוד ספק ואיך כתב רבינו שהוא ספק. ונראה שסובר רבינו שמ\"ש שם כן הוא קודם שידענו שאין זריקה מועלת לאכלו אבל אחר שהעלינו במעילה שאין זריקה מועלת לאכלו אלא לשרפו כיון שיצא פסול באכילה כיון שעדיין לא הגיע זמנו, ואפשר שמ\"ש אליבא דמ\"ד וכו' הכוונה לומר שמפני אותו טעם נסתפקו כאן ולכך לא אמרו אליבא דר\"ל קא מיבעיא ליה והשתא ניחא דבעי אליבא דהלכתא דודאי כיון שהדבר ברור שאין הלכה כר\"ל לגבי ר\"י לא ה\"ל לשאול סתם מהו אלא ודאי גם לר\"י שייכא בעיין עכ\"ל:",2,0],[19,3,"וכן אם יצא חצי הבהמה ברוב האבר וכו' וכן אם נשאום ה' להוציאן ויצאו ג' וכו'. גם זה שם בעיא דלא איפשיטא:",3,0],[19,3,"כתב הראב\"ד לפיכך נפסלו מספק א\"א לא היתה אותה בעיא וכו'. ואני אומר אע\"פ שאותה בעיא היתה סתמית בעי רבי אליעזר פרים ושעירים הנשרפים [שיצא רובן במיעוט אבר] יש לפרש לענין פיסול יוצא כדברי רבינו ועוד דלעיל בסמוך מייתי גמרא בעי רבי אליעזר יציאה (קודם זריקת דמים) מהו שתועיל בפרים ושעירים הנשרפים ואיכא למימר מדהך בעיא לענין פיסול יוצא האי בעיא נמי לענין פיסול יוצא.",4,0],[19,3,"ועל מ\"ש רבינו וכן אם נשאום כתב א\"א אף זו לענין טומאת בגדים וכו'. טעמו מדאמרינן בתר רוב מתעסקין אזלינן או בתר רוב בהמה ומדנקט רוב מתעסקים משמע ליה דלענין טומאת המתעסקים הוא ועוד דאמרינן התם בסמוך בעי ר\"א פרים ושעירים הנשרפים שיצאו וחזרו מהו מי אמרינן כיון דנפקי איטמו להו או דילמא כיון דהדור הדור ומדבעיא זו לענין טומאה קמייתא נמי לענין טומאה ונראה שלפיכך כתב ומי שיש לו לב יבין זאת. ולדברי רבינו י\"ל דההיא דרוב מתעסקין לא מכרעא דתהוי לענין טומאה ולא לענין פיסול יוצא וכן בעיא דבסמוך לא מכרעא ואע\"פ שפירש\"י כדברי הראב\"ד כבר הקשו עליו התוס' והעלו כפירוש רבינו וגם רש\"י גבי בעיא דיצא חצי כתב דלענין אם נטמא אח\"כ שישרף בפנים קא מיבעיא ליה. כתב הר\"י קורקוס ז\"ל כתב רבינו שא\"צ באלו עיבור צורה אלא מפני שמא הוא שורף קדשים שאין ראויים לשריפה ומשום ביזוי קדשים נגעו בה אבל אלו שממה נפשך נשרפין הם ומתחלתם דינם לשריפה לענין שינוי מקום אין צורך לעבור צורה ואין כאן ביזוי הקדשים עכ\"ל:",5,0],[19,5,"בשר הנמצא בעזרה וכו'. בפ\"ז דשקלים וכתב רבינו בפירוש המשנה העולה כולה כליל ולפיכך אין חותכין אותם חתיכות ודי לעשותה איברים, וכתב דנ\"מ לאם עבר אדם ואכלו אם אכל מה שנמצא בירושלים אינו חייב כלום לפי שהוא שלמים ואם אכל כהן חתיכות הנמצאים בעזרה אינו חייב כלום:",1,0],[19,5,"וכתב הראב\"ד למי שעבר ואכל א\"א לספק מעילה עכ\"ל. נראה דהיינו לומר שאם הוא חטאת או שלמים אינו חייב עליהם קרבן מעילה שהרי הם מותרים לזרים ואם הוא עולה חייב קרבן מעילה. ומשמע מדקדוק דברי הראב\"ד לכאורה דאיברים שנמצאו בעזרה אע\"פ שהם בחזקת עולה אין חייבין עליהם קרבן מעילה ודאית אלא קרבן ספק מעילה אבל א\"א לומר כן משום דבפ' רביעי דכריתות (דף י\"ז) ת\"ק סבר דאין חייב על ספק מעילות אשם תלוי:",2,0],[19,5,"אין שורפין את הנותר אלא ביום וכו' אף על פי שהשלמים אסורים באכילה מתחלת ליל שלישי וכו'. בפרק איזהו מקומן (זבחים דף נ״ו:) ובריש פסחים (דף ג').",3,0],[19,5,"ומה שכתב וכן הפגול אינו נשרף אלא ביום. נראה שטעמו משום דפגול ונותר בחדא שייטא שייטי:",4,0],[19,5,"ואין שריפת טמא ונותר ופגול דוחה את יום טוב וכו'. משנה פרק כיצד צולין (פסחים דף פ\"ג) ואיתיה בגמרא דתמורה (דף ד') ובפרק במה מדליקין:",5,0],[19,5,"ומותר לשרוף טמא ונותר ופגול כאחד. ברייתא פירקא קמא דפסחים (דף ט\"ו:) וכבית הלל:",6,0],[19,6,"בשר קדשי קדשים שנטמא בפנים וכו' עד בולד הטומאה. פלוגתא דתנאי בפירקא בתרא דשקלים ופסק כר\"ע:",1,0],[19,6,"ומימיהם של כהנים וכו' ולא עוד אלא אפילו שמן שנפסל בטבול יום וכו'. משנה ובגמ' בפ\"ק דפסחים (דף י\"ד). ויש בלשון רבינו ט\"ס שחסר תיבה אחת והגירסא הנכונה שנטמא בולד הטומאה:",2,0],[19,7,"נותר של קדשים קלים שורפין אותו בעליו בבתיהם. משנה בפרק כיצד צולין (פסחים דף פ\"א:):",1,0],[19,8,"מי שיצא מירושלים וכו'. משנה בס״פ אלו עוברין (פסחים דף מ״ט).",1,0],[19,8,"ומ\"ש אם יש בו כזית וכו'. שם פלוגתא דתנאי ופסק כחכמים וכר' יהודה.",2,0],[19,8,"ומ״ש ואם הוא אורח וכו'. אוקימתא דגמ' בפ' כיצד צולין (פסחים דף פ״ב) ותשלום דינין אלו כתב רבינו בפ״ד מהלכות קרבן פסח:",3,0],[19,9,"כל עצמות הקדשים שאין בהם מוח וכו'. ברייתא פ' כיצד צולין (פסחים דף פ״ג) כל עצמות הקדשים אינם טעונין שריפה חוץ מעצמות הפסח מפני התקלה הני עצמות ה״ד אי לימא דלית בהו מוח עצמות הפסח למה להו שריפה אלא פשיטא דאית בהו מוח ואי ס״ד שימוש נותר מילתא היא עצמות קדשים אמאי אין טעונין שריפה א״ר נחמן בר יצחק הב״ע כגון שמצאן חלוצים עצמות קדשים דאין בהם משום שבירת עצם קמי דנהוו נותר חלצינהו ולא הוו שימוש נותר ולא בעי שריפה עצמות הפסח דיש בהם משום שבירת עצם לבתר דנהוי נותר הוא דחלצינהו וה״ל שימוש נותר ובעו שריפה. ופירש״י כל עצמות נותר מן הקדשים אינם טעונים שריפה אלא שוברם ומוציא המוח ושורפו ומשליך את העצמות חוץ מעצמות פסח שאינו יכול לשברן מפני תקלת עצם לא תשברו בו לפיכך נשרפים ע״י מוח שבהם וכו'. שמצאם חלוצים כולה מתניתין מיתוקמא במוצא עצמות חלוצין כלומר שבורין ונחלץ מוח מהם. עצמות קדשים דמותר לשברן אמרי סתמא דמילתא לא אתא מוח דידהו לידי נותר ומקמי איסורייהו דניתו לידי נותר חלצינהו ואין כאן שימוש נותר. לבתר הכי דאיפסיל חלצינהו דתו לית ביה איסור שבירה כר״ש ויש כאן שימוש נותר עכ״ל:",1,0],[19,9,"וכתב הראב\"ד אינם טעונים שריפה א\"א שמצאן חלוצים מפסולי קדושה עכ\"ל. ואם היתה כוונתו ללמדנו שיהיו חלוצים לא היה צריך לכך שהרי בביאור כתב רבינו שאין בהם מוח, ולכן נ\"ל שמפני שרבינו סתם וכתב כל עצמות הקדשים דמשמע בכל גוונא מיירי בא לבאר שאינו כן דלא מיירי אלא כשמצאן ואינו יודע מה טיבן ואנו אומרים באומד הדעת מאחר שהם חלוצים פסולי המוקדשין היו כלומר נותר ולפיכך מפגלין בין עצמות פסח לעצמות שאר קדשים וכמו שנתבאר. ועי\"ל משום דלישנא דשאין בהם מוח משמע אפילו שלא היה בהם מוח מעולם לכך כתב שמצאם חלוצים כלומר דוקא כשהיה בהם מוח ונחלץ ממנו אבל אם לא היה בהם מוח מעולם לא:",2,0],[19,9,"כבר ביארנו. בקרבנות ספ\"ה.",3,0],[19,9,"ומ״ש אבל אם נפסל קודם הפשט הרי העור כבשר וישרף הכל. משנה פרק טבול יום (זבחים דף ק״ג:):",4,0],[19,9,"וכן זבח שהופשט ונמצא טריפה. שם במשנה פלוגתא דתנאי ופסק כחכמים.",5,0],[19,9,"ומה שכתב או שנפסל במחשבת הזמן או במחשבת המקום וכו'. משנה שם (דף ק\"ג) כל שלא זכה המזבח בבשרה לא זכו כהנים בעורה. ופירש\"י כל שלא זכה המזבח בבשרה כגון שאירע בה פיסול קודם זריקה לא היתה בה שעת היתר למזבח.",6,0],[19,9,"ומה שכתב אבל אם נעשה במחשבת שינוי השם וכו'. גם זה משנה שם.",7,0],[19,9,"ומה שכתב וזבח שהופשט קודם זריקה אינו פוסל. שם פלוגתא דתנאי בברייתא ופסק כרבי פירוש אם הופשט קודם זריקה אין העור נפסל עוד אפילו נפסל בשר קודם זריקה זריקה מרצה על העור לבדו:",8,0],[19,10,"אלו הן הנשרפים כו'. משנה בסוף תמורה (דף ל\"ג) כל הקדשים שנשחטו חוץ לזמנן וחוץ למקומן הרי אלו ישרפו.",1,0],[19,10,"ומ״ש וכן המנחה שנטמא. משנה פ' היה נוטל (סוטה דף כ״ב ע״ב) ומשמע ליה דה״ה לנפסלה או נותרה.",2,0],[19,10,"ומ\"ש ואשם תלוי שנודע לו שלא חטא קודם שנזרק דמו. משנה בפרק בתרא דכריתות (דף כ\"ג:).",3,0],[19,10,"ומ\"ש וחטאת העוף הבאה על הספק. במשנה בסוף תמורה (דף ל\"ד) פלוגתא ופסק כת\"ק.",4,0],[19,10,"ומ\"ש ושער נזיר טהור. גם זה שם בגמרא.",5,0],[19,10,"ומ\"ש והערלה וכלאי הכרם ודבר שאין דרכו להשרף. שם במשנה:",6,0],[19,11,"ואלו הם הנקברים קדשים שמתו שם. במשנה וכת\"ק.",1,0],[19,11,"ומ\"ש וקדשים שהפילו נפל הפילו שליא וכו' עד שנשחטו בעזרה. ג\"ז שם במשנה וכת\"ק:",2,0],[19,12,"האורג מלא הסיט משער נזיר ומפטר חמור בשק ידלק. בערלה פ\"ג:",1,0],[19,13,"כל הנקברים אפרן אסור. בסוף תמורה (דף ל\"ד).",1,0],[19,13,"ומ\"ש וכל הנשרפין של הקדש אפרם מותר חוץ מדשן המזבח וכו'. שם דנשרפים אפרן מותר ומותיב עליה מדתניא כל הנשרפים אפרם מותר חוץ מאפר אשרה ואפר הקדש לעולם אסור ומשני כי תניא אפר הקדש אסור בתרומת הדשן דלעולם אסור דתניא ושמו בנחת ושמו כולו ושמו שלא יפזר. ופירש\"י ושמו כולו וכיון דטעון גניזה אסור בהנאה:",2,0],[19,13,"וכתב הראב\"ד חוץ מדשן המזבח א\"א הרמת הדשן עכ\"ל. נראה שטעמו לומר שלא אמרו אסור אלא דשן שהיה מרים כהן בכל יום ממזבח העולה כדכתיב והרים את הדשן אשר תאכל האש את העולה ושמו אצל המזבח וכדמפרש טעמא בגמרא וכדפירש\"י ודישון מזבח הפנימי ודישון המנורה אינם בכלל זה, ורבינו סובר דילפינן להו מדישון מזבח העולה. ועי\"ל דרבינו לטעמיה אזיל שהוא סובר דדשן שע\"ג המזבח אסור בהנאה וכמבואר בדבריו בסוף הפרק:",3,0],[19,14,"כל הנשרפין לא יקברו וכל הנקברין לא ישרפו וכו'. משנה בסוף תמורה שם:",1,0],[19,15,"היה מקריב עמו בזבחים וכו'. בפרק הניזקין (גיטין דף נ״ד:) ת״ר היה עושה עמו בטהרות א״ל טהרות שעשיתי עמך נתפגלו וכו' נאמן אבל א״ל טהרות שעשיתי עמך ביום פלוני נטמאו וזבחים שעשיתי עמך ביום פלוני נתפגלו אינו נאמן מ״ש רישא ומ״ש סיפא אמר אביי כל שבידו נאמן רבא אמר כגון דאשכחיה ולא אמר ליה ולא מידי ולבתר הכי אשכחיה וא״ל. ופירש״י כל שבידו לעשות בשעה שמודיעו נאמן ורישא כגון שעודן בידו לטמאן ולפגלן וגבי קרבנות בכהן העובד מיירי כגון שהודיעו בין שחיטה לזריקה ואמר פיגלתי בשחיטה שעדיין בידו לפגלן בשאר עבודות אבל ביום פלוני שכבר יצאו מידו לאו כל כמיניה. רבא אמר אע״פ שאין בידו נאמן וסיפא כגון דאשכחיה מקמי האידנא ולא א״ל והשתא א״ל. והרשב״א כתב שהראב״ד פירש דהא דאמר אביי כל שבידו נאמן היינו כל זמן שהוא תחת ידו ואם א״ל בשעה שהוא יוצא מתחת ידו [אינו] נאמן. ולענין דינא משמע דהלכה כרבא כדקי״ל בכל דוכתא. אבל הראב״ד פוסק כאביי משום דעובדי דמייתי התם דאתא קמי' דרב אמי משמע ליה דאתו כאביי ולפיכך כתב על דברי רבינו א״א כל שבידו נאמן עכ״ל. ולי קשה על רבינו דלא אתי לא כאביי ולא כרבא דאי כאביי ה״ל לפלוגי בין ישנן בידו לאינן בידו ואי כרבא ה״ל לפלוגי בין אשכחיה ולא אמר ליה ללא אשכחיה. ואפשר לומר דפסק כאביי דטעמא דנאמן ברישא משום דהוו בידו ולישנא דברייתא הכי דייק דקאמר היה עושה עמו בטהרות ואמר ליה דמדקתני עושה עמו משמע שהיו מסורות בידו ודייק רבינו לכתוב וא״ל נתפגלו ולא כתב וא״ל זבחים שעשיתי עמך נתפגלו כדקתני בברייתא כדי לרמוז יותר על התכיפות לומר דבעודו עושה בזבחים שעדיין היו בידו א״ל נתפגלו וכן נראה מדבריו בפ״א מהלכות תפילין שפוסק כאביי. ונראה שהראב״ד כמפרש דברי רבינו כתב כל שבידו נאמן וע״פ מ״ש דטעמא דפסק כאביי משום דעובדא דרבי אמי דמייתי התם משמע דלא כרבא ודברי רבינו בפ״א מהל' תפילין הכי משמע. ונראה עוד שרבינו אינו מפרש כל שבידו כפירש״י מדסתים לה סתומי אלא כפירוש הראב״ד. ועדיין נשאר לדקדק בדברי רבינו בסיפא למה האריך ולא סתם וכתב אינו נאמן כלישנא דברייתא ונראה שטעמו משום דקשיא ליה על הך סיפא דקתני אינו נאמן מדמשמע בקידושין פרק האומר (דף ס״ה) דבין לאביי בין לרבא אם א״ל ע״א נטמאו טהרותיך והלה שותק נאמן ואע״ג דאינו בידו, וניחא ליה דהתם מיירי כשהוא נאמן לו.",1,0],[19,15,"ומ\"ש ואם לאו שורת הדין שאינו נאמן וכו'. נראה שטעמו מדאמרינן בפ' הניזקין ההוא דאמר לחבריה טהרות שעשיתי עמך ביום פלוני נטמאו אתא לקמיה דרבי אמי אמר ליה שורת הדין אינו נאמן אמר לפניו רבי אסי רבי אתה אומר כן הכי אמר ר' יוחנן משום ר' יוסי מה אעשה שהתורה האמינתו היכן האמינתו אמר ר' יצחק בר ביסנא כה\"ג ביה\"כ יוכיח דכי אמר פיגול מהימן ומנא ידעינן והא כתיב וכל אדם לא יהיה באהל מועד אלא לאו משום דמהימן וכו' ודילמא דחזיניה בפשפש קשיא, ומדאמר שורת הדין אינו נאמן משמע דה\"ק הרוצה לנהוג כפי הדין אינו נאמן אבל הרוצה להחמיר לעצמו הרי זה משובח ועוד דר' יוחנן אמר משום ר' יוסי מה אעשה שהתורה האמינתו ואע\"ג דאסיקנא בקשיא מכ\"מ יש לחוש לו לומר שהמחמיר על עצמו הר\"ז משובח. אחר שכתבתי כל זה מצאתי לרבינו שכתב בסוף הל' מטמאי משכב ומושב כדברי רבא ולכן נ\"ל שרבינו מפרש דאביי ורבא לא פליגי לענין דינא אלא בפירושא דברייתא היכי מייתבא שפיר טפי ולכך כתב רבינו דברי שניהם וסמך כאן על מ\"ש שם ושם סמך על מ\"ש כאן:",2,0],[19,15,"סליקו להו הלכות פסולי המוקדשין בס\"ד:",3,0]]);
